/// `lua.d.new_jump_party`, `lua.d.get_map_index`, `lua.d.setf`, `lua.d.getf`,
/// `lua.d.getf_from_map_index`, `lua.d.spawn_mob`, `lua.d.notice`,
/// `lua.d.set_warp_location`, `lua.d.exit_all`, `lua.server_timer`,
/// `lua.clear_server_timer`, `lua.get_server_timer_arg`, `lua.game.set_event_flag`,
/// `lua.pc.in_dungeon`, `lua.pc.remove_item`, `lua.pc.get_channel_id`: Alice leads a
/// party with Yankee beside the forest guardian, each holding the ticket (30613).
/// Alice clicks and says "Da": the tickets are taken, the dungeon of map 210 is
/// created, and both are warped to its entry (782400, 1502100). Both reconnect:
/// the forest login consumes the entry mark silently, and the probe login arms the
/// report and the two exits. The report selects the dungeon by the timer's argument
/// and notices the stored leader, the flag by both reads, and the set event flag,
/// and a dog stands at the party's feet. The first exit was cleared and never fires;
/// the second notices and sends both home to (470000, 950000).
fn forest_world() -> Option<(Server, ScratchDatabase, PathBuf)> {
    forest_world_with_probe(DUNGEON_PROBE)
}

/// [`forest_world`] with the probe bytes it installs, for a quest that arms its own timers.
fn forest_world_with_probe(probe: &[u8]) -> Option<(Server, ScratchDatabase, PathBuf)> {
    let database = ScratchDatabase::create()?;
    let npc = "locale/europe/map/metin2_map_a1/npc.txt";
    let mut npc_text = std::fs::read(
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../legacy/gamedata")
            .join(npc),
    )
    .expect("the owner's npc.txt");
    npc_text.extend_from_slice(b"m\t600\t525\t0\t0\t0\t1\t1s\t100\t1\t20412\n");
    let channels = vec![
        ChannelSpec {
            number: 1,
            listeners: 2,
            maps: vec![1, 3, 210],
        },
        ChannelSpec {
            number: 99,
            listeners: 1,
            maps: vec![72],
        },
    ];
    let (server, root) = Server::start_with_files_channels(
        binary(),
        database.url(),
        &[
            (npc, &npc_text),
            ("locale/europe/quest/zz_probe/dungeon_probe.lua", probe),
        ],
        &channels,
        "no_wander = true",
    );
    create_account(&server, "alice");
    create_account(&server, "bob");
    add_characters(&database);
    sql(&database, "UPDATE account SET empire = 1");
    sql(
        &database,
        "INSERT INTO player (account_id, slot, name, job, level, x, y) SELECT id, 0, 'Yankee', 1, \
 154, 469700, 949600 FROM account WHERE login = 'bob'",
    );
    sql(
        &database,
        "UPDATE player SET x = 469600, y = 949500 WHERE name = 'Alpha'",
    );
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 20, id, 1, 0, 1, \
 30613 FROM player WHERE name = 'Alpha'",
    );
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 21, id, 1, 0, 1, \
 30613 FROM player WHERE name = 'Yankee'",
    );
    Some((server, database, root))
}

/// The forest party's two clients and what the dialog leaves behind.
struct ForestParty {
    alice: Keyed,
    yankee: Keyed,
    alpha: Listed,
    yankee_listed: Listed,
    alice_key: u32,
    yankee_key: u32,
    alpha_vid: u32,
    yankee_vid: u32,
    port: u16,
}

fn forest_party_forms(server: &Server) -> (ForestParty, u32) {
    let (_auth_alice, alice_key) = login_key(server, b"alice");
    let mut alice = Keyed::channel(server.channel(1));
    let (_empire, list) =
        login_by_key(&mut alice, b"alice", alice_key, CLIENT_KEY).expect("alice logs in");
    let (alpha, quickslots, _items) = load_selected(&mut alice, &list, 0);
    assert_eq!(quickslots, Vec::<Vec<u8>>::new(), "no quickslot is stored");
    let (alpha_vid, _guardian) = enter_beside_shown(&mut alice, 20412);
    drain_guardian_login_walk(&mut alice, 1);
    let (_auth_yankee, yankee_key) = login_key(server, b"bob");
    let mut yankee = Keyed::channel(server.channel(1));
    let (_empire, list) =
        login_by_key(&mut yankee, b"bob", yankee_key, CLIENT_KEY).expect("yankee logs in");
    let (yankee_listed, quickslots, _yankee_items) = load_selected(&mut yankee, &list, 0);
    assert_eq!(quickslots, Vec::<Vec<u8>>::new(), "no quickslot is stored");
    let (yankee_vid, guardian) = enter_beside_shown(&mut yankee, 20412);
    alice.read_game();
    drain_guardian_login_walk(&mut yankee, 3);
    let mut invite = vec![CG_PARTY_INVITE];
    invite.extend_from_slice(&yankee_vid.to_le_bytes());
    alice.send_record(&invite);
    let asked = yankee.read_game();
    assert_eq!(
        asked[0], GC_PARTY_INVITE,
        "the invite asks the guest: {asked:02x?}"
    );
    let mut answer = vec![CG_PARTY_INVITE_ANSWER];
    answer.extend_from_slice(&alpha_vid.to_le_bytes());
    answer.push(1);
    yankee.send_record(&answer);
    drain_party_walk(&mut yankee, "the guest", 3, 2, true);
    drain_party_walk(&mut alice, "the leader", 4, 2, true);
    (
        ForestParty {
            alice,
            yankee,
            alpha,
            yankee_listed,
            alice_key,
            yankee_key,
            alpha_vid,
            yankee_vid,
            port: 0,
        },
        guardian,
    )
}

/// Ledger 404: Yankee's disconnect, read to its removal. The removal proves the
/// disconnect was processed, so the logon claim is released and the new key logs in
/// with no race.
fn forest_yankee_disconnects(alice: &mut Keyed, yankee: Keyed, yankee_vid: u32) {
    drop(yankee);
    let mut removal = vec![GC_CHARACTER_DEL];
    removal.extend_from_slice(&yankee_vid.to_le_bytes());
    loop {
        let record = alice.read_game();
        if record[0] == GC_CHARACTER_DEL {
            assert_eq!(record, removal, "Yankee disconnects");
            break;
        }
        assert!(
            matches!(
                record[0],
                GC_PARTY_ADD
                    | GC_PARTY_LINK
                    | GC_PARTY_UNLINK
                    | GC_PARTY_UPDATE
                    | GC_PARTY_PARAMETER
                    | GC_OWNERSHIP
                    | GC_CHARACTER_UPDATE
            ),
            "the trailing fan and the release first: {record:02x?}"
        );
    }
}

/// Ledger 404: Yankee takes the second empire. The empire update lands between the
/// drop and the login, and the save the drop queued never touches the account's empire.
/// Yankee's vid is its player id, so it survives; Alice reads the relink fan and the
/// view pair, with the revive-expiry look update allowed throughout (her own revive ends
/// mid-relog).
fn forest_yankee_takes_the_second_empire(
    server: &Server,
    database: &ScratchDatabase,
    party: ForestParty,
) -> ForestParty {
    let ForestParty {
        mut alice,
        yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key: _,
        alpha_vid,
        yankee_vid,
        port,
    } = party;
    forest_yankee_disconnects(&mut alice, yankee, yankee_vid);
    sql(
        database,
        "UPDATE account SET empire = 2 WHERE login = 'bob'",
    );
    let (_auth, yankee_key) = login_key(server, b"bob");
    let mut yankee = Keyed::channel(server.channel(1));
    let (_empire, list) =
        login_by_key(&mut yankee, b"bob", yankee_key, CLIENT_KEY).expect("yankee logs in again");
    let (again, quickslots, _items) = load_selected(&mut yankee, &list, 0);
    assert_eq!(again.id, yankee_listed.id, "the same Yankee");
    assert_eq!(quickslots, Vec::<Vec<u8>>::new(), "no quickslot is stored");
    let own = enter_game_view(&mut yankee);
    assert_eq!(
        own.add[1..5],
        yankee_vid.to_le_bytes(),
        "the vid is the player id"
    );
    // The relink fan lands before the view pair; the revive's entry is the timer's own
    // and filtered, and its restate and expiry reads wait for the dialog's own loops.
    for head in [GC_PARTY_ADD, GC_PARTY_LINK, GC_PARTY_UPDATE] {
        let record = loop {
            let record = alice.read_game();
            if record[0] == GC_CHARACTER_UPDATE {
                continue;
            }
            break record;
        };
        assert_eq!(record[0], head, "the relink fans {head}");
    }
    // Alice's own revive ends mid-relog, so its expiry look update is allowed past.
    let mut record = loop {
        let record = alice.read_game();
        if record[0] == GC_CHARACTER_UPDATE {
            continue;
        }
        break record;
    };
    if record[0] == GC_WALK_MODE {
        assert_eq!(
            record,
            walk_mode_of(&yankee_vid.to_le_bytes()),
            "the newcomer walks"
        );
        record = loop {
            let record = alice.read_game();
            if record[0] == GC_CHARACTER_UPDATE {
                continue;
            }
            break record;
        };
    }
    assert_eq!(record[0], GC_CHARACTER_ADD, "{record:02x?}");
    assert_eq!(&record[1..5], &yankee_vid.to_le_bytes(), "the insert's vid");
    let info = loop {
        let record = alice.read_game();
        if record[0] == GC_CHARACTER_UPDATE {
            continue;
        }
        break record;
    };
    assert_eq!(info[0], GC_CHAR_ADDITIONAL_INFO, "{info:02x?}");
    assert_eq!(&info[1..5], &yankee_vid.to_le_bytes(), "the summary's vid");
    ForestParty {
        alice,
        yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port,
    }
}

fn forest_dialog_spends_the_tickets(party: ForestParty, guardian: u32) -> ForestParty {
    let ForestParty {
        mut alice,
        yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port: _,
    } = party;
    alice.send_record(&client_click(guardian));
    let chat = loop {
        let record = alice.read_game();
        if record[0] == GC_SCRIPT {
            break record;
        }
        // Ledger 404's relog replants Yankee's revive, whose expiry look update lands
        // mid-dialog; its remove is the revive timer's own and filtered.
        assert!(
            matches!(
                record[0],
                GC_PARTY_ADD
                    | GC_PARTY_LINK
                    | GC_PARTY_UPDATE
                    | GC_PARTY_PARAMETER
                    | GC_CHARACTER_UPDATE
            ),
            "ahead of the dialog: {record:02x?}"
        );
    };
    assert_eq!(
        chat,
        server_script(1, b"[QUESTION 1;Camera lui Bagjanamu|2;Inchide]"),
        "the one chat, and the close"
    );
    alice.send_record(&client_script_answer(0));
    let ask = titled_page(
        b"Lider Gardian P\xe3dure",
        &[b"", b"Vrei sa lupti in potriva lui Bagjanamu?"],
        b"[QUESTION 1;Da|2;Nu]",
    );
    assert_eq!(alice.read_game(), server_script(1, &ask));
    alice.send_record(&client_script_answer(0));
    let continued = titled_page(
        b"Lider Gardian P\xe3dure",
        &[
            b"",
            b"Dupa continuare toti membrii grupului",
            b"vor fii teleportati in camera.",
        ],
        b"[NEXT]",
    );
    let page = loop {
        let record = alice.read_game();
        if record[0] == GC_SCRIPT {
            break record;
        }
    };
    assert_eq!(page, server_script(1, &continued));
    let cleared = alice.read_game();
    assert_eq!(cleared[0], ITEM_SET, "the take clears the leader's cell");
    assert_eq!(cleared.len(), ITEM_SET_LEN);
    assert_eq!(cleared[1], 1, "the ticket stood in the inventory");
    assert_eq!(u16::from_le_bytes([cleared[2], cleared[3]]), 0);
    assert_eq!(
        u32::from_le_bytes([cleared[4], cleared[5], cleared[6], cleared[7]]),
        0
    );
    alice.send_record(&client_script_answer(254));
    assert_eq!(
        alice.read_game(),
        server_script(0, b"[DONE]"),
        "the dialog ends as the dungeon is made"
    );
    // The create stands and both jump: the party updates, the removal, then the
    // warp to the entry.
    ForestParty {
        alice,
        yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port: 0,
    }
}

fn forest_jump_lands_at_the_entry(
    server: &Server,
    database: &ScratchDatabase,
    party: ForestParty,
) -> ForestParty {
    let ForestParty {
        mut alice,
        mut yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port: _,
    } = party;
    let port = server.channel(1).port();
    for (who, vid) in [(&mut alice, alpha_vid), (&mut yankee, yankee_vid)] {
        let mut removed = vec![GC_CHARACTER_DEL];
        removed.extend_from_slice(&vid.to_le_bytes());
        let got = loop {
            let record = who.read_game();
            if record[0] == GC_CHARACTER_DEL {
                break record;
            }
            if record[0] == ITEM_SET {
                assert_eq!(record.len(), ITEM_SET_LEN);
                assert_eq!(record[1], 1, "the ticket stood in the inventory");
                assert_eq!(u16::from_le_bytes([record[2], record[3]]), 0);
                assert_eq!(
                    u32::from_le_bytes([record[4], record[5], record[6], record[7]]),
                    0,
                    "the take clears the member's cell"
                );
                continue;
            }
            // Ledger 404's relog replants Yankee's revive, whose expiry look update lands
            // mid-jump; its remove is the revive timer's own and filtered.
            assert!(
                matches!(
                    record[0],
                    GC_PARTY_UPDATE | GC_PARTY_UNLINK | GC_PARTY_PARAMETER | GC_CHARACTER_UPDATE
                ),
                "the jump syncs the party first: {record:02x?}"
            );
        };
        assert_eq!(got, removed, "EncodeRemovePacket(this)");
        assert_eq!(
            who.read_game(),
            a_warp_record((782_400, 1_502_100), port),
            "the jump lands at the entry"
        );
    }
    wait_for(
        database,
        "(SELECT count(*) FROM item WHERE vnum = 30613) = 0",
    );
    check(
        database,
        "(SELECT map_index FROM player WHERE name = 'Alpha') = 2100000 AND (SELECT map_index \
 FROM player WHERE name = 'Yankee') = 2100000",
    );
    // Both come back on the dungeon's map, at the entry.
    alice = Keyed::channel(server.channel(1));
    let (_empire, list) =
        login_by_key(&mut alice, b"alice", alice_key, CLIENT_KEY).expect("the key logs in again");
    let _loaded = load_selected(&mut alice, &list, 0);
    let own = enter_game_view(&mut alice);
    assert_eq!(
        inserted_at(&own.add),
        (782_400, 1_502_100),
        "Alpha enters the dungeon at the entry"
    );
    yankee = Keyed::channel(server.channel(1));
    let (_empire, list) =
        login_by_key(&mut yankee, b"bob", yankee_key, CLIENT_KEY).expect("the key logs in again");
    let _loaded = load_selected(&mut yankee, &list, 0);
    let own = enter_game_view(&mut yankee);
    assert_eq!(
        inserted_at(&own.add),
        (782_400, 1_502_100),
        "Yankee enters the dungeon at the entry"
    );
    // The report selects the dungeon by the timer's argument and notices what the
    // forest stored; a dog stands at the party's feet. Yankee's enter links the
    // party on the dungeon's map and shows him to Alpha first, so the links and
    // the view are read past.
    ForestParty {
        alice,
        yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port,
    }
}

fn forest_report_names_the_dungeon(party: ForestParty) -> ForestParty {
    let ForestParty {
        mut alice,
        mut yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port,
    } = party;
    let leader = format!("flag {}", alpha.id);
    let byidx = format!("byidx {}", alpha.id);
    for (who, what) in [(&mut alice, "Alpha"), (&mut yankee, "Yankee")] {
        let index = loop {
            let record = who.read_game();
            if record[0] == GC_CHAT {
                break record;
            }
            assert!(
                matches!(
                    record[0],
                    GC_PARTY_ADD
                        | GC_PARTY_LINK
                        | GC_PARTY_UNLINK
                        | GC_PARTY_UPDATE
                        | GC_CHARACTER_ADD
                        | GC_CHAR_ADDITIONAL_INFO
                        | GC_CHARACTER_UPDATE
                        | GC_WALK_MODE
                ),
                "{what} hears the party link first: {record:02x?}"
            );
        };
        assert_eq!(
            index,
            chat_packet(CHAT_TYPE_NOTICE, 1, b"dungeon 2100000"),
            "{what} hears the index"
        );
        assert_eq!(
            who.read_game(),
            chat_packet(CHAT_TYPE_NOTICE, 1, leader.as_bytes()),
            "{what} hears the stored leader"
        );
        assert_eq!(
            who.read_game(),
            chat_packet(CHAT_TYPE_NOTICE, 1, byidx.as_bytes()),
            "{what} hears the leader by index"
        );
        assert_eq!(
            who.read_game(),
            chat_packet(CHAT_TYPE_NOTICE, 1, b"evt 1"),
            "{what} hears the set event flag"
        );
        assert_eq!(
            who.read_game(),
            chat_packet(CHAT_TYPE_NOTICE, 1, b"ch 1"),
            "{what} hears the dungeon's channel"
        );
    }
    ForestParty {
        alice,
        yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port,
    }
}

fn forest_dog_stands_at_the_partys_feet(party: ForestParty) -> ForestParty {
    let ForestParty {
        mut alice,
        mut yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port,
    } = party;
    for (who, what) in [(&mut alice, "Alpha"), (&mut yankee, "Yankee")] {
        // Raw: `read_game` filters a monster's insert as a boot die's doing.
        let dog = loop {
            let record = who.read_game_raw();
            if is_heartbeat_record(&record) {
                continue;
            }
            if record[0] == GC_CHARACTER_ADD {
                break record;
            }
            assert!(
                matches!(
                    record[0],
                    GC_CHAT
                        | GC_PARTY_ADD
                        | GC_PARTY_LINK
                        | GC_PARTY_UNLINK
                        | GC_PARTY_UPDATE
                        | GC_PARTY_PARAMETER
                ),
                "{what} hears nothing else first: {record:02x?}"
            );
        };
        assert_eq!(
            &dog[22..24],
            &101u16.to_le_bytes(),
            "{what} sees the dog: {dog:02x?}"
        );
    }
    ForestParty {
        alice,
        yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port,
    }
}

/// Ledger 404: `d.new_jump` (`G/questlua_dungeon.cpp:318-347`). No owner quest calls it —
/// its only caller is the library's `warpToDungeon`
/// (`quest/luaLibrary/dungeonFunctions.lua:262`), which no quest calls — so the probe calls
/// it in the library's global numbers, unscaled, where `d.new_jump_party` scales its own
/// (`G/dungeon.cpp:398-399`).
///
/// Yankee logs in alone and enters map 1; its login takes its own dungeon, and its own
/// removal and the warp to the forest's entry follow the burst. The row names the first
/// free copy, and Yankee comes back on the dungeon's map at the entry, where the login
/// stays quiet.
#[test]
fn a_solo_login_takes_its_own_dungeon_at_the_entry() {
    let Some((server, database, _root)) = forest_world_with_probe(SOLO_PROBE) else {
        return;
    };
    let (_auth, key) = login_key(&server, b"bob");
    let mut yankee = Keyed::channel(server.channel(1));
    let (_empire, list) =
        login_by_key(&mut yankee, b"bob", key, CLIENT_KEY).expect("yankee logs in");
    let (yankee_listed, quickslots, _items) = load_selected(&mut yankee, &list, 0);
    assert_eq!(quickslots, Vec::<Vec<u8>>::new(), "no quickslot is stored");
    let own = enter_game_shown(&mut yankee);
    read_login_event(&mut yankee);
    let id = yankee_listed.id.to_le_bytes();
    assert_eq!(own.add[1..5], id, "the insert's vid");
    let mut removed = vec![GC_CHARACTER_DEL];
    removed.extend_from_slice(&id);
    assert_eq!(yankee.read_game(), removed, "EncodeRemovePacket(this)");
    let port = server.channel(1).port();
    assert_eq!(
        yankee.read_game(),
        a_warp_record((782_400, 1_502_100), port),
        "the solo jump lands at the entry"
    );
    wait_for(
        &database,
        "(SELECT map_index FROM player WHERE name = 'Yankee') = 2100000",
    );
    yankee = Keyed::channel(server.channel(1));
    let (_empire, list) =
        login_by_key(&mut yankee, b"bob", key, CLIENT_KEY).expect("the key logs in again");
    let _loaded = load_selected(&mut yankee, &list, 0);
    let own = enter_game_shown(&mut yankee);
    read_login_event(&mut yankee);
    assert_eq!(
        inserted_at(&own.add),
        (782_400, 1_502_100),
        "Yankee enters its dungeon at the entry"
    );
    yankee.quiet("the dungeon login stays quiet");
}

/// Ledger 404: the tail report's reads. The queues apply notices before spawns, so both
/// hear `spawned` and `cleared` back to back; then each sees the dog's insert (the
/// revive-expiry look update is allowed past, as the relog's own), its release, and its
/// death. Answers the party with the dog's vid.
fn forest_tail_kills_the_dog(party: ForestParty) -> (ForestParty, u32) {
    let ForestParty {
        mut alice,
        mut yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port,
    } = party;
    let mut dog = 0;
    for (who, what, empire) in [(&mut alice, "Alpha", 1), (&mut yankee, "Yankee", 2)] {
        let spawned = loop {
            let record = who.read_game();
            if record[0] == GC_CHAT {
                break record;
            }
            assert!(
                matches!(
                    record[0],
                    GC_PARTY_ADD
                        | GC_PARTY_LINK
                        | GC_PARTY_UNLINK
                        | GC_PARTY_UPDATE
                        | GC_CHARACTER_ADD
                        | GC_CHAR_ADDITIONAL_INFO
                        | GC_CHARACTER_UPDATE
                        | GC_WALK_MODE
                ),
                "{what} hears the party link first: {record:02x?}"
            );
        };
        assert_eq!(
            spawned,
            chat_packet(CHAT_TYPE_NOTICE, empire, b"spawned"),
            "{what} hears the spawn"
        );
        assert_eq!(
            who.read_game(),
            chat_packet(CHAT_TYPE_NOTICE, empire, b"cleared"),
            "{what} hears the kill"
        );
        // Raw: `read_game` filters a monster's insert as a boot die's doing.
        let insert = loop {
            let record = who.read_game_raw();
            if is_heartbeat_record(&record) {
                continue;
            }
            if record[0] == GC_CHARACTER_ADD {
                break record;
            }
            assert!(
                matches!(
                    record[0],
                    GC_PARTY_ADD
                        | GC_PARTY_LINK
                        | GC_PARTY_UNLINK
                        | GC_PARTY_UPDATE
                        | GC_PARTY_PARAMETER
                        | GC_CHARACTER_UPDATE
                ),
                "{what} hears nothing else first: {record:02x?}"
            );
        };
        assert_eq!(
            &insert[22..24],
            &101u16.to_le_bytes(),
            "{what} sees the dog: {insert:02x?}"
        );
        let vid = u32::from_le_bytes(insert[1..5].try_into().expect("a VID"));
        if dog == 0 {
            dog = vid;
        }
        assert_eq!(vid, dog, "{what} sees the same dog");
        assert_eq!(
            who.read_game(),
            ownership_of(0, dog),
            "{what} hears the dog's release"
        );
        assert_eq!(who.read_fight(), dead_of(dog), "{what} hears the dog die");
    }
    (
        ForestParty {
            alice,
            yankee,
            alpha,
            yankee_listed,
            alice_key,
            yankee_key,
            alpha_vid,
            yankee_vid,
            port,
        },
        dog,
    )
}

/// Ledger 404: the home reenter's letter pass. No quest moved, so [`read_login_letters`]
/// returns after the login pass without its peek; the letter pass's re-sends — the
/// replaced sash mark and the two letters again — arrive only for a character whose
/// marks survived: a warp departure keeps them, while the relog's logout forgot them,
/// so Alpha re-marks and Yankee goes straight to the update. Reads the delete, the
/// create naming Theowahdan on a nonzero VID, and the letters, or nothing.
fn read_home_marks(who: &mut Keyed, what: &str) {
    let next = who
        .read_game_until(std::time::Instant::now() + QUIET_WINDOW)
        .expect("the update or the old mark");
    if next[0] == GC_CHARACTER_UPDATE {
        who.unread(vec![next]);
        return;
    }
    who.unread(vec![next]);
    let delete = who.read_game();
    assert_eq!(
        delete[0], GC_QUEST_TARGET_DELETE,
        "{what} drops the old mark: {delete:02x?}"
    );
    assert_eq!(delete.len(), 5, "{what} drops one id");
    let create = who.read_game();
    assert_eq!(
        create[0], GC_QUEST_TARGET_CREATE,
        "{what} marks again: {create:02x?}"
    );
    let mut field = [0; 33];
    field[..b"Theowahdan".len()].copy_from_slice(b"Theowahdan");
    assert_eq!(&create[5..38], &field[..], "{what} marks Theowahdan");
    assert_ne!(
        u32::from_le_bytes(create[38..42].try_into().expect("a VID")),
        0,
        "{what} marks a VID that stands"
    );
    read_letter(who, QUEST_SASH, b"A special cloth", "the sash's return");
    read_letter(
        who,
        QUEST_YOHARA,
        b"Statuia Razboinicului",
        "the statue's return",
    );
}

/// Ledger 404: a home reenter after the tail exit: the key logs in again, the load
/// selects, and the enter reads the burst with the home letter pass, landing rewarped
/// off the blocked cell.
fn forest_home_reenter(server: &Server, login: &[u8], key: u32, what: &str) -> Keyed {
    let mut who = Keyed::channel(server.channel(1));
    let (_empire, list) =
        login_by_key(&mut who, login, key, CLIENT_KEY).expect("the key logs in again");
    let _loaded = load_selected(&mut who, &list, 0);
    let own = enter_game_shown(&mut who);
    read_login_lines(&mut who, 0, None);
    let _marks = read_login_letters(&mut who, true);
    read_home_marks(&mut who, what);
    read_login_update(&mut who);
    assert_eq!(
        inserted_at(&own.add),
        (470_100, 950_000),
        "{what} enters back home, rewarped off the blocked cell"
    );
    who
}

/// Ledger 404: the tail exit's reads. Both hear `going` (the dungeon revives end in the
/// wait, so the expiry look update is allowed past; the dead dog goes a second after it
/// died, its release and removal read past), leave, land back home, and come back on
/// map 1.
fn forest_tail_sends_the_party_home(
    server: &Server,
    database: &ScratchDatabase,
    party: ForestParty,
    dog: u32,
) -> ForestParty {
    let ForestParty {
        mut alice,
        mut yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port,
    } = party;
    for (who, what, empire) in [(&mut alice, "Alpha", 1), (&mut yankee, "Yankee", 2)] {
        let going = loop {
            let record = who.read_game();
            if record[0] == GC_CHAT {
                break record;
            }
            if record[0] == GC_OWNERSHIP {
                assert_eq!(
                    record,
                    ownership_of(0, dog),
                    "{what} hears the dead dog's release"
                );
                continue;
            }
            if record[0] == GC_CHARACTER_DEL {
                assert_eq!(
                    &record[1..5],
                    &dog.to_le_bytes(),
                    "{what} hears the dead dog go"
                );
                continue;
            }
            assert!(
                matches!(
                    record[0],
                    GC_PARTY_ADD
                        | GC_PARTY_LINK
                        | GC_PARTY_UNLINK
                        | GC_PARTY_UPDATE
                        | GC_CHARACTER_UPDATE
                ),
                "{what} hears no exit but the tail's: {record:02x?}"
            );
        };
        assert_eq!(
            going,
            chat_packet(CHAT_TYPE_NOTICE, empire, b"going"),
            "{what} hears the tail exit"
        );
        let removal = who.read_game();
        assert_eq!(
            removal[0], GC_CHARACTER_DEL,
            "{what} leaves: {removal:02x?}"
        );
        assert_eq!(
            who.read_game(),
            a_warp_record((470_000, 950_000), port),
            "{what} lands back home"
        );
    }
    wait_for(
        database,
        "(SELECT map_index FROM player WHERE name = 'Alpha') = 1 AND (SELECT map_index FROM          player WHERE name = 'Yankee') = 1",
    );
    alice = forest_home_reenter(server, b"alice", alice_key, "Alpha");
    yankee = forest_home_reenter(server, b"bob", yankee_key, "Yankee");
    ForestParty {
        alice,
        yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port,
    }
}

/// Ledger 404: `d.clear_regen`, `d.kill_all`, `d.set_damage_from_race` and
/// `d.set_damage_from_affect` (`G/questlua_dungeon.cpp:235-243`, `:1231-1246`, `:902-938`).
/// Like `d.new_jump`, no owner quest calls them — only the library's uncalled `ClearDungeon`
/// and the never-loaded `questlib_extra.lua`'s uncalled tables — so the probe calls them:
/// at its dungeon login Alpha flags itself with all eight race bits and the polymorph
/// affect, and the report spawns a dog, clears the empty regen list, kills the dog, and
/// notices.
///
/// Yankee takes the second empire after the party forms (a relog: the PK policy runs in
/// its peaceful form, so only empires apart let a hit through), the party enters, the
/// tail kills the dog and sends both home. Back home Alpha's hit on the unflagged
/// Yankee lands, which proves the policy lets the next one through; Yankee's hit on the
/// flagged Alpha sends nothing.
#[test]
fn the_tail_kills_the_dog_and_the_flagged_hit_is_silent() {
    let Some((server, database, _root)) = forest_world_with_probe(TAIL_PROBE) else {
        return;
    };
    let (party, guardian) = forest_party_forms(&server);
    let party = forest_yankee_takes_the_second_empire(&server, &database, party);
    let party = forest_dialog_spends_the_tickets(party, guardian);
    let party = forest_jump_lands_at_the_entry(&server, &database, party);
    let (party, dog) = forest_tail_kills_the_dog(party);
    let party = forest_tail_sends_the_party_home(&server, &database, party, dog);
    let ForestParty {
        mut alice,
        mut yankee,
        yankee_vid,
        alpha_vid,
        ..
    } = party;
    // The control: Alpha's hit on the unflagged Yankee lands, past whatever the dice
    // proc first.
    alice.send_record(&client_attack(yankee_vid));
    let deadline = std::time::Instant::now() + Duration::from_secs(2);
    let landed = loop {
        let Some(record) = alice.read_game_until(deadline) else {
            break false;
        };
        if record[0] == GC_DAMAGE_INFO && record[1..5] == yankee_vid.to_le_bytes() {
            break true;
        }
    };
    assert!(landed, "the unflagged hit lands");
    while yankee
        .read_game_until(std::time::Instant::now() + QUIET_WINDOW)
        .is_some()
    {}
    // The flagged hit: Yankee's swing at Alpha sends nothing.
    yankee.send_record(&client_attack(alpha_vid));
    yankee.quiet("the flagged hit sends nothing");
}

#[test]
fn a_party_enters_the_forest_and_its_timer_sends_it_home() {
    let Some((server, database, _root)) = forest_world() else {
        return;
    };
    let (party, guardian) = forest_party_forms(&server);
    let party = forest_dialog_spends_the_tickets(party, guardian);
    let party = forest_jump_lands_at_the_entry(&server, &database, party);
    let party = forest_report_names_the_dungeon(party);
    let party = forest_dog_stands_at_the_partys_feet(party);
    let ForestParty {
        mut alice,
        mut yankee,
        port,
        ..
    } = party;
    // The cleared exit never fires; the second notices and sends both home.
    for (who, what) in [(&mut alice, "Alpha"), (&mut yankee, "Yankee")] {
        let second = loop {
            let record = who.read_game();
            if record[0] == GC_CHAT {
                break record;
            }
            assert!(
                matches!(
                    record[0],
                    GC_PARTY_ADD | GC_PARTY_LINK | GC_PARTY_UNLINK | GC_PARTY_UPDATE
                ),
                "{what} hears no exit but the second: {record:02x?}"
            );
        };
        assert_eq!(
            second,
            chat_packet(CHAT_TYPE_NOTICE, 1, b"second"),
            "{what} hears only the second exit"
        );
        let removal = who.read_game();
        assert_eq!(
            removal[0], GC_CHARACTER_DEL,
            "{what} leaves: {removal:02x?}"
        );
        assert_eq!(
            who.read_game(),
            a_warp_record((470_000, 950_000), port),
            "{what} lands back home"
        );
    }
    wait_for(
        &database,
        "(SELECT map_index FROM player WHERE name = 'Alpha') = 1 AND (SELECT map_index FROM \
 player WHERE name = 'Yankee') = 1",
    );
}
/// The records that may ride ahead of the forest returns' own: the relink's walk and the
/// view's own inserts and updates.
fn forest_return_noise(head: u8) -> bool {
    matches!(
        head,
        GC_PARTY_ADD
            | GC_PARTY_LINK
            | GC_PARTY_UNLINK
            | GC_PARTY_UPDATE
            | GC_PARTY_PARAMETER
            | GC_CHARACTER_ADD
            | GC_CHAR_ADDITIONAL_INFO
            | GC_CHARACTER_UPDATE
            | GC_WALK_MODE
            | GC_OWNERSHIP
    )
}

/// Both members hear the landing `back` two seconds on.
fn forest_both_hear_the_landing(mut party: ForestParty) -> ForestParty {
    for (who, what) in [(&mut party.alice, "Alpha"), (&mut party.yankee, "Yankee")] {
        let back = loop {
            let record = who.read_game();
            if record[0] == GC_CHAT {
                break record;
            }
            assert!(
                forest_return_noise(record[0]),
                "{what} hears the landing first: {record:02x?}"
            );
        };
        assert_eq!(
            back,
            chat_packet(CHAT_TYPE_NOTICE, 1, b"back"),
            "{what} hears the landing"
        );
    }
    party
}

/// One party tick runs with both linked inside, nearing Yankee; its update proves it.
fn forest_tick_nears_while_both_inside(mut party: ForestParty) -> ForestParty {
    std::thread::sleep(std::time::Duration::from_secs(4));
    for _ in 0..32 {
        let record = party.yankee.read_game();
        if record[0] == GC_PARTY_UPDATE {
            break;
        }
        assert!(
            forest_return_noise(record[0]),
            "ahead of the tick: {record:02x?}"
        );
    }
    party
}

/// The leader's wire is gone; Yankee's carries its own warp home. Alpha's own removal
/// may or may not arrive first: the warp queues to Yankee's session while the removal
/// fans from the game thread, and the warp-leave drops Yankee's pending outbox with
/// it. A stranger's removal still fails. The `RemoveBonus` fan zeroes Yankee's role
/// points through `ComputePoints` between the two.
fn forest_drop_warps_yankee_home(yankee: &mut Keyed, alpha_vid: u32, yankee_vid: u32, port: u16) {
    let mut removed_self = false;
    let mut warped = false;
    for _ in 0..32 {
        if removed_self && warped {
            break;
        }
        let record = yankee.read_game();
        if record[0] == GC_CHARACTER_DEL {
            let vid = u32::from_le_bytes(record[1..5].try_into().expect("four bytes"));
            if vid == alpha_vid {
                continue;
            }
            assert_eq!(vid, yankee_vid, "no stranger leaves: {record:02x?}");
            removed_self = true;
            continue;
        }
        if record[0] == GC_WARP {
            assert_eq!(
                record,
                a_warp_record((469_700, 949_600), port),
                "Yankee warps to its saved exit"
            );
            warped = true;
            continue;
        }
        assert!(
            forest_return_noise(record[0]) || record[0] == GC_POINT_CHANGE,
            "behind the disconnect: {record:02x?}"
        );
    }
    assert!(removed_self && warped, "Yankee sees its warp home");
}

/// Alpha lands home beside Yankee, so Yankee reads the arrive: the insert, its info
/// and the entrant's revive entry and restate, as `drain_leader_relog` does.
fn forest_yankee_sees_alpha_arrive(yankee: &mut Keyed, alpha_vid: u32) {
    let add = yankee.read_game();
    assert_eq!(
        add[0], GC_CHARACTER_ADD,
        "yankee sees the arrive: {add:02x?}"
    );
    assert_eq!(&add[1..5], &alpha_vid.to_le_bytes(), "the insert's vid");
    let info = yankee.read_game();
    assert_eq!(info[0], GC_CHAR_ADDITIONAL_INFO, "{info:02x?}");
    let entry = yankee.read_game_raw();
    assert!(
        yankee.timer_record(&entry),
        "the entrant's entry is the timer's: {entry:02x?}"
    );
    let restate = yankee.read_game_raw();
    assert!(
        yankee.timer_restate(&restate),
        "the entrant's login update restates its entry: {restate:02x?}"
    );
}

/// `sys.dungeon.core`: the leader's disconnect sends the near home, and the relog comes
/// home. A party of two jumps into the forest; both hear the landing `back`. Past one
/// party tick the leader disconnects, and the near Yankee is warped to its saved exit
/// (`FExitDungeon`, `G/party.cpp:655-661`) while its row goes home to map 1. Alpha's
/// relog lands home too: the row names the dungeon, so the login re-seeds the pending
/// warp from the exit (`SetPlayerProto`, `G/char.cpp:2289-2294`). Yankee quits at once,
/// disbanding the pair, and the quiets prove no `back` reaches the outsiders.
#[test]
fn a_leader_disconnect_sends_the_near_home_and_the_relog_comes_home() {
    let Some((server, database, _root)) = forest_world_with_probe(RETURN_PROBE) else {
        return;
    };
    let (party, guardian) = forest_party_forms(&server);
    let party = forest_dialog_spends_the_tickets(party, guardian);
    let party = forest_jump_lands_at_the_entry(&server, &database, party);
    let party = forest_both_hear_the_landing(party);
    let party = forest_tick_nears_while_both_inside(party);
    let ForestParty {
        alice,
        mut yankee,
        alpha,
        yankee_listed,
        alice_key,
        yankee_key,
        alpha_vid,
        yankee_vid,
        port,
    } = party;
    // The leader disconnects; Yankee's wire carries its own warp home.
    drop(alice);
    forest_drop_warps_yankee_home(&mut yankee, alpha_vid, yankee_vid, port);
    // Both stand offline, so one Update tick fires to nobody and the next is three
    // seconds out: Yankee's enter below runs in a tick-free window, and the pulled
    // walk is the link's own.
    std::thread::sleep(std::time::Duration::from_millis(3_500));
    // Yankee re-enters home on map 1, at its saved exit, relinked to a party of two
    // with an offline leader.
    yankee = Keyed::channel(server.channel(1));
    let (_empire, list) =
        login_by_key(&mut yankee, b"bob", yankee_key, CLIENT_KEY).expect("the key logs in again");
    let _loaded = load_selected(&mut yankee, &list, 0);
    let members = [alpha.id, yankee_listed.id];
    let own = enter_game_view_partied(&mut yankee, &[yankee_listed.id], &members);
    assert_eq!(
        inserted_at(&own.add),
        (469_700, 949_600),
        "Yankee enters home at its exit"
    );
    check(
        &database,
        "(SELECT map_index FROM player WHERE name = 'Yankee') = 1",
    );
    // Yankee quits at once: a party of two disbands with no REMOVE, only the role
    // points' zeroes and their `ComputePoints` cascade (`:1717-1721`), and the party
    // is gone before Alpha's relog. The cascade's length varies with the recompute,
    // so the drain runs till the wire idles.
    yankee.send_record(&client_party_remove(yankee_listed.id));
    let idle = std::time::Instant::now() + std::time::Duration::from_millis(500);
    loop {
        let Some(record) = yankee.read_game_until(idle) else {
            break;
        };
        if record[0] != GC_POINT_CHANGE {
            yankee.pushed.insert(0, record);
            break;
        }
    }
    // Alpha's relog comes home, not back inside: the row names the dungeon, so the
    // login re-seeds the pending warp from the exit columns (`SetPlayerProto`,
    // `G/char.cpp:2289-2294`), which is legacy's end state too. No `back` can reach
    // either of them now: both left the present set, and no login inside arms the
    // timer again.
    let mut alice = Keyed::channel(server.channel(1));
    let (_empire, list) =
        login_by_key(&mut alice, b"alice", alice_key, CLIENT_KEY).expect("the key logs in again");
    let _loaded = load_selected(&mut alice, &list, 0);
    let own = enter_game_view(&mut alice);
    assert_eq!(
        inserted_at(&own.add),
        (469_600, 949_500),
        "Alpha enters home at its exit"
    );
    check(
        &database,
        "(SELECT map_index FROM player WHERE name = 'Alpha') = 1",
    );
    forest_yankee_sees_alpha_arrive(&mut yankee, alpha_vid);
    // With the party gone no Update tick can fall inside the quiets, so their silence
    // proves no `back` reaches the outsiders.
    alice.quiet_allowing_farm("no return reaches alpha");
    yankee.quiet_allowing_farm("no return reaches yankee");
}

/// `lua.ds.give_qualification`, `lua.ds.is_qualified`, `lua.ds.open_refine_window`,
/// `lua.ds.open_attr_change_window`: the alchemist (20001) stands on map 1, and Alpha
/// enters beside it. The login event grants the qualification (its `GC_AFFECT_ADD`
/// carries kind 540); Alpha clicks the alchemist, picks the refine chat, and the
/// dialog opens the refine window (209, sub 0). The attr-change chat's gate reads
/// qualified, and "Da" opens the one-byte 211 window.
#[test]
fn the_alchemists_chats_open_the_dragon_soul_windows_once_qualified() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start_with_npcs_configured(
        binary(),
        database.url(),
        "metin2_map_a1",
        "",
        "no_wander = true",
    );
    create_account(&server, "alice");
    add_characters(&database);
    sql(&database, "UPDATE account SET empire = 1");
    sql(
        &database,
        "UPDATE player SET x = 469600, y = 949500 WHERE name = 'Alpha'",
    );
    let (mut alice, _alpha, _items) = load_character(&server, b"alice", 0);
    let (_own, alchemist) = enter_beside_shown(&mut alice, 20001);
    // The login event granted the qualification: `read_login_lines` (inside the walk
    // drain) already read the infinite add between the hides and `event_info`'s line.
    drain_guardian_login_walk(&mut alice, 1);
    // The grant started the affect event, whose first tick may land in the walk's
    // quiet window: the revive timer's expiry (215's remove) and its update. The
    // click's read skips past them.
    alice.send_record(&client_click(alchemist));
    let chat = alice.read_script_past_ticks();
    assert_eq!(
        chat,
        server_script(
            1,
            b"[QUESTION 1;Schimbare Atributii Piatra Dragon|2;Rafinare Piatra Dragon|3;Inchide]",
        ),
        "the two chats, and the close"
    );
    // The refine chat: the gate reads qualified and the window opens.
    alice.send_record(&client_script_answer(1));
    let page = titled_page(
        b"Alchimist",
        &[b"Doresti sa rafinezi o Piatra Dragon? Mi se pare[ENTER]corect. Trebuie sa stii insa ca acest proces[ENTER]poate esua. Am auzit ca aceste boabe de Fasole[ENTER]Dragon pe care le gasesti in spatele monedei care[ENTER]se invarte cresc sansa de succes."],
        b"[DONE]",
    );
    loop {
        let record = alice.read_game();
        if record[0] == GC_SCRIPT {
            assert_eq!(record, server_script(1, &page), "the refine page");
            continue;
        }
        assert_eq!(
            record,
            vec![GC_DRAGON_SOUL_REFINE, 0, 1, 0xff, 0xff],
            "the open: {record:02x?}"
        );
        break;
    }
    // The attr-change chat: its `with` gate reads qualified, and "Da" opens 211.
    alice.send_record(&client_click(alchemist));
    let chat = alice.read_script_past_ticks();
    assert_eq!(
        chat,
        server_script(
            1,
            b"[QUESTION 1;Schimbare Atributii Piatra Dragon|2;Rafinare Piatra Dragon|3;Inchide]",
        ),
        "the two chats again, and the close"
    );
    alice.send_record(&client_script_answer(0));
    let ask = titled_page(
        b"Alchimist",
        &[b"Vrei sa deschizi schimbarea atributiilor pietrei dragon?"],
        b"[QUESTION 1;Da|2;Nu]",
    );
    assert_eq!(alice.read_game(), server_script(1, &ask));
    alice.send_record(&client_script_answer(0));
    assert_eq!(
        alice.read_game(),
        server_script(0, b"[DONE]"),
        "the answer ends the dialog"
    );
    assert_eq!(
        alice.read_game(),
        vec![GC_DS_PLUS_CHANGE_ATTR_OPEN],
        "the attr window opens"
    );
    alice.still("nothing follows");
}

/// `quest.yohara_manager`: the city statue (20433) stands on map 1, and Alpha,
/// level 154 with `yohara_system` at `killReward_new`, enters beside it. The
/// letter drains copy the return scenario's, whose seed this one shares. The
/// click offers the ship's return and the Yohara trip; "Un continent nou"
/// asks, "Da" reads `pc.get_conqueror_level()` 33 and the step orders the
/// warp to Yohara (537500, 492700). The refusal branch waits: Alpha's
/// conqueror level is 33, and no second quest gates on the read.
#[test]
fn a_yes_to_the_statues_yohara_trip_warps_to_yohara() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let mut channels = default_channels();
    channels[0].maps.push(374);
    let server = Server::start_with_npcs_channels(
        binary(),
        database.url(),
        "metin2_map_a1",
        "m\t600\t525\t0\t0\t0\t1\t1s\t100\t1\t20433\n",
        &channels,
        "no_wander = true",
    );
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "UPDATE player SET x = 469600, y = 949500 WHERE name = 'Alpha'",
    );
    // The CRC32 of `killReward_new`.
    sql(
        &database,
        "INSERT INTO quest_flag (player_id, name, value) SELECT player.id, \
         'yohara_system.__status'::bytea, -512007343 FROM player WHERE player.name = 'Alpha'",
    );
    let (mut alice, _alpha, _items) = load_character(&server, b"alice", 0);
    let (own, statue) = enter_beside_shown(&mut alice, 20433);
    read_login_lines(&mut alice, 0, None);
    read_letter(
        &mut alice,
        QUEST_ATTR67ADD,
        b"Sixth and Seventh Bonus",
        "item_attr67add",
    );
    let theowahdan = read_quest_target_create(&mut alice, 1, b"Theowahdan");
    read_letter(
        &mut alice,
        QUEST_SASH,
        b"A special cloth",
        "the sash's change",
    );
    let stale = alice.read_game();
    assert_eq!(
        stale,
        server_quest_target_delete(1),
        "the reward state's letter deletes its stale Overseer mark"
    );
    assert_eq!(
        alice.read_game(),
        server_quest_target_create(2, b"Theowahdan", theowahdan),
        "the letter pass marks him again"
    );
    read_letter(
        &mut alice,
        QUEST_SASH,
        b"A special cloth",
        "the sash's letter",
    );
    read_login_update(&mut alice);
    alice.still("nothing follows");

    alice.send_record(&client_click(statue));
    assert_eq!(
        alice.read_game(),
        server_script(1, b"[QUESTION 1;Return|2;Un continent nou|3;Inchide]"),
        "the ship's return and the yohara trip, and the close"
    );
    alice.send_record(&client_script_answer(1));
    let ask = titled_page(
        b"Savas\xe7i heykeli:",
        &[b"Doresti sa calatoresti pe noul continent Yohara?"],
        b"[QUESTION 1;Da|2;Nu]",
    );
    assert_eq!(alice.read_game(), server_script(1, &ask));
    alice.send_record(&client_script_answer(0));
    assert_eq!(alice.read_game(), server_script(0, b"[DONE]"));
    let mut removed = vec![GC_CHARACTER_DEL];
    removed.extend_from_slice(&own.to_le_bytes());
    assert_eq!(alice.read_game(), removed, "EncodeRemovePacket(this)");
    let port = server.channel(1).port();
    assert_eq!(
        alice.read_game(),
        a_warp_record((537_500, 492_700), port),
        "the yohara warp names its continent and Channel 1"
    );
    alice.still("nothing follows");
    check(
        &database,
        "(SELECT x FROM player WHERE name = 'Alpha') = 537500 AND (SELECT y FROM player WHERE \
         name = 'Alpha') = 492700",
    );
}

/// `quest.guild_ranking`: Alpha masters `MyGuild` (ladder 1000, seeded before the
/// boot) and stands by the guild man on map 1. The click offers the disband
