const FLAG618_PROBE: &[u8] = b"quest flag618_probe begin\n\
    state start begin\n\
    when 20300.click begin\n\
    local before = pc.getqf('__status')\n\
    set_state('away')\n\
    local after = pc.getqf('__status')\n\
    if before == 0 and after ~= 0 then\n\
    say('at-once')\n\
    else\n\
    say('deferred')\n\
    end\n\
    end\n\
    end\n\
    state away begin\n\
    when 20300.click begin\n\
    say('away')\n\
    end\n\
    end\n\
    end\n";

