/// `sys.item.proto`: the moonlight box (50011) draws its single group row over the
/// wire — the pickup notice, the gift's set, the spent box's clear, and the row's
/// line — with the gift one of the group's 29 rows.
#[test]
fn a_moonlight_box_draws_its_group_and_tells_the_gift() {
    /// The owner's 50011 rows: `(vnum, count)`, in file order.
    const ROWS: [(u32, u16); 29] = [
        (71084, 15),
        (50252, 1),
        (51505, 1),
        (51506, 1),
        (27987, 10),
        (51505, 1),
        (50128, 10),
        (30055, 2),
        (30060, 2),
        (30056, 2),
        (30058, 2),
        (30057, 2),
        (30059, 2),
        (30076, 1),
        (30003, 1),
        (30004, 1),
        (30005, 1),
        (25040, 5),
        (30078, 5),
        (30077, 1),
        (27992, 1),
        (27993, 1),
        (27994, 1),
        (30052, 1),
        (30048, 1),
        (30049, 1),
        (30046, 1),
        (30051, 1),
        (30053, 1),
    ];
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    add_characters(&database);
    sql(&database, "UPDATE account SET empire = 1");
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 60, id, 1, 0,          1, 50011 FROM player WHERE name = 'Alpha'",
    );
    let server = Server::start(binary(), database.url());
    let (mut alice, _) = enter_world(&server, b"alice", 0);
    alice.send_record(&client_item_use(0));
    let pickup = alice.read_game();
    assert_eq!(pickup[0], GC_CHAT, "the gift is picked up first");
    let pickup = &pickup[10..];
    let name = pickup
        .strip_prefix(b"[LS;444;")
        .and_then(|rest| rest.strip_suffix(b"]"))
        .expect("the pickup names the gift");
    let (window, cell, vnum, count) = set_fields(&alice.read_game());
    assert_eq!(window, 1, "the gift lands in the inventory window");
    assert!(
        cell == 1 || cell >= common::item_slots::CUSTOM_INVENTORY_SLOT_START,
        "the gift lands past the box or in its custom bank: {cell}"
    );
    assert!(
        ROWS.contains(&(vnum, count)),
        "the gift is a group row: ({vnum}, {count})"
    );
    assert_eq!(
        set_fields(&alice.read_game()),
        (1, 0, 0, 0),
        "the spent box clears"
    );
    let line = alice.read_game();
    assert_eq!(line[0], GC_CHAT, "the row tells its line");
    let mut want = Vec::from(b"[LS;".as_slice());
    if count > 1 {
        want.extend_from_slice(b"204;");
        want.extend_from_slice(name);
        want.extend_from_slice(b";");
        want.extend_from_slice(count.to_string().as_bytes());
    } else {
        want.extend_from_slice(b"35;");
        want.extend_from_slice(name);
    }
    want.push(b']');
    assert_eq!(&line[10..], want.as_slice(), "the line names the gift");
    alice.quiet("the draw tells nothing more");
}

/// `sys.item.proto`: the treasure key names a non-box (`[LS;1248]`), a missing box
/// silently, and its matching box with `[LS;46]` — no box group exists on the
/// owner's data, so the key and the box stay.
#[test]
fn a_key_names_a_non_box_a_missing_box_and_its_groupless_box() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    add_characters(&database);
    sql(&database, "UPDATE account SET empire = 1");
    for (id, vnum, pos) in [(60, 50008, 0), (61, 50006, 1), (62, 19, 2)] {
        sql(
            &database,
            &format!(
                "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT {id}, id,                  1, {pos}, 1, {vnum} FROM player WHERE name = 'Alpha'"
            ),
        );
    }
    let server = Server::start(binary(), database.url());
    let (mut alice, _) = enter_world(&server, b"alice", 0);
    alice.send_record(&client_use_to_item(0, 2));
    assert_eq!(&alice.read_game()[10..], b"[LS;1248]", "a non-box is named");
    alice.send_record(&client_use_to_item(0, 9));
    alice.quiet("a missing box is silent");
    alice.send_record(&client_use_to_item(0, 1));
    assert_eq!(&alice.read_game()[10..], b"[LS;46]", "no group, no draw");
    alice.quiet("the failure tells nothing more");
    let kept = support::rows(
        database.url(),
        "SELECT COUNT(*) FROM item WHERE owner_id = (SELECT id FROM player WHERE name =          'Alpha') AND vnum IN (50008, 50006)",
        1,
    );
    assert_eq!(kept[0][0], 2, "the key and the box stay");
}

/// The start step's burst after its script: the start's broadcast (the mast's
/// target HP), the wave's pair, the heal's own notice, the stun's flag update and
/// affect add, and the heal's broadcast again.
fn read_ship_start_burst(alice: &mut Keyed) {
    let target = alice.read_game();
    assert_eq!(target[0], GC_TARGET, "the mast HP broadcasts");
    let first = alice.read_game();
    assert_eq!(first[0], GC_CHAT, "the attack warning chats");
    let second = alice.read_game();
    assert_eq!(second[0], GC_CHAT, "the wave line chats");
    let notice = alice.read_game();
    assert_eq!(notice[0], GC_CHAT, "the mast HP chats");
    // The stun's flag update lands before its affect add.
    let flags = alice.read_game();
    assert_eq!(flags[0], GC_CHARACTER_UPDATE, "the stun flags land");
    let stun = alice.read_game();
    assert_eq!(stun[0], GC_AFFECT_ADD, "the reader stuns");
    let cast = alice.read_game();
    assert_eq!(cast[0], GC_TARGET, "the mast HP broadcasts again");
}

/// The Channels the ship defence runs on: Channel 1 hosts the cape (135), the ship
/// (358) and the port (359), the create's and the land's gates.
fn ship_channels() -> Vec<ChannelSpec> {
    vec![
        ChannelSpec {
            number: 1,
            listeners: 2,
            maps: vec![1, 3, 135, 358, 359],
        },
        ChannelSpec {
            number: 99,
            listeners: 1,
            maps: vec![72],
        },
    ]
}

/// `lua.ship_defense_mgr.create`, `lua.ship_defense_mgr.start`,
/// `lua.ship_defense_mgr.join`, `lua.ship_defense_mgr.leave`,
/// `lua.ship_defense_mgr.land`, `lua.ship_defense_mgr.is_created`,
/// `lua.ship_defense_mgr.is_running`, `lua.ship_defense_mgr.need_party`,
/// `lua.ship_defense_mgr.need_ticket`,
/// `lua.ship_defense_mgr.spawn_wood_repair`,
/// `lua.ship_defense_mgr.require_cooldown`,
/// `lua.ship_defense_mgr.set_alliance_hp_pct`, `lua.ship_defense_mgr.can_join`:
/// Alpha stands beside 9009 on the cape (135). Its board chats the four true
/// flags, the shadow pair around the create, and enters warped to the recall spot
/// on the run's index. Coming back, the wheel (20436) stands on the run; its start
/// chats the running read, heals the mast (the HP notice and the stun land), and
/// its land ships out to the port. (`ship_defense_mgr.join` needs a party, which
/// one client cannot form; the unit join pins the warp.)
#[test]
fn a_captain_boards_starts_and_lands_the_ship_defence() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    add_characters(&database);
    // 9009 of `Metin2_map_CapeDragonHead/npc.txt:9` stands at (838, 1187) times
    // 100 past the cape's base (1024000, 1664000).
    sql(
        &database,
        "UPDATE player SET map_index = 135, x = 1107800, y = 1782700 WHERE name = 'Alpha'",
    );
    let (server, _data) = Server::start_with_files_channels(
        binary(),
        database.url(),
        &[("locale/europe/quest/zz_probe/ship_probe.lua", SHIP_PROBE)],
        &ship_channels(),
        "no_wander = true",
    );
    let (mut alice, listed, entered) = enter_world_seeing(&server, b"alice", 0);
    let npc = shown_vid(&entered, 9009, "the cape shows 9009");
    alice.send_record(&client_click(npc));
    assert_eq!(
        alice.read_game(),
        server_script(1, b"[QUESTION 1;Apararea Navei!|2;probe board|3;Inchide]",),
        "the quest's chat, the probe's, and the close"
    );
    alice.send_record(&client_script_answer(1));
    assert_eq!(
        alice.read_game(),
        server_script(
            1,
            b"flags truetruetruetrue[ENTER]before false[ENTER]made true[ENTER][DONE]"
        ),
        "the flags and the shadow pair around the create"
    );
    let port = server.channel(1).port();
    let mut removed = vec![GC_CHARACTER_DEL];
    removed.extend_from_slice(&listed.id.to_le_bytes());
    assert_eq!(alice.read_game(), removed, "EncodeRemovePacket(this)");
    assert_eq!(
        alice.read_game(),
        a_warp_record((166_700, 522_300), port),
        "the recall spot on the run"
    );
    alice.quiet("the create step ends");
    wait_for(
        &database,
        "(SELECT map_index FROM player WHERE name = 'Alpha') = 3580000",
    );
    // Coming back, the wheel stands on the run: its start chats the running read,
    // heals the mast, and the HP notice and the stun land.
    drop(alice);
    let (mut alice, _character, _quickslots, _items) =
        load_with_quickslots_on(&server, 1, b"alice", 0, ENGLISH);
    let entered = enter_game_view(&mut alice);
    let wheel = shown_vid(&entered, 20436, "the run shows the wheel");
    alice.send_record(&client_click(wheel));
    assert_eq!(
        alice.read_game(),
        server_script(
            1,
            b"[QUESTION 1;Incepe Apararea Navei|2;Opreste Calatoria|3;probe start|4;probe land|5;Inchide]",
        ),
        "the quest's chats, the probes, and the close"
    );
    alice.send_record(&client_script_answer(2));
    assert_eq!(
        alice.read_game(),
        server_script(1, b"runs true[ENTER]healed[ENTER][DONE]"),
        "the running read and the heal"
    );
    read_ship_start_burst(&mut alice);
    alice.quiet("the start step ends");
    // The land ships out to the port spot.
    alice.send_record(&client_click(wheel));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the menu again");
    alice.send_record(&client_script_answer(3));
    assert_eq!(
        alice.read_game(),
        server_script(1, b"landed[ENTER][DONE]"),
        "the land says so"
    );
    // The land's own delete and warp, in order.
    let mut removed = vec![GC_CHARACTER_DEL];
    removed.extend_from_slice(&listed.id.to_le_bytes());
    assert_eq!(alice.read_game(), removed, "EncodeRemovePacket(this)");
    let port = server.channel(1).port();
    assert_eq!(
        alice.read_game(),
        a_warp_record((168_500, 611_200), port),
        "the port spot"
    );
    alice.quiet("the land step ends");
    wait_for(
        &database,
        "(SELECT map_index FROM player WHERE name = 'Alpha') = 359",
    );
}
/// `sys.dungeon.ship_defense`: Alpha boards, starts, and watches wave 1 land on the
/// mast. The start's burst is the broadcast, the attack warning and the wave line (the
/// probe's heal is absent here); the wave-1 countdown chats at 60 and under 10; and the
/// deck's first spawn walks the mast — a `GC_TARGET` naming it with less than its
/// 5,000,000 — while the fake-hydra intimidation stays dead on the map.
#[test]
fn a_wave_strikes_the_mast_while_the_fake_heads_stand_dead() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    add_characters(&database);
    sql(
        &database,
        "UPDATE player SET map_index = 135, x = 1107800, y = 1782700 WHERE name = 'Alpha'",
    );
    let (server, _data) = Server::start_with_files_channels(
        binary(),
        database.url(),
        &[("locale/europe/quest/zz_probe/ship_probe.lua", SHIP_PROBE)],
        &ship_channels(),
        "no_wander = true",
    );
    let (mut alice, listed, entered) = enter_world_seeing(&server, b"alice", 0);
    let npc = shown_vid(&entered, 9009, "the cape shows 9009");
    alice.send_record(&client_click(npc));
    assert_eq!(
        alice.read_game()[0],
        GC_SCRIPT,
        "the board menu with the probe's arm"
    );
    alice.send_record(&client_script_answer(1));
    assert_eq!(
        alice.read_game()[0],
        GC_SCRIPT,
        "the flags and the shadow pair around the create"
    );
    let mut removed = vec![GC_CHARACTER_DEL];
    removed.extend_from_slice(&listed.id.to_le_bytes());
    assert_eq!(alice.read_game(), removed, "EncodeRemovePacket(this)");
    assert_eq!(alice.read_game()[0], GC_WARP, "the recall spot on the run");
    alice.quiet("the create step ends");
    wait_for(
        &database,
        "(SELECT map_index FROM player WHERE name = 'Alpha') = 3580000",
    );
    drop(alice);
    let (mut alice, _character, _quickslots, _items) =
        load_with_quickslots_on(&server, 1, b"alice", 0, ENGLISH);
    let entered = enter_game_view(&mut alice);
    let wheel = shown_vid(&entered, 20436, "the run shows the wheel");
    let mast = shown_vid(&entered, 20434, "the run shows the mast");
    alice.send_record(&client_click(wheel));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the wheel's menu");
    alice.send_record(&client_script_answer(2));
    assert_eq!(
        alice.read_game()[0],
        GC_SCRIPT,
        "the running read and the heal"
    );
    read_ship_start_burst(&mut alice);
    alice.quiet("the start step ends");
    // The wave-1 countdown chats at 60, then under 10; the deck may take a minute
    // to speak, so the wait is two.
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(150);
    let mut struck = false;
    let mut fake_dead = false;
    loop {
        let Some(record) = alice.read_game_until(deadline) else {
            break;
        };
        if record[0] == GC_TARGET && record.get(1..5) == Some(&mast.to_le_bytes()) {
            let hp = i32::from_le_bytes(record[6..10].try_into().expect("four bytes"));
            if i64::from(hp) < 5_000_000 {
                struck = true;
            }
        }
        if record[0] == GC_CHARACTER_DEL {
            // The fake-hydra clear destroys the intimidation's head 3 s on.
            fake_dead = true;
        }
        if struck && fake_dead {
            break;
        }
    }
    assert!(struck, "a deck spawn struck the mast");
    assert!(fake_dead, "the fake head goes without a swing");
}

/// The fight's probe: the NPC's reward arm reads `CanGetReward` and attempts the
/// take, so the wire pins the gate's refusal before the fight is won.
const MELEY_FIGHT_PROBE: &[u8] = b"quest meley_fight_probe begin\n\
    state start begin\n\
    when 20419.chat.\"probe register\" begin\n\
    local r1, r2 = MeleyLair.Register()\n\
    say(\"got \" .. r1 .. \" \" .. r2)\n\
    end\n\
    when 20419.chat.\"probe enter\" begin\n\
    local ok, limit = MeleyLair.Enter()\n\
    say(\"in \" .. tostring(ok) .. \" \" .. limit)\n\
    end\n\
    when 20419.chat.\"probe reward\" begin\n\
    say(\"may \" .. tostring(MeleyLair.CanGetReward()))\n\
    MeleyLair.Reward(1)\n\
    say(\"tried\")\n\
    end\n\
    end\n\
    end\n";

/// `lua.MeleyLair.CanGetReward`, `lua.MeleyLair.Reward`: Alpha leads `MyGuild`
/// and stands beside the sub map's NPC (20419). The probe register passes, the
/// probe enter in guild PK mode warps it to the run, and the gate click refuses
/// the failed start over the wire: the statues have no proto on the owner's
/// data, so a piece is missing and the three failed-start lines chat. (The
/// units pin the real start, the statue flags, the kill strip and the chest's
/// take.)
#[test]
fn a_guild_starts_meleys_fight_and_the_reward_refuses() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    add_characters(&database);
    seed_meley_guild(&database);
    let (server, _data) = Server::start_with_files_channels(
        binary(),
        database.url(),
        &[(
            "locale/europe/quest/zz_probe/meley_fight_probe.lua",
            MELEY_FIGHT_PROBE,
        )],
        &meley_channels(),
        "no_wander = true",
    );
    meley_fight_registers_and_enters(&server, &database);
}

/// The fight's first half: the probe register passes, guild PK mode lands, and
/// the probe enter warps Alpha to the recall spot on the run.
fn meley_fight_registers_and_enters(server: &Server, database: &ScratchDatabase) {
    let (mut alice, listed, entered) =
        enter_world_seeing_guilded(server, b"alice", 0, 1, Some(&[(801, 48, 5)]));
    let npc = shown_vid(&entered, 20_419, "the sub map shows 20419");
    alice.send_record(&client_click(npc));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the menu");
    alice.send_record(&client_script_answer(3));
    assert_eq!(
        alice.read_game(),
        server_script(1, b"got 6 300[ENTER][DONE]"),
        "the register passes"
    );
    assert_eq!(
        alice.read_game(),
        an_info_line(b"[LS;1001;0]"),
        "the ladder line"
    );
    alice.quiet("the register step ends");
    wait_for(
        database,
        "(SELECT ladder_point FROM guild WHERE id = 7) = 0",
    );
    alice.send_record(&client_chat(CHAT_TALKING, b"/pkmode 4"));
    assert_eq!(read_update_mode(&mut alice, listed.id), 4, "guild lands");
    alice.quiet("the switch ends");
    alice.send_record(&client_click(npc));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the menu again");
    alice.send_record(&client_script_answer(4));
    assert_eq!(
        alice.read_game(),
        server_script(1, b"in true 0[ENTER][DONE]"),
        "the enter passes"
    );
    let port = server.channel(1).port();
    let mut removed = vec![GC_CHARACTER_DEL];
    removed.extend_from_slice(&listed.id.to_le_bytes());
    assert_eq!(alice.read_game(), removed, "EncodeRemovePacket(this)");
    assert_eq!(
        alice.read_game(),
        a_warp_record((320_000, 1_529_000), port),
        "the recall spot on the run"
    );
    alice.quiet("the enter step ends");
    wait_for(
        database,
        "(SELECT map_index FROM player WHERE name = 'Alpha') = 2120000",
    );
    drop(alice);
    meley_fight_clicks_the_gate(server);
}

/// The fight's second half: coming back, the gate click refuses the failed
/// start, and the shelter NPC's reward probe reads false and gives nothing.
fn meley_fight_clicks_the_gate(server: &Server) {
    let (keyed, character, _quickslots, _items) =
        load_with_quickslots_on(server, 1, b"alice", 0, ENGLISH);
    let mut alice = keyed;
    let entered = enter_game_guilded(&mut alice, 1, Some(&[(801, 48, 5)]));
    assert_eq!((character.x, character.y), (320_000, 1_529_000));
    let gate = shown_vid(&entered, 20_388, "the run shows the gate");
    read_login_lines(&mut alice, 0, None);
    read_letter(
        &mut alice,
        QUEST_ATTR67ADD,
        b"Sixth and Seventh Bonus",
        "item_attr67add",
    );
    let _marks = read_login_letters(&mut alice, false);
    read_login_update(&mut alice);
    alice.quiet("the login ends");
    alice.send_record(&client_click(gate));
    let first = alice.read_game();
    assert_eq!(first[0], GC_CHAT, "the failed-start line");
    let second = alice.read_game();
    assert_eq!(second[0], GC_CHAT, "the ladder return");
    let third = alice.read_game();
    assert_eq!(third[0], GC_CHAT, "the warp-out line");
    assert_eq!(
        alice.read_game(),
        an_info_line(b"[LS;1001;600]"),
        "the returned ladder"
    );
    alice.quiet("the click ends");
    let shelter = shown_vid(&entered, 20_419, "the run shows the shelter NPC");
    alice.send_record(&client_click(shelter));
    assert_eq!(
        alice.read_game(),
        server_script(
            1,
            b"[QUESTION 1;Leave the shelter!|2;probe register|3;probe enter|4;probe reward|5;Inchide]",
        ),
        "the run's menu"
    );
    alice.send_record(&client_script_answer(3));
    assert_eq!(
        alice.read_game(),
        server_script(1, b"may false[ENTER]tried[ENTER][DONE]"),
        "no take before the win"
    );
    alice.quiet("the reward step ends");
}

/// Alpha with two campfires in cell 0 (id 51).
