    let protos = owners_protos();
    let fire = protos.get(CAMPFIRE).expect("the owner's data has the fire");
    assert_eq!(
        fire.item_type,
        gamedata::item_kind::ITEM_CAMPFIRE,
        "a campfire"
    );
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
