/// `sys.life.fishing`, `event.char_item.kill_campfire_event`: a used campfire stands at the
/// point 100 ahead (Alpha enters at [`ALPHA_ENTERS_AT`] facing north, so 100 north of it),
/// facing a drawn whole heading, and one fire is used; a second use within 60 s is refused
/// with the wait line and changes nothing; 40 s on the fire goes out and its removal
/// reaches the view.
#[test]
fn a_used_campfire_stands_ahead_burns_and_goes_out() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = campfire_stage(&database);
    let (mut alice, _alpha, _entered) = enter_equipped_world_with(&server, b"alice", 1);
    let at = (ALPHA_ENTERS_AT.0, ALPHA_ENTERS_AT.1 + 100);

    alice.send_record(&client_item_use(0));
    assert_eq!(
        update_fields(&alice.read_game()),
        (1, 0, 1),
        "one fire left"
    );
    let insert = alice.read_game();
    assert_eq!(insert[0], GC_CHARACTER_ADD, "the campfire's insert");
    assert_eq!(inserted_at(&insert), at, "100 ahead");
    assert_eq!(
        u16::from_le_bytes([insert[22], insert[23]]),
        12_000,
        "the campfire"
    );
    let angle = f32::from_le_bytes(insert[5..9].try_into().expect("four"));
    assert!(
        angle.fract() == 0.0 && (0.0..=359.0).contains(&angle),
        "a drawn whole heading: {angle}"
    );
    let vid = u32::from_le_bytes(insert[1..5].try_into().expect("four bytes"));
    assert_eq!(
        u32::from_le_bytes(alice.read_game()[1..5].try_into().expect("four bytes")),
        vid,
        "the campfire's summary"
    );
    wait_for(&database, "(SELECT count FROM item WHERE id = 51) = 1");

    alice.send_record(&client_item_use(0));
    assert_eq!(
        alice.read_game(),
        an_info_line(b"Once at 60 seconds you can use the fire"),
        "the 60 s cool"
    );
    alice.quiet("the refused fire changes nothing");

    let deadline = std::time::Instant::now() + Duration::from_secs(45);
    let mut removal = vec![GC_CHARACTER_DEL];
    removal.extend_from_slice(&vid.to_le_bytes());
    assert_eq!(
        alice.read_game_until(deadline),
        Some(removal),
        "40 s on the fire goes out"
    );
}

/// `HEADER_CG_DAILY_GIFT` and `HEADER_GC_DAILY_GIFT` (both 0xb4).
const CG_DAILY_GIFT: u8 = 180;
const GC_DAILY_GIFT: u8 = 180;
/// `sizeof(TPacketGCDailyGift)`: the header, cash, week, seven vnums, counts,
/// collect times, costs and statuses.
const DAILY_GIFT_LEN: usize = 111;
/// `DAILY_GIFT_TICKET_ITEM` (`G/length.h`).
const DAILY_TICKET: u32 = 72319;

/// A `CG_DAILY_GIFT` of `action` for `slot`.
fn client_daily_gift(action: u8, slot: u8) -> Vec<u8> {
    vec![CG_DAILY_GIFT, action, slot]
}

/// A `GC_DAILY_GIFT` week, parsed off the client's socket.
struct GiftWeek {
    cash: u32,
    week: u8,
    vnums: [u32; 7],
    counts: [u32; 7],
    collects: [u32; 7],
    costs: [u16; 7],
    statuses: [u8; 7],
}

/// Read a `GC_DAILY_GIFT` record and parse its seven days.
fn read_gift_week(keyed: &mut Keyed) -> GiftWeek {
    let record = keyed.read_game();
    assert_eq!(record.len(), DAILY_GIFT_LEN);
    assert_eq!(record[0], GC_DAILY_GIFT);
    let u32_at = |at: usize| u32::from_le_bytes(record[at..at + 4].try_into().unwrap());
    let mut week = GiftWeek {
        cash: u32_at(1),
        week: record[5],
        vnums: [0; 7],
        counts: [0; 7],
        collects: [0; 7],
        costs: [0; 7],
        statuses: [0; 7],
    };
    for day in 0..7 {
        week.vnums[day] = u32_at(6 + day * 4);
        week.counts[day] = u32_at(34 + day * 4);
        week.collects[day] = u32_at(62 + day * 4);
        week.costs[day] = u16::from_le_bytes([record[90 + day * 2], record[91 + day * 2]]);
        week.statuses[day] = record[104 + day];
    }
    week
}

/// Read the seven `[TEST]` lines an open prints, one per day in day order.
fn read_test_days(keyed: &mut Keyed) {
    for day in 1..=7u8 {
        let line = keyed.read_game();
        let head = format!("[TEST] You can collect day {day} at ");
        assert_eq!(line[0], GC_CHAT, "day {day} rides a chat line");
        assert_eq!(
            line.len(),
            10 + head.len() + 25,
            "day {day} carries a ctime and its newline"
        );
        assert_eq!(
            &line[10..10 + head.len()],
            head.as_bytes(),
            "day {day} names itself"
        );
        assert_eq!(
            line[line.len() - 1],
            b'\n',
            "day {day} keeps ctime's newline"
        );
    }
}

/// The guard's `[TEST]` line a collect of day `day` prints before anything else:
/// the status call carries collect time 0, so the date is the epoch.
fn guard_test_day(alice: &mut Keyed, day: u8) {
    assert_eq!(
        alice.read_game(),
        an_info_line(
            format!("[TEST] You can collect day {day} at Thu Jan  1 00:00:00 1970\n").as_bytes()
        ),
        "the guard names day {day} at the epoch"
    );
}

/// Stage the daily-gift scenario: Alpha an `IMPLEMENTOR` with 1000 cash and a ticket
/// in cell 4, and Yankee at level 1, both in empire 1 where Alpha stands.
fn stage_daily_gifts(database: &ScratchDatabase) {
    sql(
        database,
        "INSERT INTO gm_grant (account_id, name, authority) SELECT id, 'Alpha', 'IMPLEMENTOR' \
         FROM account WHERE login = 'alice'",
    );
    sql(database, "UPDATE account SET empire = 1");
    sql(
        database,
        "UPDATE account SET cash = 1000 WHERE login = 'alice'",
    );
    sql(
        database,
        "INSERT INTO player (account_id, slot, name, job, level, x, y) SELECT id, 0, 'Yankee', \
         1, 1, 470000, 950000 FROM account WHERE login = 'bob'",
    );
    sql(
        database,
        &format!(
            "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 20, id, 1, 4, \
             1, {DAILY_TICKET} FROM player WHERE name = 'Alpha'"
        ),
    );
}

/// Run `/daily_gift_event {args}` and read the arm and the notice an enable fans, or
/// the arm and the line a disable answers.
fn run_daily_event(alice: &mut Keyed, args: &[u8], value: u8) {
    let mut line = b"/daily_gift_event ".to_vec();
    line.extend_from_slice(args);
    alice.send_record(&client_chat(CHAT_TALKING, &line));
    assert_eq!(
        alice.read_game(),
        a_command_line(format!("DailyGiftEvent {value}").as_bytes()),
        "the flag's arm lands first"
    );
}

/// `sub.DailyGift.DAILY_GIFT_CLOSE`: the close clears the open flag, so the next open
/// reloads the week instead of resending it. The open, collect and ticket arms ride
/// `daily_gifts_collect_for_cash_and_a_ticket_and_the_week_renews`.
#[test]
fn a_daily_gift_close_clears_the_open_week() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    add_characters(&database);
    stage_daily_gifts(&database);
    let server = Server::start(binary(), database.url());
    let (mut alice, _) = enter_world_as_implementor(&server);
    run_daily_event(&mut alice, b"1 3 1", 1);
    assert_eq!(
        alice.read_game(),
        chat_packet(CHAT_TYPE_NOTICE, 1, b"Daily gifts are now available."),
        "the start is noticed"
    );
    // Open: the week loads. Close: silent. Open again: the week reloads, with the
    // same cash and week.
    alice.send_record(&client_daily_gift(1, 0));
    read_test_days(&mut alice);
    let first = read_gift_week(&mut alice);
    assert_eq!((first.cash, first.week), (1000, 3), "the loaded week");
    alice.send_record(&client_daily_gift(0, 0));
    alice.quiet("the close answers nothing");
    alice.send_record(&client_daily_gift(1, 0));
    read_test_days(&mut alice);
    let second = read_gift_week(&mut alice);
    assert_eq!(
        (second.cash, second.week),
        (1000, 3),
        "the reopened week reloads"
    );
}

/// `cg.game.daily_gift`: the week's gifts collect free, for cash and for the ticket,
/// a short week renews into the next, and the row and the cash save.
#[test]
fn daily_gifts_collect_for_cash_and_a_ticket_and_the_week_renews() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    create_account_before_boot(&database, "bob");
    add_characters(&database);
    stage_daily_gifts(&database);
    // The save cycle is a second, so the cash delta saves twice: once behind the
    // collects, once at the drop. The second save must find no delta left.
    let server = Server::start_configured(
        binary(),
        database.url(),
        &default_channels(),
        "save_event_second_cycle = 1",
    );
    let (mut alice, _) = enter_world_as_implementor(&server);
    let before = unix_secs();
    run_daily_event(&mut alice, b"1 3 1", 1);
    assert_eq!(
        alice.read_game(),
        chat_packet(CHAT_TYPE_NOTICE, 1, b"Daily gifts are now available."),
        "the start is noticed"
    );
    let after = unix_secs();
    collect_the_week(&mut alice, before, after);
    wait_for(
        &database,
        "(SELECT cash = 400 FROM account WHERE login = 'alice')",
    );
    read_daily_usage(&mut alice);
    refuse_yankee_mission(&server, &mut alice);
    run_daily_event(&mut alice, b"0", 0);
    assert_eq!(
        alice.read_game(),
        an_info_line(b"You disabled the daily gift event."),
        "the stop answers"
    );
    alice.send_record(&client_daily_gift(1, 0));
    alice.quiet("a stopped event opens nothing");
    renew_the_week(&server, &database, alice);
}

/// The usage, while the event runs: the seventeen lines, a blank, the dates, and
/// the already-active refusal of a second start.
fn read_daily_usage(alice: &mut Keyed) {
    alice.send_record(&client_chat(CHAT_TALKING, b"/daily_gift_event"));
    for line in [
        "Usage: daily_gift_event <command> <specific_week> <renew>",
        "<command>",
        "    0 = Disable",
        "    1 = Enable",
        "<specific_week>",
        "    ID = ( 0 = Random | # Week table )",
        "    STRING = ( auto = Start week from order )",
        "<renew>",
        "    0 = The event will stop after a week",
        "    1 = The event will continue after a week",
        "        with the same arguments.",
        "<renew>",
        "    0 = The event will stop after a week",
        "    1 = The event will continue after a week",
        "        with the same arguments.",
        "Example:",
        "Command: /daily_gift_event 1 auto 1",
    ] {
        assert_eq!(alice.read_game(), an_info_line(line.as_bytes()), "{line}");
    }
    assert_eq!(
        alice.read_game(),
        an_info_line(b""),
        "the dates stand apart"
    );
    for head in [
        b"     Start Date: ".as_slice(),
        b"     Renew Date: ".as_slice(),
    ] {
        let line = alice.read_game();
        assert_eq!(&line[10..10 + head.len()], head, "the date names itself");
        assert_eq!(
            line[line.len() - 1],
            b'\n',
            "the date keeps ctime's newline"
        );
    }
    alice.send_record(&client_chat(CHAT_TALKING, b"/daily_gift_event 1 3 1"));
    assert_eq!(
        alice.read_game(),
        an_info_line(b"This event is already active."),
        "a second start refuses"
    );
}

/// Below level 50 Yankee may look but never collect: every day locks, and the
/// mission line follows the record and answers the collect. The status returns
/// before the `[TEST]` print, so no test line lands.
fn refuse_yankee_mission(server: &Server, alice: &mut Keyed) {
    let (mut yankee, yankee_listed) =
        enter_world_on_with_team(server, 1, b"bob", 0, ENGLISH, Some(b"Alpha"));
    alice.sees_enter(yankee_listed.id, true, None);
    yankee.send_record(&client_daily_gift(1, 0));
    assert_eq!(
        read_gift_week(&mut yankee).statuses,
        [0, 0, 0, 0, 0, 0, 0],
        "no mission locks every day"
    );
    assert_eq!(
        yankee.read_game(),
        an_info_line(
            b"You cannot collect any reward until you complete the required quest. (Reach level 50)"
        ),
        "the look ends on the mission"
    );
    yankee.send_record(&client_daily_gift(2, 0));
    assert_eq!(
        yankee.read_game(),
        an_info_line(
            b"You cannot collect any reward until you complete the required quest. (Reach level 50)"
        ),
        "the collect answers the mission"
    );
    yankee.quiet("a refused collect changes nothing");
    let yankee_id = yankee_listed.id;
    drop(yankee);
    alice.sees_disconnect(yankee_id);
}

/// Seconds since the epoch, as the collect-time ranges compare them.
fn unix_secs() -> u32 {
    u32::try_from(
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs(),
    )
    .unwrap()
}

/// The week's collects: day 1 free and silent, day 3 for the ticket while cash would
/// cover it, day 2 for cash, then the refuses — the double collect, the poor day, the
/// spent ticket — and the silent close and unknown action.
fn collect_the_week(alice: &mut Keyed, before: u32, after: u32) {
    alice.send_record(&client_daily_gift(1, 0));
    read_test_days(alice);
    let week = read_gift_week(alice);
    assert_eq!(
        (week.cash, week.week),
        (1000, 3),
        "the loaded cash and week"
    );
    assert_eq!(
        week.vnums,
        [53006, 53015, 53219, 53221, 53237, 53245, 53256],
        "the owner's third week"
    );
    assert_eq!(week.counts, [1; 7], "one of each");
    assert_eq!(
        week.costs,
        [300, 600, 900, 1200, 1500, 1800, 2100],
        "the week's costs"
    );
    assert_eq!(
        week.statuses,
        [1, 0, 0, 0, 0, 0, 0],
        "day 1 waits, the rest lock"
    );
    for (day, collect) in week.collects.iter().enumerate() {
        let start = collect - 86_400 * u32::try_from(day + 1).unwrap();
        assert!(
            (before..=after).contains(&start),
            "day {} opens a day after the start: {start}",
            day + 1
        );
    }
    // Day 1 collects free, with no line: the gift is set, then the week resends.
    alice.send_record(&client_daily_gift(2, 0));
    guard_test_day(alice, 1);
    assert_eq!(
        set_fields(&alice.read_game()),
        (1, 0, 53006, 1),
        "the free gift lands in the first cell"
    );
    read_test_days(alice);
    assert_eq!(
        read_gift_week(alice).statuses,
        [2, 0, 0, 0, 0, 0, 0],
        "day 1 collected, day 2 still locked"
    );
    // Day 3 for the ticket, although the 1000 cash would cover its 900: the ticket
    // arm spends the ticket, and the gift lands silent.
    alice.send_record(&client_daily_gift(3, 2));
    guard_test_day(alice, 3);
    assert_eq!(
        set_fields(&alice.read_game()),
        (1, 4, 0, 0),
        "the ticket leaves its cell"
    );
    assert_eq!(
        set_fields(&alice.read_game()),
        (1, 1, 53219, 1),
        "the ticket's gift lands next"
    );
    read_test_days(alice);
    let week = read_gift_week(alice);
    assert_eq!(week.cash, 1000, "the ticket spends no cash");
    assert_eq!(
        week.statuses,
        [2, 0, 2, 0, 0, 0, 0],
        "day 3 collected, the cash untouched"
    );
    // Day 2 for cash: the line, the gift, and the week with 400 left.
    alice.send_record(&client_daily_gift(2, 1));
    guard_test_day(alice, 2);
    assert_eq!(
        alice.read_game(),
        an_info_line(b"You have unlocked the item successfully."),
        "the unlock says so"
    );
    assert_eq!(
        set_fields(&alice.read_game()),
        (1, 2, 53015, 1),
        "the bought gift lands next"
    );
    read_test_days(alice);
    let week = read_gift_week(alice);
    assert_eq!(week.cash, 400, "600 spent");
    assert_eq!(week.statuses, [2, 2, 2, 0, 0, 0, 0], "three days collected");
    refuse_the_week(alice);
}

/// The week's refuses: the double collect, the poor day, the spent ticket — and
/// the silent close and unknown action, then the reopen that resends the week.
fn refuse_the_week(alice: &mut Keyed) {
    alice.send_record(&client_daily_gift(2, 1));
    guard_test_day(alice, 2);
    assert_eq!(
        alice.read_game(),
        an_info_line(b"You have already recieved this reward."),
        "the double collect refuses"
    );
    alice.send_record(&client_daily_gift(2, 3));
    guard_test_day(alice, 4);
    assert_eq!(
        alice.read_game(),
        an_info_line(b"Unfortunately you don't have enough cash."),
        "1200 costs more than the 400 left"
    );
    alice.send_record(&client_daily_gift(3, 4));
    guard_test_day(alice, 5);
    assert_eq!(
        alice.read_game(),
        an_info_line(b"You don't have the ticket."),
        "the ticket is spent"
    );
    alice.send_record(&client_daily_gift(9, 0));
    alice.quiet("an unknown action is consumed");
    alice.send_record(&client_daily_gift(0, 0));
    alice.quiet("the close answers nothing");
    alice.send_record(&client_daily_gift(1, 0));
    read_test_days(alice);
    assert_eq!(
        read_gift_week(alice).statuses,
        [2, 2, 2, 0, 0, 0, 0],
        "the reopen resends the week"
    );
    alice.quiet("every answer was read");
}

/// Stop the week, save it, and start it again with a past renew time: the next open
/// renews into week 4, with the saved cash and the collects left behind.
fn renew_the_week(server: &Server, database: &ScratchDatabase, alice: Keyed) {
    drop(alice);
    wait_for(
        database,
        "(SELECT week = 3 AND day1 = 2 AND day2 = 2 AND day3 = 2 AND day4 = 0 AND day5 = 0 \
         AND day6 = 0 AND day7 = 0 FROM daily_gift WHERE player_id = (SELECT id FROM player \
         WHERE name = 'Alpha'))",
    );
    check(
        database,
        "(SELECT cash = 400 FROM account WHERE login = 'alice')",
    );
    check(
        database,
        "(SELECT count(*) = 3 FROM item WHERE owner_id = (SELECT id FROM player WHERE name = \
         'Alpha') AND vnum IN (53006, 53015, 53219))",
    );
    let (mut alice, _) = enter_world_as_implementor(server);
    run_daily_event(&mut alice, b"1 3 1", 1);
    assert_eq!(
        alice.read_game(),
        chat_packet(CHAT_TYPE_NOTICE, 1, b"Daily gifts are now available."),
        "the event starts again"
    );
    alice.send_record(&client_chat(
        CHAT_TALKING,
        b"/eventflag daily_gift_renew_time 1000",
    ));
    assert_eq!(
        alice.read_game(),
        an_info_line(b"RequestSetEventFlag daily_gift_renew_time 1000"),
        "the renew moves to the past"
    );
    alice.send_record(&client_chat(CHAT_TALKING, b"/eventflag daily_gift_order 1"));
    assert_eq!(
        alice.read_game(),
        an_info_line(b"RequestSetEventFlag daily_gift_order 1"),
        "the order takes the next week"
    );
    drop(alice);
    let (mut alice, _) = enter_world_as_implementor(server);
    let before = unix_secs();
    alice.send_record(&client_daily_gift(1, 0));
    read_test_days(&mut alice);
    let week = read_gift_week(&mut alice);
    let after = unix_secs();
    assert_eq!(
        (week.cash, week.week),
        (400, 4),
        "the saved cash, the next week"
    );
    assert_eq!(week.vnums[0], 76002, "week 4 leads with its own gift");
    assert_eq!(
        week.statuses,
        [1, 0, 0, 0, 0, 0, 0],
        "the new week waits on day 1"
    );
    let start = week.collects[0] - 86_400;
    assert!(
        (before..=after).contains(&start),
        "the new week starts at the renew: {start}"
    );
    alice.quiet("every answer was read");
}

/// `HEADER_CG_AURA` (172): the client-to-server aura request.
const CG_AURA: u8 = 0xac;

/// One `CG_AURA` check-in: the dead size word stays zero, then the item cell, the
/// aura slot, and the window.
fn client_aura_checkin(window: u8, cell: u16, slot: u16) -> Vec<u8> {
    let mut record = vec![CG_AURA, 0, 0, 0, 1];
    record.extend_from_slice(&cell.to_le_bytes());
    record.push(7);
    record.extend_from_slice(&slot.to_le_bytes());
    record.push(window);
    record
}

/// One `CG_AURA` accept: the window alone.
fn client_aura_accept(window: u8) -> Vec<u8> {
    vec![CG_AURA, 0, 0, 2, window]
}

/// One `CG_AURA` cancel: the dead window byte rides unread, as the close names no
/// window.
fn client_aura_cancel() -> Vec<u8> {
    vec![CG_AURA, 0, 0, 3, 0]
}

/// One `GC_AURA` check-in, parsed off the client's socket: the subheader, the
/// material's cell, the aura slot, the vnum, the drain socket, and the first
/// attribute.
fn read_aura_set(record: &[u8]) -> (u8, u16, u16, u32, i32, (u8, i16)) {
    assert_eq!(record.len(), AURA_SET_LEN, "the check-in's width");
    assert_eq!(record[0], GC_AURA);
    let vnum = u32::from_le_bytes(record[10..14].try_into().expect("four bytes"));
    let sockets = i32::from_le_bytes(record[32..36].try_into().expect("four bytes"));
    let attr = (
        record[56],
        i16::from_le_bytes(record[57..59].try_into().expect("two bytes")),
    );
    (
        record[3],
        u16::from_le_bytes(record[5..7].try_into().expect("two bytes")),
        u16::from_le_bytes(record[8..10].try_into().expect("two bytes")),
        vnum,
        sockets,
        attr,
    )
}

/// `HEADER_CG_CL` (233): the client-to-server changelook request.
const CG_CL: u8 = 0xe9;

/// One `CG_CL` request: the sub-header, the material slot, and the named position.
fn client_cl(sub_header: u8, pos: u8, window: u8, cell: u16) -> Vec<u8> {
    let mut record = vec![CG_CL, sub_header, 0, 0, 0, 0, pos, window];
    record.extend_from_slice(&cell.to_le_bytes());
    record
}

/// One `GC_CL` record, parsed off the client's socket.
struct ClRecord {
    subheader: u8,
    cost: u32,
    pos: u8,
    item_pos: (u8, u16),
}

/// Read one `GC_CL` record and parse its four fields.
fn read_cl(keyed: &mut Keyed) -> ClRecord {
    let record = keyed.read_game();
    assert_eq!(record.len(), CL_LEN, "a changelook record is 10 bytes");
    assert_eq!(record[0], GC_CL, "the changelook header");
    ClRecord {
        subheader: record[1],
        cost: u32::from_le_bytes(record[2..6].try_into().expect("four")),
        pos: record[6],
        item_pos: (
            record[7],
            u16::from_le_bytes(record[8..10].try_into().expect("two")),
        ),
    }
}

/// The transmutation of a `GC_ITEM_UPDATE` (the header, the 3-byte cell, the count and
/// the refine element come first).
fn update_transmutation(update: &[u8]) -> u32 {
    assert_eq!(update.len(), ITEM_UPDATE_LEN);
    assert_eq!(update[0], ITEM_UPDATE);
    u32::from_le_bytes(update[10..14].try_into().expect("four bytes"))
}

/// `HEADER_CG_SASH` (230): the client-to-server sash request.
const CG_SASH: u8 = 0xe6;

/// One `CG_SASH` request: the sub-header, the material slot, and the named position.
fn client_sash(sub_header: u8, pos: u8, window: u8, cell: u16) -> Vec<u8> {
    let mut record = vec![CG_SASH, sub_header, 0, 0, 0, 0, 0, pos, window];
    record.extend_from_slice(&cell.to_le_bytes());
    record.extend_from_slice(&[0; 12]);
    record
}

/// One `GC_SASH` record, parsed off the client's socket.
struct SashRecord {
    subheader: u8,
    window: bool,
    price: u32,
    pos: u8,
    item_pos: (u8, u16),
    vnum: u32,
    min_absorb: u32,
    max_absorb: u32,
}

/// Read one `GC_SASH` record and parse its nine fields.
fn read_sash(keyed: &mut Keyed) -> SashRecord {
    let record = keyed.read_game();
    assert_eq!(record.len(), SASH_LEN, "a sash record is 23 bytes");
    assert_eq!(record[0], GC_SASH, "the sash header");
    SashRecord {
        subheader: record[1],
        window: record[2] != 0,
        price: u32::from_le_bytes(record[3..7].try_into().expect("four")),
        pos: record[7],
        item_pos: (
            record[8],
            u16::from_le_bytes(record[9..11].try_into().expect("two")),
        ),
        vnum: u32::from_le_bytes(record[11..15].try_into().expect("four")),
        min_absorb: u32::from_le_bytes(record[15..19].try_into().expect("four")),
        max_absorb: u32::from_le_bytes(record[19..23].try_into().expect("four")),
    }
}

/// Seed the sash scenario and boot the server: Alpha beside Theowahdan with the
/// combine pair at cells 0 and 1, the bell at cell 2, and forty spare grade-1 sashes
/// at cells 3 up (each failed refine destroys one; the retry loop allows 40 draws).
fn sash_seed_sashes() -> Option<(ScratchDatabase, Server)> {
    let database = ScratchDatabase::create()?;
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "UPDATE player SET x = 482800, y = 944900 WHERE name = 'Alpha'",
    );
    sql(
        &database,
        "INSERT INTO quest_flag (player_id, name, value) SELECT player.id, \
         'sash_mission.__status'::bytea, 557528158 FROM player WHERE player.name = 'Alpha'",
    );
    // Two grade-1 sashes to combine, the bell to absorb, and forty spare grade-1
    // sashes: each failed refine destroys one, and the retry loop allows 40 draws.
    for (id, pos, vnum) in [(40, 0, 85001), (41, 1, 85001), (42, 2, 5000)] {
        sql(
            &database,
            &format!(
                "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT {id}, id, \
                 1, {pos}, 1, {vnum} FROM player WHERE name = 'Alpha'"
            ),
        );
    }
    for spare in 0..40 {
        sql(
            &database,
            &format!(
                "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT {}, id, \
                 1, {}, 1, 85001 FROM player WHERE name = 'Alpha'",
                100 + spare,
                3 + spare,
            ),
        );
    }
    sql(
        &database,
        "UPDATE item SET attrtype0 = 7, attrvalue0 = 26 WHERE id = 42",
    );
    Some((database, server))
}

/// The first login: the reward mark, the sash letter, the marks and the update;
/// answers the open connection and Theowahdans VID.
fn sash_first_login(server: &Server) -> (Keyed, u32) {
    let (mut keyed, _alpha, _items) = load_character(server, b"alice", 0);
    let beside = enter_beside(&mut keyed, THEOWAHDAN_VNUM);
    read_login_lines(&mut keyed, 0, None);
    read_letter(
        &mut keyed,
        QUEST_ATTR67ADD,
        b"Sixth and Seventh Bonus",
        "item_attr67add",
    );
    read_letter(
        &mut keyed,
        QUEST_YOHARA,
        b"Statuia Razboinicului",
        "the Yohara quest's change",
    );
    let _reward = read_quest_target_create(&mut keyed, 1, b"Theowahdan");
    read_letter(
        &mut keyed,
        QUEST_SASH,
        b"A special cloth",
        "the sash's letter",
    );
    read_letter(
        &mut keyed,
        QUEST_YOHARA,
        b"Statuia Razboinicului",
        "the Yohara quest's letter",
    );
    read_login_update(&mut keyed);
    keyed.still("nothing follows");

    (keyed, beside)
}

/// Past the rewards pages to his eight chats, then the "Combination" chat opens
/// the window.
fn sash_open_combination(keyed: &mut Keyed, theowahdan: u32) {
    // Past the reward's pages to his eight chats.
    keyed.send_record(&client_click(theowahdan));
    assert_eq!(
        keyed.read_game_marked(),
        server_quest_target_delete(1),
        "the target click deletes the reward mark"
    );
    let first = titled_page(b"teowahdan", &SASH_REWARD_FIRST, b"[NEXT]");
    assert_eq!(keyed.read_game_marked(), server_script(1, &first));
    keyed.send_record(&client_script_answer(254));
    let second = titled_page(b"teowahdan", &SASH_REWARD_SHORT, b"[DONE]");
    assert_eq!(keyed.read_game_marked(), server_script(1, &second));
    assert_ne!(
        read_quest_target_create(&mut *keyed, 2, b"Captain"),
        theowahdan
    );
    read_letter(
        &mut *keyed,
        QUEST_SASH,
        b"Increase your power",
        "the new state",
    );
    keyed.send_record(&client_click(theowahdan));
    assert_eq!(
        keyed.read_game(),
        server_script(
            1,
            b"[QUESTION 1;About the auras...|2;Aura: Bonus absorption|3;Aura: Refine|4;Aura: \
              Evolve|5;Transmutation|6;What is a Sash?|7;Combination|8;Absorption of \
              bonuses|9;Inchide]"
        ),
        "his eight chats, and the close"
    );
    keyed.send_record(&client_script_answer(6));
    let ask = titled_page(
        b"teowahdan",
        &[b"", b"Would you like to combine two sashes?", b""],
        b"[QUESTION 1;Yes|2;No]",
    );
    assert_eq!(keyed.read_game(), server_script(1, &ask));
    keyed.send_record(&client_script_answer(0));
    assert_eq!(keyed.read_game(), server_script(0, b"[DONE]"));
    let open = read_sash(&mut *keyed);
    assert_eq!(
        (open.subheader, open.window, open.price),
        (0, true, 0),
        "the combination window opens"
    );
}

/// Slot 0 lands at the 1370 quirk, the bell lands nowhere, slot 1 shows the result,
/// a held destroy is silent, the poor refine chats.
fn sash_adds_and_poor_refine(keyed: &mut Keyed) {
    // The grade-2 sash lands in slot 0; a grade-1 in slot 1 is another grade.
    keyed.send_record(&client_sash(1, 0, 1, 0));
    let added = read_sash(&mut *keyed);
    assert_eq!(
        (added.subheader, added.window, added.price, added.pos),
        (2, true, 100_000, 90),
        "the add answers, priced by the grade, at the 1370 quirk"
    );
    assert_eq!(
        (
            added.item_pos,
            added.vnum,
            added.min_absorb,
            added.max_absorb
        ),
        ((1, 0), 0, 0, 0),
        "one material shows no result"
    );
    // The bell is no costume: slot 1 of the combination takes nothing silently.
    keyed.send_record(&client_sash(1, 1, 1, 2));
    keyed.still("a non-costume lands silently nowhere");
    // The grade-1 sash lands in slot 1: the 85002 result at 5..=5.
    keyed.send_record(&client_sash(1, 1, 1, 1));
    let added = read_sash(&mut *keyed);
    assert_eq!(
        (
            added.subheader,
            added.vnum,
            added.min_absorb,
            added.max_absorb
        ),
        (2, 85002, 5, 5),
        "two grade-1 sashes show the stepped result"
    );
    // A destroy of a held material is silent: the lock holds.
    keyed.send_record(&client_destroy(0));
    keyed.still("a held material cannot be destroyed");
}

/// Slot 1 lifts priced by slot 0, slot 0 clears both, the close answers and a second
/// close sends nothing.
fn sash_remove_and_close(keyed: &mut Keyed) {
    // A refine with one material is silent: `CanRefineSashMaterials` answers 0.
    keyed.send_record(&client_sash(2, 1, 1, 0));
    let _ = read_sash(&mut *keyed);
    keyed.send_record(&client_sash(3, 0, 1, 0));
    keyed.still("one material refines nothing");
    keyed.send_record(&client_sash(1, 1, 1, 1));
    let _ = read_sash(&mut *keyed);
    // The poor refine chats and sends no record.
    keyed.send_record(&client_sash(3, 0, 1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"NOT_ENOUGH_YANG"),
        "no gold, no record"
    );
    keyed.still("nothing follows");
    // Slot 1 lifts alone, priced by what slot 0 holds; slot 0 clears the rest.
    keyed.send_record(&client_sash(2, 1, 1, 0));
    let removed = read_sash(&mut *keyed);
    assert_eq!(
        (
            removed.subheader,
            removed.window,
            removed.price,
            removed.pos
        ),
        (3, true, 100_000, 1),
        "slot 1 lifts, priced by slot 0"
    );
    assert_eq!(
        (removed.item_pos, removed.vnum),
        ((1, 0), 0),
        "the remove zeroes its position and vnum"
    );
    keyed.send_record(&client_sash(2, 0, 1, 0));
    let removed = read_sash(&mut *keyed);
    assert_eq!(
        (removed.subheader, removed.price, removed.pos),
        (3, 0, 0),
        "slot 0 clears both"
    );
    // The close answers; a second close sends nothing.
    keyed.send_record(&client_sash(0, 0, 1, 0));
    let closed = read_sash(&mut *keyed);
    assert_eq!(
        (closed.subheader, closed.window),
        (1, true),
        "the window closes"
    );
    keyed.send_record(&client_sash(0, 0, 1, 0));
    keyed.still("a closed window sends no close");
}

/// Stores the gold, relogs, reopens the window and lands the pair; answers the open
/// connection.
fn sash_gold_relog(server: &Server, database: &ScratchDatabase, keyed: Keyed) -> Keyed {
    // With the gold stored the reopened window combines: both cells clear, 85002
    // lands in cell 0 at absorption 5, and the refine answers 100.
    sql(
        database,
        "UPDATE player SET gold = 500000 WHERE name = 'Alpha'",
    );
    drop(keyed);
    let (mut relogged, _alpha, _items) = load_character(server, b"alice", 0);
    let theowahdan = enter_beside(&mut relogged, THEOWAHDAN_VNUM);
    read_login_lines(&mut relogged, 0, None);
    read_letter(
        &mut relogged,
        QUEST_ATTR67ADD,
        b"Sixth and Seventh Bonus",
        "item_attr67add",
    );
    let _captain = read_quest_target_create(&mut relogged, 3, b"Captain");
    read_letter(
        &mut relogged,
        QUEST_SASH,
        b"Increase your power",
        "the new state",
    );
    read_letter(
        &mut relogged,
        QUEST_YOHARA,
        b"Statuia Razboinicului",
        "the Yohara quest's change",
    );
    read_login_update(&mut relogged);
    relogged.still("nothing follows");
    relogged.send_record(&client_click(theowahdan));
    assert_eq!(
        relogged.read_game(),
        server_script(
            1,
            b"[QUESTION 1;About the auras...|2;Aura: Bonus absorption|3;Aura: Refine|4;Aura: Evolve|5;Transmutation|6;What is a Sash?|7;Combination|8;Absorption of bonuses|9;Inchide]"
        ),
        "the chats, straight to them"
    );
    relogged.send_record(&client_script_answer(6));
    let ask = titled_page(
        b"teowahdan",
        &[b"", b"Would you like to combine two sashes?", b""],
        b"[QUESTION 1;Yes|2;No]",
    );
    assert_eq!(relogged.read_game(), server_script(1, &ask));
    relogged.send_record(&client_script_answer(0));
    assert_eq!(relogged.read_game(), server_script(0, b"[DONE]"));
    let open = read_sash(&mut relogged);
    assert_eq!(
        (open.subheader, open.window),
        (0, true),
        "the window reopens"
    );
    relogged.send_record(&client_sash(1, 255, 1, 0));
    let added = read_sash(&mut relogged);
    assert_eq!(
        (added.subheader, added.price, added.pos, added.item_pos),
        (2, 100_000, 90, (1, 0)),
        "255 lands in the first free slot"
    );
    relogged.send_record(&client_sash(1, 255, 1, 1));
    let added = read_sash(&mut relogged);
    assert_eq!(
        (
            added.subheader,
            added.vnum,
            added.min_absorb,
            added.max_absorb
        ),
        (2, 85002, 5, 5),
        "the pair shows the result"
    );
    relogged
}

/// Refines at 80-in-100 until it succeeds, rotating the spares: a failure clears
/// slot 1s cell, spends the gold and answers `max_absorb` 0; the success clears both
/// cells, lands 85002 at absorption 5, spends 100,000 gold, chats `SUCCESS`, answers
/// `pos` 0 and `max_absorb` 100, and the effect 25 reaches the mover behind it.
fn sash_refine_until_success(keyed: &mut Keyed) {
    // The refine at 80-in-100: rerun the window until it succeeds. The world rolls
    // other draws between the scenario's (spawns, regen), so the loop allows enough
    // draws for the driest seed: failing 38 in a row at 0.2 each is 1 in 3.6e27.
    let mut tries = 0;
    loop {
        tries += 1;
        assert!(tries < 40, "the combine succeeds within 40 draws");
        keyed.send_record(&client_sash(3, 0, 1, 0));
        // A success clears both cells and lands 85002 in cell 0; a failure clears
        // slot 1's cell only. The first record tells them apart.
        let first = keyed.read_game();
        assert_eq!(first[0], ITEM_SET, "the slot-1 clear comes first, always");
        let second = keyed.read_game();
        if second[0] == ITEM_SET {
            // Both cells cleared: the success. The new sash lands, the gold moves,
            // SUCCESS chats, the effect goes around, and REFINED answers 100.
            let landed = keyed.read_game();
            assert_eq!(landed[0], ITEM_SET, "the result lands");
            assert_eq!(set_fields(&landed).2, 85002, "the stepped vnum");
            let gold = keyed.read_game();
            assert_eq!(gold[0], GC_GOLD_CHANGE, "the spend shows");
            assert_eq!(
                keyed.read_game(),
                an_info_line(b"SUCCESS"),
                "the success chats"
            );
            let refined = read_sash(&mut *keyed);
            assert_eq!(
                (
                    refined.subheader,
                    refined.price,
                    refined.pos,
                    refined.max_absorb
                ),
                (4, 100_000, 0, 100),
                "the refine answers its success"
            );
            // The effect around reaches the mover too, behind the answer.
            let effect = keyed.read_game();
            assert_eq!(effect[0], GC_SPECIAL_EFFECT, "the success shows around");
            assert_eq!(effect[1], 25, "SE_EFFECT_SASH_SUCCEDED");
            break;
        }
        // A failure: the FAILED chat and the REFINED record at 0. The gold moves
        // with no record of its own... no: ChangeGold sends it. Read the spend.
        let next = keyed.read_game();
        if next[0] == GC_GOLD_CHANGE {
            assert_eq!(
                keyed.read_game(),
                an_info_line(b"FAILED"),
                "the failure chats"
            );
        } else {
            assert_eq!(next, an_info_line(b"FAILED"), "the failure chats");
        }
        let refined = read_sash(&mut *keyed);
        assert_eq!(
            (refined.subheader, refined.max_absorb),
            (4, 0),
            "the refine answers its failure"
        );
        // The retry proves the failure unlocked slot 1 and kept slot 0: slot 1 lifts
        // alone (priced by what slot 0 still holds), and the next spare (cells 3 up)
        // fills it. Each failure ate one sash.
        keyed.send_record(&client_sash(2, 1, 1, 0));
        let removed = read_sash(&mut *keyed);
        assert_eq!(
            (removed.subheader, removed.price, removed.pos),
            (3, 100_000, 1),
            "slot 1 lifts, priced by the survivor in slot 0"
        );
        let spare = u16::try_from(2 + tries).expect("a spare cell");
        keyed.send_record(&client_sash(1, 255, 1, spare));
        let added = read_sash(&mut *keyed);
        assert_eq!(
            (added.subheader, added.vnum),
            (2, 85002),
            "the spare fills slot 1 and shows the result again"
        );
    }
}

/// Grants IMPLEMENTOR, relogs quiet (the missions non-GM login gate keeps it so),
/// reopens, kills: the close answers behind the dead and the three re-added affects.
fn sash_death_closes(server: &Server, database: &ScratchDatabase, keyed: Keyed) {
    // Death closes the window: the grant, the relog, the reopen, the kill, and the
    // close behind the dead. The mission's login gate (`not pc.is_gm()`) keeps the
    // GM relog quiet: no letter, no mark.
    sql(
        database,
        "INSERT INTO gm_grant (account_id, name, authority) SELECT id, 'Alpha', 'IMPLEMENTOR'          FROM account WHERE login = 'alice'",
    );
    drop(keyed);
    let (mut relogged, _alpha, _items) = load_character(server, b"alice", 0);
    let (alpha_vid, theowahdan) = enter_beside_shown(&mut relogged, THEOWAHDAN_VNUM);
    // The GM relog: the rank lines lead, `dungeon_info`'s line follows, `event_panel`'s
    // letter rides between it and `costume_option`'s hides (the implementor entry order).
    read_rank_login(&mut relogged, 0, &[], &[]);
    assert_eq!(
        relogged.read_game(),
        chat_packet(CHAT_TYPE_COMMAND, 1, b"dungeon_info_qid 1"),
        "dungeoninfo's line leads the GM login event"
    );
    read_letter(&mut relogged, 5, b"GM: Event Panel", "event_panel");
    read_login_lines_hiding_after_dungeon(&mut relogged, 1, 0, None, [false; 5], None);
    let _marks = read_login_letters(&mut relogged, true);
    let _captain = read_quest_target_create(&mut relogged, 4, b"Captain");
    read_letter(
        &mut relogged,
        QUEST_SASH,
        b"Increase your power",
        "the new state",
    );
    read_letter(
        &mut relogged,
        QUEST_YOHARA,
        b"Statuia Razboinicului",
        "the Yohara quest's change",
    );
    read_login_update(&mut relogged);
    relogged.still("nothing follows");
    relogged.send_record(&client_click(theowahdan));
    assert_eq!(
        relogged.read_game(),
        server_script(
            1,
            b"[QUESTION 1;About the auras...|2;Aura: Bonus absorption|3;Aura: Refine|4;Aura: Evolve|5;Transmutation|6;What is a Sash?|7;Combination|8;Absorption of bonuses|9;Inchide]"
        ),
        "the chats again"
    );
    relogged.send_record(&client_script_answer(6));
    let ask = titled_page(
        b"teowahdan",
        &[b"", b"Would you like to combine two sashes?", b""],
        b"[QUESTION 1;Yes|2;No]",
    );
    assert_eq!(relogged.read_game(), server_script(1, &ask));
    relogged.send_record(&client_script_answer(0));
    assert_eq!(relogged.read_game(), server_script(0, b"[DONE]"));
    let open = read_sash(&mut relogged);
    assert_eq!(
        (open.subheader, open.window),
        (0, true),
        "the window stands again"
    );
    relogged.send_record(&client_sash(1, 0, 1, 0));
    let _ = read_sash(&mut relogged);
    relogged.send_record(&client_chat(CHAT_TALKING, b"/kill Alpha"));
    assert_eq!(
        relogged.read_game(),
        ownership_of(0, alpha_vid),
        "death releases the view"
    );
    assert_eq!(relogged.read_game(), [GC_PHASE, 6], "the dead phase");
    assert_eq!(relogged.read_game(), dead_of(alpha_vid), "the dead");
    // The client is sent its affects again behind the dead (`Dead`, `:1561-1569`):
    // the two the login laid plus the penalty's own, in the order they run.
    let mut kinds = Vec::new();
    for what in [
        "the first re-added",
        "the second re-added",
        "the third re-added",
    ] {
        let add = relogged.read_game();
        assert_eq!(add[0], GC_AFFECT_ADD, "{what}: {add:02x?}");
        kinds.push(u32::from_le_bytes(add[1..5].try_into().expect("four")));
    }
    assert_eq!(kinds, [540, 215, 540], "the running three, in order");
    let closed = read_sash(&mut relogged);
    assert_eq!(
        (closed.subheader, closed.window),
        (1, true),
        "death closes the window"
    );
    relogged.still("nothing follows");
}

