/// The bell refuses slot 0, the sash lands, the bell lands as the weapon, the refine
/// absorbs, the disconnect banks every row: the sash carries the bells attribute and
/// the stamp, the bell is gone.
fn sash_absorb_and_bank(keyed: Keyed, database: &ScratchDatabase) {
    let mut keyed = keyed;
    keyed.send_record(&client_sash(1, 0, 1, 2));
    keyed.still("the bell is no costume: slot 0 takes nothing silently");
    keyed.send_record(&client_sash(1, 0, 1, 0));
    let added = read_sash(&mut keyed);
    assert_eq!(
        (added.subheader, added.window, added.price, added.pos),
        (2, false, 200_000, 90),
        "the grade-2 sash lands in slot 0, priced 200,000"
    );
    keyed.send_record(&client_sash(1, 1, 1, 2));
    let added = read_sash(&mut keyed);
    assert_eq!(
        (
            added.subheader,
            added.vnum,
            added.min_absorb,
            added.max_absorb
        ),
        (2, 85002, 5, 5),
        "the weapon lands in slot 1; the pair shows the sash at its 5"
    );
    keyed.send_record(&client_sash(3, 0, 1, 0));
    let update = keyed.read_game();
    assert_eq!(update[0], ITEM_UPDATE, "the sash's row updates");
    let sockets = update_sockets(&update);
    assert_eq!(sockets[1], 5000, "the bell's vnum stamps socket 1");
    let cleared = keyed.read_game();
    assert_eq!(cleared[0], ITEM_SET, "the bell's cell clears");
    assert_eq!(set_fields(&cleared).2, 0, "the bell is destroyed");
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"SUCCESS"),
        "the absorb chats"
    );
    let refined = read_sash(&mut keyed);
    assert_eq!(
        (
            refined.subheader,
            refined.window,
            refined.price,
            refined.pos,
            refined.max_absorb
        ),
        (4, false, 200_000, 255, 1),
        "the refine answers 255 and 1"
    );
    keyed.still("nothing follows");
    // The disconnect banks every row: the sash carries the bell's attribute and the
    // stamp, the bell is gone.
    drop(keyed);
    wait_for(
        database,
        "SELECT count(*) = 1 FROM item WHERE vnum = 85002 AND attrtype0 = 7 AND attrvalue0 = 26 \
         AND socket1 = 5000",
    );
    wait_for(database, "SELECT count(*) = 0 FROM item WHERE id = 42");
}

/// `cg.game.sash`, `sub.Sash.*`, `quest.sash`: Alpha, level 154 with the sash mission past
/// its reward and two grade-1 sashes (85001) at cells 0 and 1 plus a bell (5000) at cell 2,
/// enters beside Theowahdan. "Combination" opens the window; the grade-1 sash lands in
/// slot 0 at the 1370 quirk (the client hears 90), the bell lands silently nowhere (no
/// costume), the second grade-1 shows the 85002 result at 5..=5, a destroy of a held
/// material is silent, and the poor refine chats `NOT_ENOUGH_YANG` with no record. Slot 1
/// lifts alone priced by slot 0, slot 0 clears both, the close answers and a second close
/// sends nothing. With the gold stored the reopened window refines at 80-in-100 odds until
/// it succeeds: a failure clears slot 1's cell, spends the gold and answers `max_absorb`
/// 0; the success clears both cells, lands 85002 in cell 0 at absorption 5, spends 100,000
/// gold, chats `SUCCESS`, answers `pos` 0 and `max_absorb` 100, and the effect 25 goes
/// around and reaches the mover behind the answer.
///
/// Then, as an IMPLEMENTOR (so the mission's non-GM login gate keeps the relog quiet),
/// death closes the reopened window with its record behind the dead and the three
/// re-added affects. The absorption chat reopens it uncombined; the bell refuses slot 0
/// silently (no costume), the grade-2 sash lands there priced 200,000, the bell lands in
/// slot 1 as the weapon showing 85002 at 5..=5, and the refine updates the sash (socket 1
/// stamped 5000), destroys the bell, chats `SUCCESS`, and answers `pos` 255 and
/// `max_absorb` 1. The disconnect banks every row: the sash carries the bell's attribute
/// and the stamp, the bell is gone.
#[test]
fn sash_combines_and_absorbs() {
    let Some((database, server)) = sash_seed_sashes() else {
        return;
    };
    let (mut alice, theowahdan) = sash_first_login(&server);
    sash_open_combination(&mut alice, theowahdan);
    sash_adds_and_poor_refine(&mut alice);
    sash_remove_and_close(&mut alice);
    let mut alice = sash_gold_relog(&server, &database, alice);
    sash_refine_until_success(&mut alice);
    sash_death_closes(&server, &database, alice);
    let alice = sash_absorb_login(&server);
    sash_absorb_and_bank(alice, &database);
}

/// Seed the changelook scenario and boot the server: Alpha beside Theowahdan with the
/// sword pair at cells 0 and 1 (a +0 and a +1 sword, 10 and 11), the male-only armour at
/// cell 2 (11901), the female-only armour at cell 3 (11903), the head armour at cell 4
/// (12200), the mount spear at cell 12 (7200), and the stone at cell 13 (28030). The
/// two-cell swords and armours cover their anchor plus the cell five below, so the spear
/// and the stone sit clear of every footprint.
fn cl_seed_looks() -> Option<(ScratchDatabase, Server)> {
    let database = ScratchDatabase::create()?;
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "UPDATE player SET x = 482800, y = 944900 WHERE name = 'Alpha'",
    );
    sql(
        &database,
        "INSERT INTO quest_flag (player_id, name, value) SELECT player.id, \
         'sash_mission.__status'::bytea, 557528158 FROM player WHERE player.name = 'Alpha'",
    );
    let protos = owners_protos();
    let k = gamedata::item_kind::ITEM_WEAPON;
    for (vnum, (want, sub)) in [
        (10, (k, gamedata::item_kind::WEAPON_SWORD)),
        (11, (k, gamedata::item_kind::WEAPON_SWORD)),
        (
            11_901,
            (
                gamedata::item_kind::ITEM_ARMOR,
                gamedata::item_kind::ARMOR_BODY,
            ),
        ),
        (
            11_903,
            (
                gamedata::item_kind::ITEM_ARMOR,
                gamedata::item_kind::ARMOR_BODY,
            ),
        ),
        (
            12_200,
            (
                gamedata::item_kind::ITEM_ARMOR,
                gamedata::item_kind::ARMOR_HEAD,
            ),
        ),
        (
            7200,
            (
                gamedata::item_kind::ITEM_WEAPON,
                gamedata::item_kind::WEAPON_MOUNT_SPEAR,
            ),
        ),
        (
            7000,
            (
                gamedata::item_kind::ITEM_WEAPON,
                gamedata::item_kind::WEAPON_FAN,
            ),
        ),
        (
            3000,
            (
                gamedata::item_kind::ITEM_WEAPON,
                gamedata::item_kind::WEAPON_TWO_HANDED,
            ),
        ),
    ] {
        let proto = protos.get(vnum).expect("the owner's data has it");
        assert_eq!(
            (proto.item_type, proto.sub_type),
            (want, sub),
            "the seed vnum {vnum} is the kind the scenario proves"
        );
    }
    assert_eq!(
        (
            protos.get(11_901).expect("male-only").anti_flags & 1,
            protos.get(11_903).expect("female-only").anti_flags & 2
        ),
        (1, 2),
        "the armour pair splits on the sex flags"
    );
    for (id, pos, vnum) in [
        (40, 0, 10),
        (41, 1, 11),
        (42, 2, 11_901),
        (43, 3, 11_903),
        (44, 4, 12_200),
        (45, 12, 7200),
        (46, 13, 28_030),
        (47, 9, 7000),
        (48, 14, 3000),
    ] {
        sql(
            &database,
            &format!(
                "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT {id}, id, \
                 1, {pos}, 1, {vnum} FROM player WHERE name = 'Alpha'"
            ),
        );
    }
    Some((database, server))
}

/// The first login: the reward mark, the sash letter, the marks and the update;
/// answers the open connection and Theowahdans VID.
fn cl_first_login(server: &Server) -> (Keyed, u32) {
    let (mut keyed, _alpha, _items) = load_character(server, b"alice", 0);
    let beside = enter_beside(&mut keyed, THEOWAHDAN_VNUM);
    read_login_lines(&mut keyed, 0, None);
    read_letter(
        &mut keyed,
        QUEST_ATTR67ADD,
        b"Sixth and Seventh Bonus",
        "item_attr67add",
    );
    read_letter(
        &mut keyed,
        QUEST_YOHARA,
        b"Statuia Razboinicului",
        "the Yohara quest's change",
    );
    let _reward = read_quest_target_create(&mut keyed, 1, b"Theowahdan");
    read_letter(
        &mut keyed,
        QUEST_SASH,
        b"A special cloth",
        "the sash's letter",
    );
    read_letter(
        &mut keyed,
        QUEST_YOHARA,
        b"Statuia Razboinicului",
        "the Yohara quest's letter",
    );
    read_login_update(&mut keyed);
    keyed.still("nothing follows");
    (keyed, beside)
}

/// Past the rewards pages to his eight chats, then the "Transmutation" chat opens
/// the window.
fn cl_open_transmutation(keyed: &mut Keyed, theowahdan: u32) {
    keyed.send_record(&client_click(theowahdan));
    assert_eq!(
        keyed.read_game_marked(),
        server_quest_target_delete(1),
        "the target click deletes the reward mark"
    );
    let first = titled_page(b"teowahdan", &SASH_REWARD_FIRST, b"[NEXT]");
    assert_eq!(keyed.read_game_marked(), server_script(1, &first));
    keyed.send_record(&client_script_answer(254));
    let second = titled_page(b"teowahdan", &SASH_REWARD_SHORT, b"[DONE]");
    assert_eq!(keyed.read_game_marked(), server_script(1, &second));
    assert_ne!(
        read_quest_target_create(&mut *keyed, 2, b"Captain"),
        theowahdan
    );
    read_letter(
        &mut *keyed,
        QUEST_SASH,
        b"Increase your power",
        "the new state",
    );
    keyed.send_record(&client_click(theowahdan));
    assert_eq!(
        keyed.read_game(),
        server_script(
            1,
            b"[QUESTION 1;About the auras...|2;Aura: Bonus absorption|3;Aura: Refine|4;Aura: \
              Evolve|5;Transmutation|6;What is a Sash?|7;Combination|8;Absorption of \
              bonuses|9;Inchide]"
        ),
        "his eight chats, and the close"
    );
    keyed.send_record(&client_script_answer(4));
    let ask = titled_page(
        b"teowahdan",
        &[
            b"",
            b"Transmutation enables you to permanently change",
            b"the appearance of your equipment. The effect is",
            b"restricted to the level of your equipment,",
            b"however, and the transmutation will be reversed",
            b"if you improve the item. Do you want to continue?",
            b"",
        ],
        b"[QUESTION 1;Yes|2;No]",
    );
    assert_eq!(keyed.read_game(), server_script(1, &ask));
    keyed.send_record(&client_script_answer(0));
    assert_eq!(keyed.read_game(), server_script(0, b"[DONE]"));
    let open = read_cl(&mut *keyed);
    assert_eq!(
        (open.subheader, open.cost, open.pos, open.item_pos),
        (0, 50_000_000, 0, (1, 0)),
        "the changelook window opens"
    );
}

/// The kind refusals chat, the +0 sword lands in slot 0, slot 1's mismatches chat, and
/// a held destroy is silent.
fn cl_adds_and_guards(keyed: &mut Keyed) {
    // The head armour, the mount spear and the stone are no transmutable kind.
    for (cell, what) in [(4, "a head armour"), (12, "a mount spear"), (13, "a stone")] {
        keyed.send_record(&client_cl(2, 0, 1, cell));
        assert_eq!(
            keyed.read_game(),
            an_info_line(b"[Transmutation] This item cannot be transmuted"),
            "{what} chats the cannot line"
        );
    }
    keyed.still("nothing follows");
    // The +0 sword lands in slot 0; the record echoes the named position.
    keyed.send_record(&client_cl(2, 0, 1, 0));
    let added = read_cl(&mut *keyed);
    assert_eq!(
        (added.subheader, added.cost, added.pos, added.item_pos),
        (2, 0, 0, (1, 0)),
        "the sword lands"
    );
    // Slot 1 takes no armour of another type; the sex-split pair proves the flag
    // arm below, after the swords leave the window.
    keyed.send_record(&client_cl(2, 1, 1, 2));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Transmutation] You cannot submit this item"),
        "an armour of another type chats the submit line"
    );
    // Same type, another subtype: the fan chats the submit line too (its job flags
    // also disagree, so the polearm proves the subtype arm alone: broad flags in slot
    // 0, narrow ones in slot 1, same type, another subtype).
    keyed.send_record(&client_cl(2, 1, 1, 9));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Transmutation] You cannot submit this item"),
        "a fan of another subtype chats the submit line"
    );
    keyed.send_record(&client_cl(3, 0, 1, 0));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(2, 0, 1, 14));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(2, 1, 1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Transmutation] You cannot submit this item"),
        "a sword of another subtype chats the submit line"
    );
    keyed.send_record(&client_cl(3, 0, 1, 0));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(2, 0, 1, 0));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(2, 1, 1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Transmutation] You can't add locked items"),
        "the held sword chats the locked line"
    );
    // The +1 sword lands in slot 1: same kind, same flags, another vnum.
    keyed.send_record(&client_cl(2, 1, 1, 1));
    let added = read_cl(&mut *keyed);
    assert_eq!(
        (added.subheader, added.pos, added.item_pos),
        (2, 1, (1, 1)),
        "the +1 sword lands in slot 1"
    );
    // A destroy of a held material is silent: the lock holds.
    keyed.send_record(&client_destroy(1));
    keyed.still("a held material cannot be destroyed");
    // The window clears for the flag proof: the male-only armour lands in slot 0,
    // and the female-only one chats the submit line in slot 1 — the sex flags
    // disagree either way.
    keyed.send_record(&client_cl(3, 0, 1, 0));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(2, 0, 1, 2));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(2, 1, 1, 3));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Transmutation] You cannot submit this item"),
        "the opposed sex flag chats the submit line"
    );
    keyed.send_record(&client_cl(3, 0, 1, 0));
    let _ = read_cl(&mut *keyed);
    // The same-vnum arm: the +0 sword lands again, and its own twin in slot 1 is
    // the held sword, so the lock chats first — the vnum arm is proved by the
    // +1's landing below, which a same vnum would refuse.
    keyed.send_record(&client_cl(2, 0, 1, 0));
    let _ = read_cl(&mut *keyed);
}

/// Slot 1 lifts alone, slot 0 clears both, the close answers and a second close chats
/// the not-open line.
fn cl_remove_and_close(keyed: &mut Keyed) {
    // Slot 0 holds the +0 sword from the flag proof; the +1 lands in slot 1 so a
    // refine with one material chats the submit line after slot 1 lifts.
    keyed.send_record(&client_cl(2, 1, 1, 1));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(3, 1, 1, 0));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(4, 0, 1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Transmutation] Please submit the item you want to transmute"),
        "one material chats the submit line"
    );
    keyed.send_record(&client_cl(2, 1, 1, 1));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(4, 0, 1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Transmutation] You don't have enough Gold"),
        "no gold, no record"
    );
    keyed.still("nothing follows");
    // Slot 1 lifts alone; slot 0 clears the rest.
    keyed.send_record(&client_cl(3, 1, 1, 0));
    let removed = read_cl(&mut *keyed);
    assert_eq!(
        (
            removed.subheader,
            removed.cost,
            removed.pos,
            removed.item_pos
        ),
        (3, 0, 1, (1, 0)),
        "slot 1 lifts with a zeroed position"
    );
    keyed.send_record(&client_cl(2, 1, 1, 1));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(3, 0, 1, 0));
    let removed = read_cl(&mut *keyed);
    assert_eq!(
        (removed.subheader, removed.pos),
        (3, 0),
        "slot 0 clears both"
    );
    // A remove of the empty slot sends nothing, and a remove of slot 2 is past
    // the window; the close answers, and a second close chats the not-open line.
    keyed.send_record(&client_cl(3, 0, 1, 0));
    keyed.still("an empty slot removes nothing");
    keyed.send_record(&client_cl(2, 0, 1, 0));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(3, 2, 1, 0));
    keyed.still("slot 2 removes nothing");
    keyed.send_record(&client_cl(3, 0, 1, 0));
    let _ = read_cl(&mut *keyed);
    keyed.send_record(&client_cl(1, 0, 1, 0));
    let closed = read_cl(&mut *keyed);
    assert_eq!(
        (closed.subheader, closed.cost, closed.pos, closed.item_pos),
        (1, 0, 0, (1, 0)),
        "the window closes"
    );
    keyed.send_record(&client_cl(1, 0, 1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Transmutation] The window is not opened"),
        "a closed window chats the not-open line"
    );
}

/// Stores the gold, relogs, and reopens the window; answers the open connection.
fn cl_gold_relog(server: &Server, database: &ScratchDatabase, keyed: Keyed) -> Keyed {
    sql(
        database,
        "UPDATE player SET gold = 50000000 WHERE name = 'Alpha'",
    );
    drop(keyed);
    let (mut relogged, _alpha, _items) = load_character(server, b"alice", 0);
    let theowahdan = enter_beside(&mut relogged, THEOWAHDAN_VNUM);
    read_login_lines(&mut relogged, 0, None);
    read_letter(
        &mut relogged,
        QUEST_ATTR67ADD,
        b"Sixth and Seventh Bonus",
        "item_attr67add",
    );
    let _captain = read_quest_target_create(&mut relogged, 3, b"Captain");
    read_letter(
        &mut relogged,
        QUEST_SASH,
        b"Increase your power",
        "the new state",
    );
    read_letter(
        &mut relogged,
        QUEST_YOHARA,
        b"Statuia Razboinicului",
        "the Yohara quest's change",
    );
    read_login_update(&mut relogged);
    relogged.still("nothing follows");
    relogged.send_record(&client_click(theowahdan));
    assert_eq!(
        relogged.read_game(),
        server_script(
            1,
            b"[QUESTION 1;About the auras...|2;Aura: Bonus absorption|3;Aura: Refine|4;Aura: \
              Evolve|5;Transmutation|6;What is a Sash?|7;Combination|8;Absorption of \
              bonuses|9;Inchide]"
        ),
        "the chats again"
    );
    relogged.send_record(&client_script_answer(4));
    let ask = titled_page(
        b"teowahdan",
        &[
            b"",
            b"Transmutation enables you to permanently change",
            b"the appearance of your equipment. The effect is",
            b"restricted to the level of your equipment,",
            b"however, and the transmutation will be reversed",
            b"if you improve the item. Do you want to continue?",
            b"",
        ],
        b"[QUESTION 1;Yes|2;No]",
    );
    assert_eq!(relogged.read_game(), server_script(1, &ask));
    relogged.send_record(&client_script_answer(0));
    assert_eq!(relogged.read_game(), server_script(0, b"[DONE]"));
    let open = read_cl(&mut relogged);
    assert_eq!(open.subheader, 0, "the window stands again");
    relogged
}

/// The pair lands, the refine stamps the +0 sword with the +1's look, destroys the
/// +1, spends 50,000,000 gold, answers `REFINE`, and the disconnect banks the stamp.
fn cl_refine_and_bank(keyed: Keyed, database: &ScratchDatabase) {
    let mut keyed = keyed;
    keyed.send_record(&client_cl(2, 0, 1, 0));
    let _ = read_cl(&mut keyed);
    keyed.send_record(&client_cl(2, 1, 1, 1));
    let _ = read_cl(&mut keyed);
    keyed.send_record(&client_cl(4, 0, 1, 0));
    let update = keyed.read_game();
    assert_eq!(update[0], ITEM_UPDATE, "the sword's row updates");
    assert_eq!(
        update_transmutation(&update),
        11,
        "the +1's vnum stamps the look"
    );
    let cleared = keyed.read_game();
    assert_eq!(cleared[0], ITEM_SET, "the +1's cell clears");
    assert_eq!(set_fields(&cleared).2, 0, "the +1 is destroyed");
    let gold = keyed.read_game();
    assert_eq!(gold[0], GC_GOLD_CHANGE, "the gold moves");
    assert_eq!(
        u64::from_le_bytes(gold[16..24].try_into().expect("eight")),
        0,
        "50,000,000 leaves the 50,000,000 empty"
    );
    let refined = read_cl(&mut keyed);
    assert_eq!(
        (
            refined.subheader,
            refined.cost,
            refined.pos,
            refined.item_pos
        ),
        (4, 0, 0, (1, 0)),
        "the refine answers"
    );
    // The refine cleared the window: an add lands nowhere, and the close chats the
    // not-open line.
    keyed.send_record(&client_cl(2, 0, 1, 0));
    keyed.still("no window takes the add");
    keyed.send_record(&client_cl(1, 0, 1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Transmutation] The window is not opened"),
        "the refine closed the window"
    );
    keyed.still("nothing follows");
    drop(keyed);
    // The disconnect banks the stamp: the +0 carries the +1's look, the +1 is gone,
    // and the gold is 0.
    wait_for(
        database,
        "SELECT count(*) = 1 FROM item WHERE id = 40 AND transmutation = 11",
    );
    wait_for(database, "SELECT count(*) = 0 FROM item WHERE id = 41");
    wait_for(database, "SELECT gold = 0 FROM player WHERE name = 'Alpha'");
}

/// Death closes the reopened window: the IMPLEMENTOR grant (the mission's non-GM login
/// gate keeps the relog quiet), the relog, the reopen, a material landed, the kill, and
/// the close behind the dead and the three re-added affects. Answers the open
/// connection.
fn cl_death_closes(server: &Server, database: &ScratchDatabase, keyed: Keyed) -> Keyed {
    sql(
        database,
        "INSERT INTO gm_grant (account_id, name, authority) SELECT id, 'Alpha', 'IMPLEMENTOR'          FROM account WHERE login = 'alice'",
    );
    drop(keyed);
    let (mut relogged, _alpha, _items) = load_character(server, b"alice", 0);
    let (alpha_vid, theowahdan) = enter_beside_shown(&mut relogged, THEOWAHDAN_VNUM);
    read_rank_login(&mut relogged, 0, &[], &[]);
    assert_eq!(
        relogged.read_game(),
        chat_packet(CHAT_TYPE_COMMAND, 1, b"dungeon_info_qid 1"),
        "dungeoninfo's line leads the GM login event"
    );
    read_letter(&mut relogged, 5, b"GM: Event Panel", "event_panel");
    read_login_lines_hiding_after_dungeon(&mut relogged, 1, 0, None, [false; 5], None);
    let _marks = read_login_letters(&mut relogged, true);
    let _captain = read_quest_target_create(&mut relogged, 5, b"Captain");
    read_letter(
        &mut relogged,
        QUEST_SASH,
        b"Increase your power",
        "the new state",
    );
    read_letter(
        &mut relogged,
        QUEST_YOHARA,
        b"Statuia Razboinicului",
        "the Yohara quest's change",
    );
    read_login_update(&mut relogged);
    relogged.still("nothing follows");
    relogged.send_record(&client_click(theowahdan));
    assert_eq!(
        relogged.read_game(),
        server_script(
            1,
            b"[QUESTION 1;About the auras...|2;Aura: Bonus absorption|3;Aura: Refine|4;Aura: Evolve|5;Transmutation|6;What is a Sash?|7;Combination|8;Absorption of bonuses|9;Inchide]"
        ),
        "the chats again"
    );
    relogged.send_record(&client_script_answer(4));
    let ask = titled_page(
        b"teowahdan",
        &[
            b"",
            b"Transmutation enables you to permanently change",
            b"the appearance of your equipment. The effect is",
            b"restricted to the level of your equipment,",
            b"however, and the transmutation will be reversed",
            b"if you improve the item. Do you want to continue?",
            b"",
        ],
        b"[QUESTION 1;Yes|2;No]",
    );
    assert_eq!(relogged.read_game(), server_script(1, &ask));
    relogged.send_record(&client_script_answer(0));
    assert_eq!(relogged.read_game(), server_script(0, b"[DONE]"));
    let open = read_cl(&mut relogged);
    assert_eq!(open.subheader, 0, "the window stands again");
    // The +0 sword carries the refine's stamp, so it chats the already line; the
    // polearm lands instead.
    relogged.send_record(&client_cl(2, 0, 1, 0));
    assert_eq!(
        relogged.read_game(),
        an_info_line(b"[Transmutation] You can't add items which are transmuted yet"),
        "the stamped sword chats the already line"
    );
    relogged.send_record(&client_cl(2, 0, 1, 14));
    let _ = read_cl(&mut relogged);
    relogged.send_record(&client_chat(CHAT_TALKING, b"/kill Alpha"));
    assert_eq!(
        relogged.read_game(),
        ownership_of(0, alpha_vid),
        "death releases the view"
    );
    assert_eq!(relogged.read_game(), [GC_PHASE, 6], "the dead phase");
    assert_eq!(relogged.read_game(), dead_of(alpha_vid), "the dead");
    let mut kinds = Vec::new();
    for what in [
        "the first re-added",
        "the second re-added",
        "the third re-added",
    ] {
        let add = relogged.read_game();
        assert_eq!(add[0], GC_AFFECT_ADD, "{what}: {add:02x?}");
        kinds.push(u32::from_le_bytes(add[1..5].try_into().expect("four")));
    }
    assert_eq!(kinds, [540, 215, 540], "the running three, in order");
    let closed = read_cl(&mut relogged);
    assert_eq!(
        (closed.subheader, closed.cost, closed.pos, closed.item_pos),
        (1, 0, 0, (1, 0)),
        "death closes the window"
    );
    relogged.still("nothing follows");
    relogged
}

/// `cg.game.cl`, `sub.ChangeLook.*`, `quest.changelook`: Alpha with the sword pair at
/// cells 0 and 1, the sex-split armour pair, a head armour, a mount spear and a stone,
/// enters beside Theowahdan. "Transmutation" opens the window with the 50,000,000 cost.
/// The head armour, the mount spear and the stone chat the cannot line; the +0 sword
/// lands in slot 0, the male-only armour chats the submit line in slot 1, the held
/// sword chats the locked line, the +1 sword lands in slot 1, and a destroy of a held
/// material is silent. Slot 1 lifts alone with a zeroed position, slot 0 clears both,
/// an empty remove sends nothing, the close answers and a second close chats the
/// not-open line. A one-material refine chats the submit line; the poor refine chats
/// the gold line with no record. With the gold stored the reopened window refines: the
/// +0's row updates with the +1's look, the +1 is destroyed, 50,000,000 gold leaves,
/// the refine answers, and the disconnect banks the stamp.
#[test]
fn a_transmutation_is_refused_stamped_and_banked() {
    let Some((database, server)) = cl_seed_looks() else {
        return;
    };
    let (mut alice, theowahdan) = cl_first_login(&server);
    cl_open_transmutation(&mut alice, theowahdan);
    cl_adds_and_guards(&mut alice);
    cl_remove_and_close(&mut alice);
    let alice = cl_gold_relog(&server, &database, alice);
    cl_refine_and_bank(alice, &database);
    // Death closes a reopened window; the grant lands after the refine so the
    // earlier logins stay non-GM.
    let (mut alice, _alpha, _items) = load_character(&server, b"alice", 0);
    let _ = enter_beside(&mut alice, THEOWAHDAN_VNUM);
    read_login_lines(&mut alice, 0, None);
    read_letter(
        &mut alice,
        QUEST_ATTR67ADD,
        b"Sixth and Seventh Bonus",
        "item_attr67add",
    );
    let _captain = read_quest_target_create(&mut alice, 4, b"Captain");
    read_letter(
        &mut alice,
        QUEST_SASH,
        b"Increase your power",
        "the new state",
    );
    read_letter(
        &mut alice,
        QUEST_YOHARA,
        b"Statuia Razboinicului",
        "the Yohara quest's change",
    );
    read_login_update(&mut alice);
    alice.still("nothing follows");
    let _dead = cl_death_closes(&server, &database, alice);
}

/// `HEADER_CG_GAYA_SYSTEM` (241): the client-to-server Gaya request.
const CG_GAYA_SYSTEM: u8 = 0xf1;

/// One `CG_GAYA_SYSTEM` request: the sub-header and the `pos`.
fn client_gaya(sub_header: u8, pos: i32) -> Vec<u8> {
    let mut record = vec![CG_GAYA_SYSTEM, sub_header];
    record.extend_from_slice(&pos.to_le_bytes());
    record
}

/// A `GC_CHARACTER_POINT_CHANGE` record, parsed off the client's socket.
struct PointMove {
    kind: u8,
    amount: i64,
    value: i64,
}

/// Read one `GC_CHARACTER_POINT_CHANGE` record and parse its kind, amount and value.
fn read_point_move(keyed: &mut Keyed) -> PointMove {
    let record = keyed.read_game();
    assert_eq!(
        record.len(),
        POINT_CHANGE_LEN,
        "a points record is 25 bytes"
    );
    assert_eq!(record[0], GC_POINT_CHANGE, "the point header");
    PointMove {
        kind: record[8],
        amount: i64::from_le_bytes(record[9..17].try_into().expect("eight")),
        value: i64::from_le_bytes(record[17..25].try_into().expect("eight")),
    }
}

/// `cg.game.gaya_system`, `sub.GayaSystemSend.*`: the craft guards of a stone stack at
/// cell 0, a lone stone at 1, a sword at 2 and a grade-4 stone at 3.
fn gaya_craft_guards(keyed: &mut Keyed) {
    // An empty cell crafts nothing.
    keyed.send_record(&client_gaya(0, 9));
    keyed.still("an empty cell sends nothing");
    // The sword is no stone; the grade-4 stone is past the grade.
    keyed.send_record(&client_gaya(0, 2));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Gaya] Eroare.."),
        "a sword is no stone"
    );
    keyed.send_record(&client_gaya(0, 3));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Gaya] Eroare.."),
        "a grade-4 stone is past the grade"
    );
    keyed.still("the guards end");
}

/// The Gaya seed: Seon-Hae 20095 beside Alpha on map 1, a stone pair at cells 0 and
/// 1, a sword at 2, a grade-4 stone at 3, and ten glimmerstones at 4; answers the
/// open database and server. Gold is 100,000.
fn gaya_seed_stones() -> Option<(ScratchDatabase, Server)> {
    let database = ScratchDatabase::create()?;
    let npc = "locale/europe/map/metin2_map_a1/npc.txt";
    let mut npc_text = std::fs::read(
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../legacy/gamedata")
            .join(npc),
    )
    .expect("the owner's npc.txt");
    npc_text.extend_from_slice(b"m\t606\t540\t0\t0\t0\t1\t1000s\t100\t1\t20095\n");
    let (server, _data) = Server::start_with_files_configured(
        binary(),
        database.url(),
        &[(npc, &npc_text)],
        "no_wander = true",
    );
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "UPDATE player SET gold = 100000 WHERE name = 'Alpha'",
    );
    let protos = owners_protos();
    for (vnum, (want, sub)) in [
        (28_030, (gamedata::item_kind::ITEM_METIN, 0)),
        (28_430, (gamedata::item_kind::ITEM_METIN, 0)),
        (10, (gamedata::item_kind::ITEM_WEAPON, 0)),
        (30_400, (gamedata::item_kind::ITEM_MATERIAL, 0)),
    ] {
        let proto = protos.get(vnum).expect("the owner's data has it");
        assert_eq!(
            proto.item_type, want,
            "the seed vnum {vnum} is the kind the scenario proves"
        );
        assert_eq!(
            proto.sub_type, sub,
            "the seed vnum {vnum} is the subtype the scenario proves"
        );
    }
    for (id, pos, vnum, count) in [
        (40, 0, 28_030, 2),
        (41, 1, 28_030, 1),
        (42, 2, 10, 1),
        (43, 3, 28_430, 1),
        (44, 4, 30_400, 10),
        (45, 5, 30_401, 9),
    ] {
        sql(
            &database,
            &format!(
                "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT {id}, id, \
                 1, {pos}, {count}, {vnum} FROM player WHERE name = 'Alpha'"
            ),
        );
    }
    Some((database, server))
}

// The craft's spend: win or lose, GayaCheck lands, the ten stones clear, the Yang
// leaves the gold, and the cell loses one stone. Answers whether the roll won.
fn gaya_craft_spend(keyed: &mut Keyed) -> bool {
    use protocol::gc_item_window::{GcItemSet, GcItemUpdate};
    keyed.send_record(&client_gaya(0, 0));
    let first = keyed.read_game();
    let won = first[0] == GC_POINT_CHANGE;
    if won {
        let grant = read_point_move_bytes(&first);
        assert_eq!(
            (grant.kind, grant.amount, grant.value),
            (207, 0, 1),
            "the grant point"
        );
        assert_eq!(
            keyed.read_game(),
            an_info_line(b"[Gaya] Ai reu\xbait s\xe3  : 1."),
            "the grant line"
        );
        assert_eq!(
            keyed.read_game(),
            an_info_line(b"[Gaya] Ascu\xfeirea a reu\xbait."),
            "the success line"
        );
    } else {
        assert_eq!(
            first,
            an_info_line(b"[Gaya] Ascu\xfeirea a e\xbauat."),
            "the loss line"
        );
    }
    assert_eq!(
        keyed.read_game(),
        chat_packet(CHAT_TYPE_COMMAND, 1, b"GayaCheck"),
        "the window refresh"
    );
    let cleared = keyed.read_game();
    assert_eq!(cleared[0], ITEM_SET, "the spent stones clear");
    let set = GcItemSet::decode(&cleared).expect("a set record");
    assert_eq!((set.cell.cell, set.vnum), (4, 0), "cell 4 empties");
    let fewer = keyed.read_game();
    assert_eq!(fewer[0], ITEM_UPDATE, "the cell loses one stone");
    let update = GcItemUpdate::decode(&fewer).expect("an update record");
    assert_eq!((update.cell.cell, update.count), (0, 1), "one stone of two");
    keyed.still("the craft ends");
    won
}

/// The Gaya login: the letters and the update; answers Seon-Hae's VID.
fn gaya_first_login(keyed: &mut Keyed) -> u32 {
    let entered = enter_game_shown(keyed);
    read_login_lines(keyed, 0, None);
    let _marks = read_login_letters(keyed, true);
    read_login_update(keyed);
    keyed.still("nothing follows");
    vid_shown_at(entered.shown.inserts(), (470_200, 950_000))
}

/// Past the stone guards with the shelf unopened: the market and the refresh chat
/// the error line; a slot past 8 chats it too.
fn gaya_no_shelf(keyed: &mut Keyed) {
    keyed.send_record(&client_gaya(1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Gaya] Eroare.."),
        "no shelf buys nothing"
    );
    keyed.send_record(&client_gaya(2, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Gaya] Eroare.."),
        "no shelf refreshes nothing"
    );
    keyed.still("the shelf guards end");
}

/// Seon-Hae's "Ce bonusuri" chat opens the market: the clear, nine items, the
/// `slots` line, the stamp and the window. Answers the nine shelf rows as shown.
fn gaya_open_market(keyed: &mut Keyed, seon: u32, slots: &[u8]) -> Vec<(u32, u32, u32)> {
    keyed.send_record(&client_click(seon));
    let menu = [
        &b"[QUESTION 1;Pietre Str\xE3lucitoare|2;Ce bonusuri \xEE\x6Di aduce Gaya? |3;Inchide]"[..],
    ]
    .concat();
    assert_eq!(keyed.read_game(), server_script(1, &menu));
    keyed.send_record(&client_script_answer(1));
    let page = [
        b"[ENTER]Nu ai auzit \xEE\x6E\x63\xE3 de magazinul Gaya? [ENTER]Nu? Oh atunci trebuie s\xE3 \xEE\xFEi povestesc.. [ENTER]De la magazinul gaya po\xFEi achizi\xFEiona anumite obiecte folositoare! [ENTER]Dore\xBati s\xE3 vizualizezi magazinul ? [ENTER][ENTER]" as &[u8],
        b"[QUESTION 1;Da |2;Nu ]" as &[u8],
    ]
    .concat();
    assert_eq!(keyed.read_game(), server_script(1, &page));
    keyed.send_record(&client_script_answer(0));
    assert_eq!(keyed.read_game(), server_script(0, b"[DONE]"));
    assert_eq!(
        keyed.read_game(),
        chat_packet(CHAT_TYPE_COMMAND, 1, b"GayaMarketClear"),
        "the market clear"
    );
    let mut shelf = Vec::new();
    for _ in 0..9 {
        let line = keyed.read_game();
        let text = &line[10..];
        assert!(
            text.starts_with(b"GayaMarketItems "),
            "a market item: {line:?}"
        );
        let mut parts = text[b"GayaMarketItems ".len()..]
            .split(|byte| *byte == b' ')
            .map(|part| part.iter().fold(0u32, |n, d| n * 10 + u32::from(d - b'0')));
        shelf.push((
            parts.next().unwrap_or(0),
            parts.next().unwrap_or(0),
            parts.next().unwrap_or(0),
        ));
    }
    assert_eq!(
        keyed.read_game(),
        chat_packet(CHAT_TYPE_COMMAND, 1, slots),
        "the slot line"
    );
    let stamp = keyed.read_game();
    assert!(
        stamp[10..].starts_with(b"GayaMarketTime "),
        "the stamp: {stamp:?}"
    );
    assert_eq!(
        keyed.read_game(),
        chat_packet(CHAT_TYPE_COMMAND, 1, b"OpenGuiGayaMarket"),
        "the market window"
    );
    keyed.still("the market opens");
    shelf
}

// A locked slot short of the unlocks names them; a slot past 8 chats the error
// line; and a poor slot 0 chats the poor line.
fn gaya_market_guards(keyed: &mut Keyed) {
    keyed.send_record(&client_gaya(1, 9));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Gaya] Eroare.."),
        "a slot past 8 chats the error line"
    );
    keyed.send_record(&client_gaya(1, 3));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Gaya] 10 unit\xe3\xfei Extinde Magazinul Gaya cerute."),
        "a locked slot names its unlocks"
    );
    keyed.send_record(&client_gaya(1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Gaya] Nu de\xfeii suficient\xe3 Gaya"),
        "a poor slot chats the poor line"
    );
    keyed.still("the market guards end");
}

// Ten unlocks stand the slot-3 unlock behind: the unlock clears the stack and
// re-sends the markers with slot 3 open; the refresh spends nothing short of its
// refreshers, then re-rolls with the slots kept.
fn gaya_unlock_and_refresh(server: &Server, database: &ScratchDatabase, keyed: Keyed) -> Keyed {
    use protocol::gc_item_window::GcItemSet;
    // The tenth unlock lands in the store; the relog loads it, and the market reopens
    // fresh (the shelf is per-login).
    sql(database, "UPDATE item SET count = 10 WHERE id = 45");
    drop(keyed);
    let (mut keyed, _alpha, _items) = load_character(server, b"alice", 0);
    let entered = enter_game_shown(&mut keyed);
    read_login_lines(&mut keyed, 0, None);
    let _marks = read_login_letters(&mut keyed, true);
    read_login_update(&mut keyed);
    keyed.still("nothing follows");
    let seon = vid_shown_at(entered.shown.inserts(), (470_200, 950_000));
    gaya_open_market(&mut keyed, seon, b"GayaMarketSlotsDesblock 0 0 0 0 0 0");
    keyed.send_record(&client_gaya(1, 3));
    let cleared = keyed.read_game();
    assert_eq!(cleared[0], ITEM_SET, "the unlocks clear");
    let set = GcItemSet::decode(&cleared).expect("a set record");
    assert_eq!((set.cell.cell, set.vnum), (5, 0), "cell 5 empties");
    assert_eq!(
        keyed.read_game(),
        chat_packet(CHAT_TYPE_COMMAND, 1, b"GayaMarketClear"),
        "the markers re-send"
    );
    for _ in 0..9 {
        let line = keyed.read_game();
        assert!(
            line[10..].starts_with(b"GayaMarketItems "),
            "a market item: {line:?}"
        );
    }
    assert_eq!(
        keyed.read_game(),
        chat_packet(CHAT_TYPE_COMMAND, 1, b"GayaMarketSlotsDesblock 1 0 0 0 0 0"),
        "slot 3 stands open"
    );
    let stamp = keyed.read_game();
    assert!(
        stamp[10..].starts_with(b"GayaMarketTime "),
        "the stamp: {stamp:?}"
    );
    keyed.still("the unlock ends");
    keyed.send_record(&client_gaya(2, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Gaya] 10 unit\xe3\xfei Renew Gaya Store cerute."),
        "a refresh short of refreshers names them"
    );
    keyed.still("the refresh guard ends");
    // The buy lands once the purse holds 1,000: the grant lands in the store and
    // the relog loads it, then the market reopens and shelf slot 0 sells — the point
    // record, the pickup line and the set record. The price is parsed off the shelf's
    // first item line. The relog's login burst carries the purse first: the points
    // record's Gaya slot is asserted on the way in.
    // The disconnect banks the shelf's unlock; the grant lands once the save is done
    // (the save would overwrite it), and the relog loads 1,000.
    drop(keyed);
    wait_for(
        database,
        "(SELECT gold FROM player WHERE name = 'Alpha') = 95000",
    );
    sql(
        database,
        "UPDATE player SET gaya = 1000 WHERE name = 'Alpha'",
    );
    let (mut keyed, _alpha, _items) = load_character(server, b"alice", 0);
    let entered = enter_game_shown(&mut keyed);
    read_login_lines(&mut keyed, 0, None);
    let _marks = read_login_letters(&mut keyed, true);
    read_login_update(&mut keyed);
    keyed.still("nothing follows");
    let seon = vid_shown_at(entered.shown.inserts(), (470_200, 950_000));
    let shelf = gaya_open_market(&mut keyed, seon, b"GayaMarketSlotsDesblock 1 0 0 0 0 0");
    let protos = owners_protos();
    // 55002 is missing from the owner protos, so a row that holds it sells
    // nothing: the price leaves and no pickup follows. The four `ITEM_UNIQUE` rows
    // likewise: their make path is not ported (`unported_drop`), so the buy spends
    // and renders nothing. Rows neither the protos nor the maker take are skipped,
    // and the landed count is what `CreateItem` keeps: only a stackable row lands
    // its count, a lone row lands one (`G/item_manager.cpp:251`).
    let (slot, (vnum, price, count)) = shelf
        .iter()
        .enumerate()
        .filter(|(_, (vnum, _, _))| {
            protos
                .get(*vnum)
                .is_some_and(|proto| world::character::unported_drop(*vnum, proto).is_none())
        })
        .map(|(slot, row)| (slot, *row))
        .next()
        .expect("the shelf holds a vnum the maker takes");
    let stackable = protos
        .get(vnum)
        .is_some_and(|proto| proto.flags & world::item::ITEM_FLAG_STACKABLE != 0);
    let count = u16::try_from(if stackable { count } else { 1 }).expect("a shelf count");
    let slot = i32::try_from(slot).expect("a shelf slot");
    keyed.send_record(&client_gaya(1, slot));
    let point = read_point_move(&mut keyed);
    assert_eq!(
        (point.kind, point.amount, point.value),
        (207, 0, 1000 - i64::from(price)),
        "the price leaves the purse"
    );
    let pickup = keyed.read_game();
    assert_eq!(pickup[0], GC_CHAT, "the pickup line lands");
    let set = keyed.read_game();
    assert_eq!(set[0], ITEM_SET, "the bought item lands");
    let landed = protocol::gc_item_window::GcItemSet::decode(&set).expect("a set record");
    assert_eq!(
        (landed.vnum, landed.count),
        (vnum, count),
        "the shelf's row lands whole"
    );
    keyed.still("the buy ends");
    keyed
}

/// `cg.game.gaya_system`, `sub.GayaSystemSend.*`: the stone guards refuse and one
/// craft spends, the shelf guards refuse, the market opens over the owner's chat,
/// its guards refuse, the slot-3 unlock lands, and the refresh names its refreshers.
#[test]
fn a_gaya_craft_spends_and_a_market_opens() {
    let Some((database, server)) = gaya_seed_stones() else {
        return;
    };
    let (mut keyed, _alpha, _items) = load_character(&server, b"alice", 0);
    let seon = gaya_first_login(&mut keyed);
    gaya_craft_guards(&mut keyed);
    let _won = gaya_craft_spend(&mut keyed);
    gaya_no_shelf(&mut keyed);
    gaya_open_market(&mut keyed, seon, b"GayaMarketSlotsDesblock 0 0 0 0 0 0");
    gaya_market_guards(&mut keyed);
    let keyed = gaya_unlock_and_refresh(&server, &database, keyed);
    gaya_command_line(keyed);
}

/// `/w_gaya` runs the same three lines the records do: an empty line and a bare
/// word are silent, and `refresh` with the shelf open names the missing
/// refreshers, as the sub-header's refresh does.
fn gaya_command_line(mut keyed: Keyed) {
    keyed.send_record(&client_chat(CHAT_TALKING, b"/w_gaya"));
    keyed.still("an empty line is silent");
    keyed.send_record(&client_chat(CHAT_TALKING, b"/w_gaya dance"));
    keyed.still("a strange word is silent");
    keyed.send_record(&client_chat(CHAT_TALKING, b"/w_gaya craft"));
    keyed.still("a craft with no slot is silent");
    keyed.send_record(&client_chat(CHAT_TALKING, b"/w_gaya refresh"));
    assert_eq!(
        keyed.read_game(),
        an_info_line(b"[Gaya] 10 unit\xe3\xfei Renew Gaya Store cerute."),
        "the command's refresh names its refreshers"
    );
    keyed.still("the command ends");
}

/// Parse a `GC_CHARACTER_POINT_CHANGE` the test already read.
fn read_point_move_bytes(record: &[u8]) -> PointMove {
    assert_eq!(
        record.len(),
        POINT_CHANGE_LEN,
        "a points record is 25 bytes"
    );
    PointMove {
        kind: record[8],
        amount: i64::from_le_bytes(record[9..17].try_into().expect("eight")),
        value: i64::from_le_bytes(record[17..25].try_into().expect("eight")),
    }
}

/// `HEADER_CG_BIOLOGIST` (175) and `HEADER_GC_BIOLOGIST` (140).
const CG_BIOLOGIST: u8 = 175;
const GC_BIOLOGIST: u8 = 140;
/// `sizeof(TPacketGCBiologist)`: the header, sub-header, selective byte, 64-byte
/// title, five words, two three-word bonus arrays, and the seconds left.
const BIOLOGIST_LEN: usize = 115;
/// `POINT_BIOLOGIST_STATE`, `POINT_BIOLOGIST_ITEMS_TAKEN`, `POINT_BIOLOGIST_COMPLETED`.
const POINT_BIO_STATE: u8 = 166;
const POINT_BIO_TAKEN: u8 = 167;
const POINT_BIO_DONE: u8 = 168;

/// A `CG_BIOLOGIST`: the sub-header and the four bytes (`byChosenAffect`,
/// `byDecreaseTimeIndex`, `byIsElixirUse`, `byIsBookTimeUse`).
fn client_biologist(sub: u8, chosen: u8, flower: u8, elixir: u8, book: u8) -> Vec<u8> {
    vec![CG_BIOLOGIST, sub, chosen, flower, elixir, book]
}

/// The parsed `GC_BIOLOGIST` window.
struct BioWindow {
    sub: u8,
    selective: u8,
    title: Vec<u8>,
    level: u32,
    req: u32,
    takes: u32,
    elixir: u32,
    book: u32,
    bonus_vnum: [u32; 3],
    bonus_value: [u32; 3],
    time: i32,
}

/// Parse a `GC_BIOLOGIST` the test already read.
fn read_bio_window(record: &[u8]) -> BioWindow {
    assert_eq!(
        record.len(),
        BIOLOGIST_LEN,
        "a biologist window is 115 bytes"
    );
    assert_eq!(record[0], GC_BIOLOGIST);
    let word = |at: usize| u32::from_le_bytes(record[at..at + 4].try_into().expect("four"));
    let end = record[3..67]
        .iter()
        .position(|byte| *byte == 0)
        .unwrap_or(64);
    BioWindow {
        sub: record[1],
        selective: record[2],
        title: record[3..3 + end].to_vec(),
        level: word(67),
        req: word(71),
        takes: word(75),
        elixir: word(79),
        book: word(83),
        bonus_vnum: [word(87), word(91), word(95)],
        bonus_value: [word(99), word(103), word(107)],
        time: i32::from_le_bytes(record[111..115].try_into().expect("four")),
    }
}

/// The biologist seed: Alpha holds ten orc teeth (30006) at cell 0, ten elixirs
/// (71035) at 1, one big flower (30170) at 2 and nine forget books (72350) at 3;
/// answers the open database and server.
fn bio_seed_materials() -> Option<(ScratchDatabase, Server)> {
    let database = ScratchDatabase::create()?;
    let (server, _console) = Server::start_with_console_configured(
        binary(),
        database.url(),
        &default_channels(),
        "no_wander = true",
    );
    create_account(&server, "alice");
    add_characters(&database);
    for (id, pos, vnum, count) in [
        (40, 0, 30_006, 10),
        (41, 1, 71_035, 10),
        (42, 2, 30_170, 1),
        (43, 3, 72_350, 9),
    ] {
        sql(
            &database,
            &format!(
                "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT {id}, id, \
                 1, {pos}, {count}, {vnum} FROM player WHERE name = 'Alpha'"
            ),
        );
    }
    Some((database, server))
}

/// Alice's Alpha enters the game and reads the login burst, ready for a biologist
/// request.
fn bio_enter(server: &Server) -> Keyed {
    let (mut keyed, _alpha, _items) = load_character(server, b"alice", 0);
    let _entered = enter_game_shown(&mut keyed);
    read_login_lines(&mut keyed, 0, None);
    let _marks = read_login_letters(&mut keyed, true);
    read_login_update(&mut keyed);
    keyed.still("nothing follows");
    keyed
}

/// The client leaves and the disconnect banks the row: `condition` is the `SELECT`
/// the banked row must satisfy.
fn bio_banked(database: &ScratchDatabase, server: &mut Server, keyed: Keyed, condition: &str) {
    drop(keyed);
    server.wait_for("Character disconnected; wrote the row");
    wait_for(database, &format!("({condition})"));
}

/// `sys.custom.biologist`: Alpha opens the window on mission 0, hands over a tooth
/// with the elixir, is told to wait, shortens the wait with the big flower, hands
/// over the rest with the forget book clearing each wait, and finishes mission 0:
/// the reward lands, affect 553 lands on `POINT_MOV_SPEED`, the state rises and
/// the taken clears. Then the selective arm (which legacy guards with nothing but
/// the shared guards) grants mission 1's picked bonus and rises again, and the
/// disconnect banks state 2 with the taken cleared.
#[test]
fn a_biologist_hands_over_materials_and_finishes_a_mission() {
    let Some((database, mut server)) = bio_seed_materials() else {
        return;
    };
    let (mut keyed, _alpha, _items) = load_character(&server, b"alice", 0);
    let _entered = enter_game_shown(&mut keyed);
    read_login_lines(&mut keyed, 0, None);
    let _marks = read_login_letters(&mut keyed, true);
    read_login_update(&mut keyed);
    keyed.still("nothing follows");
    // An unknown sub-header and the close byte name no arm: both are silent.
    keyed.send_record(&client_biologist(9, 0, 0, 0, 0));
    keyed.still("a strange sub-header is silent");
    keyed.send_record(&client_biologist(1, 0, 0, 0, 0));
    keyed.still("the close byte is silent");
    // The open shows mission 0: the title, level 30, the tooth and its ten takes.
    keyed.send_record(&client_biologist(0, 0, 0, 0, 0));
    let window = read_bio_window(&keyed.read_game());
    assert_eq!(window.sub, 0, "the open sub-header");
    assert_eq!(window.selective, 0, "mission 0 never selects");
    assert_eq!(window.title, b"Din\xfeii de Orc", "the mission-0 title");
    assert_eq!(window.level, 30, "the mission-0 level");
    assert_eq!(window.req, 30_006, "the tooth");
    assert_eq!(window.takes, 10, "the ten takes");
    assert_eq!(window.elixir, 71_035, "the elixir vnum");
    assert_eq!(window.book, 72_350, "the forget-book vnum");
    assert_eq!(
        (window.bonus_vnum, window.bonus_value),
        ([8, 0, 0], [10, 0, 0]),
        "mission 0 pays move speed 10"
    );
    assert!(window.time <= 0, "no wait runs: {}", window.time);
    keyed.still("the open ends");
    bio_first_take(&mut keyed);
    bio_wait_and_flower(&mut keyed);
    bio_middle_takes(&mut keyed);
    bio_last_take(&mut keyed);
    bio_selective_grant(&mut keyed);
    drop(keyed);
    server.wait_for("Character disconnected; wrote the row");
    wait_for(
        &database,
        "(SELECT biologist_state = 2 AND biologist_items_taken = 0 AND biologist_completed = 0 \
         FROM player WHERE name = 'Alpha')",
    );
}

/// The first take with the elixir: the elixir line, the success command, the tooth
/// and elixir counts fall, the taken rises to 1, and the window re-sends with the
/// 1800 s wait running.
fn bio_first_take(keyed: &mut Keyed) {
    keyed.send_record(&client_biologist(2, 0, 0, 1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(
            b"|cff808000[Biologist]|h|r Elixirul Exploat\xe3rii a fost folosit\xe3 pentru a v\xe3 \
              oferi o \xbaans\xe3 perfect\xe3 de oferire a obiectului!"
        ),
        "the elixir line"
    );
    assert_eq!(
        update_fields(&keyed.read_game()),
        (1, 1, 9),
        "one elixir leaves"
    );
    assert_eq!(
        keyed.read_game(),
        a_command_line(b"BINARY_BiologistProvidesMaterialSuccesfully"),
        "the take lands"
    );
    assert_eq!(
        update_fields(&keyed.read_game()),
        (1, 0, 9),
        "one tooth leaves"
    );
    let took = read_point_move_bytes(&keyed.read_game());
    assert_eq!(
        (took.kind, took.amount, took.value),
        (POINT_BIO_TAKEN, 1, 1),
        "the taken rises"
    );
    let window = read_bio_window(&keyed.read_game());
    assert_eq!(window.sub, 2, "the provide sub-header");
    assert!(
        (1790..=1800).contains(&window.time),
        "the 1800 s wait runs: {}",
        window.time
    );
    keyed.still("the take ends");
}

/// The next take meets the wait; the unheld small flower is refused; the big flower
/// clears the 1800 s wait (1800 - 2700 reads free) and the window re-sends.
fn bio_wait_and_flower(keyed: &mut Keyed) {
    keyed.send_record(&client_biologist(2, 0, 0, 1, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(
            b"|cff808000[Biologist]|h|r \xcenc\xe3 prelucrez ultimul obiect oferit! Te rog s\xe3 \
              mai a\xbatep\xfei o vreme!"
        ),
        "the wait line"
    );
    keyed.still("the refused take ends");
    keyed.send_record(&client_biologist(4, 0, 0, 0, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(
            b"|cff808000[Biologist]|h|r Ai nevoie de o floare pentru a putea reduce timpul de \
              a\xbateptare!"
        ),
        "no small flower is held"
    );
    keyed.still("the refused flower ends");
    keyed.send_record(&client_biologist(4, 0, 1, 0, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(
            b"|cff808000[Biologist]|h|r Timpul de a\xbateptare a fost redus cu 45 de minute!"
        ),
        "the 45 minutes line"
    );
    assert_eq!(
        set_fields(&keyed.read_game()),
        (1, 2, 0, 0),
        "the big flower leaves"
    );
    let window = read_bio_window(&keyed.read_game());
    assert_eq!(window.sub, 4, "the time sub-header");
    assert!(window.time <= 0, "the wait cleared: {}", window.time);
    keyed.still("the flower ends");
}

/// Takes 2 to 9, each with the elixir and the forget book: the elixir line, the
/// success command, the three counts fall, the taken rises, the forgot line chats,
/// and the window re-sends with the wait cleared.
fn bio_middle_takes(keyed: &mut Keyed) {
    for take in 2..=9u32 {
        let teeth = 10 - take;
        let elixirs = 10 - take;
        let books = 10 - take;
        keyed.send_record(&client_biologist(2, 0, 0, 1, 1));
        assert_eq!(
            keyed.read_game(),
            an_info_line(
                b"|cff808000[Biologist]|h|r Elixirul Exploat\xe3rii a fost folosit\xe3 pentru a \
                  v\xe3 oferi o \xbaans\xe3 perfect\xe3 de oferire a obiectului!"
            ),
            "take {take}: the elixir line"
        );
        assert_eq!(
            update_fields(&keyed.read_game()),
            (1, 1, u16::try_from(elixirs).expect("elixirs fit")),
            "take {take}: one elixir leaves"
        );
        assert_eq!(
            keyed.read_game(),
            a_command_line(b"BINARY_BiologistProvidesMaterialSuccesfully"),
            "take {take}: the take lands"
        );
        assert_eq!(
            update_fields(&keyed.read_game()),
            (1, 0, u16::try_from(teeth).expect("teeth fit")),
            "take {take}: one tooth leaves"
        );
        let took = read_point_move_bytes(&keyed.read_game());
        assert_eq!(
            (took.kind, took.amount, took.value),
            (POINT_BIO_TAKEN, 1, i64::from(take)),
            "take {take}: the taken rises"
        );
        assert_eq!(
            keyed.read_game(),
            an_info_line(
                b"|cff808000[Biologist]|h|r Cartea Uit\xe3rii a fost folosit\xe3 pentru e elimina \
                  urm\xe3toarea limit\xe3 de timp!"
            ),
            "take {take}: the forgot line"
        );
        if books == 0 {
            assert_eq!(
                set_fields(&keyed.read_game()),
                (1, 3, 0, 0),
                "take {take}: the last book leaves"
            );
        } else {
            assert_eq!(
                update_fields(&keyed.read_game()),
                (1, 3, u16::try_from(books).expect("books fit")),
                "take {take}: one book leaves"
            );
        }
        let window = read_bio_window(&keyed.read_game());
        assert_eq!(window.sub, 2, "take {take}: the provide sub-header");
        assert!(window.time <= 0, "take {take}: the book cleared the wait");
        keyed.still("the take ends");
    }
}
/// The tenth take finishes mission 0: the elixir's and take's lines, the counts
/// fall, the taken reaches 10, the reward 50109 lands in the freed cell 2, affect
/// 553 lands move speed 10, the state rises to 1, the taken clears, and the window
/// re-sends on mission 1.
fn bio_last_take(keyed: &mut Keyed) {
    keyed.send_record(&client_biologist(2, 0, 0, 1, 1));
    assert_eq!(
        keyed.read_game(),
        an_info_line(
            b"|cff808000[Biologist]|h|r Elixirul Exploat\xe3rii a fost folosit\xe3 pentru a v\xe3 \
              oferi o \xbaans\xe3 perfect\xe3 de oferire a obiectului!"
        ),
        "the elixir line"
    );
    assert_eq!(
        set_fields(&keyed.read_game()),
        (1, 1, 0, 0),
        "the last elixir leaves"
    );
    assert_eq!(
        keyed.read_game(),
        a_command_line(b"BINARY_BiologistProvidesMaterialSuccesfully"),
        "the take lands"
    );
    assert_eq!(
        set_fields(&keyed.read_game()),
        (1, 0, 0, 0),
        "the last tooth leaves"
    );
    let took = read_point_move_bytes(&keyed.read_game());
    assert_eq!(
        (took.kind, took.amount, took.value),
        (POINT_BIO_TAKEN, 1, 10),
        "the taken reaches 10"
    );
    assert_eq!(
        set_fields(&keyed.read_game()),
        (1, 830, 50_109, 1),
        "the giftbox reward lands in its custom bank"
    );
    let rose = read_point_move_bytes(&keyed.read_game());
    assert_eq!(
        (rose.kind, rose.amount, rose.value),
        (POINT_BIO_STATE, 1, 1),
        "the state rises to 1"
    );
    let cleared = read_point_move_bytes(&keyed.read_game());
    assert_eq!(
        (cleared.kind, cleared.amount, cleared.value),
        (POINT_BIO_TAKEN, -10, 0),
        "the taken clears"
    );
    assert_eq!(
        keyed.read_game(),
        an_info_line(
            b"|cff808000[Biologist]|h|r Cartea Uit\xe3rii a fost folosit\xe3 pentru e elimina \
              urm\xe3toarea limit\xe3 de timp!"
        ),
        "the last book clears the finish's wait"
    );
    assert_eq!(
        set_fields(&keyed.read_game()),
        (1, 3, 0, 0),
        "the last book leaves"
    );
    let window = read_bio_window(&keyed.read_game());
    assert_eq!(window.sub, 2, "the provide sub-header");
    assert_eq!(window.title, b"C\xe3r\xfeile Blestemate", "now mission 1");
    assert_eq!(window.level, 40, "mission 1 wants 40");
    assert_eq!(window.req, 30_047, "mission 1 wants the cursed book");
    assert_eq!(
        (window.bonus_vnum, window.bonus_value),
        ([7, 0, 0], [8, 0, 0]),
        "mission 1 pays attack speed 8"
    );
    assert!(window.time <= 0, "the finish cleared the wait");
    // The affect's own records ride the outbox, behind the answer's: the speed
    // rises, the look re-sends, and affect 553 lands move speed 10.
    let faster = read_point_move_bytes(&keyed.read_game());
    assert_eq!(
        (faster.kind, faster.amount, faster.value),
        (19, 0, 110),
        "move speed takes the mission's 10"
    );
    let update = keyed.read_game();
    assert_eq!(update[0], GC_CHARACTER_UPDATE, "the look re-sends");
    let (added, _) = affect_moves(&[keyed.read_game()]);
    assert_eq!(added, vec![(553, 19, 10)], "affect 553 lands");
    keyed.still("the finish ends");
}

/// The selective arm on mission 1: legacy guards it with nothing but the shared
/// guards, so choice 0 grants at once — the reward 50110 lands, affect 554 lands
/// attack speed 8, the state rises to 2, and the window re-sends on mission 2.
/// A choice past 2 is silent (legacy reads `byIndex` uninitialized there).
fn bio_selective_grant(keyed: &mut Keyed) {
    for chosen in [3, 4, 5, 255] {
        keyed.send_record(&client_biologist(3, chosen, 0, 0, 0));
        keyed.still("a choice past 2 is silent");
    }
    keyed.send_record(&client_biologist(3, 0, 0, 0, 0));
    let cleared = read_point_move_bytes(&keyed.read_game());
    assert_eq!(
        (cleared.kind, cleared.amount, cleared.value),
        (POINT_BIO_TAKEN, 0, 0),
        "below the last mission the taken clears first"
    );
    assert_eq!(
        set_fields(&keyed.read_game()),
        (1, 831, 50_110, 1),
        "mission 1's giftbox lands beside the first"
    );
    let rose = read_point_move_bytes(&keyed.read_game());
    assert_eq!(
        (rose.kind, rose.amount, rose.value),
        (POINT_BIO_STATE, 1, 2),
        "the state rises to 2"
    );
    let window = read_bio_window(&keyed.read_game());
    assert_eq!(window.sub, 2, "the provide sub-header");
    assert_eq!(window.title, b"Suvenirul Demonului", "now mission 2");
    assert_eq!(window.req, 30_015, "mission 2 wants the demon souvenir");
    // The picked affect's own records ride the outbox, behind the answer's: the
    // speed total, then the add. No look re-sends for attack speed.
    let quicker = read_point_move_bytes(&keyed.read_game());
    assert_eq!(quicker.kind, 17, "attack speed moves");
    assert_eq!(quicker.amount, 0, "the affect compute sends the total");
    let update = keyed.read_game();
    assert_eq!(update[0], GC_CHARACTER_UPDATE, "the look re-sends");
    let (added, _) = affect_moves(&[keyed.read_game()]);
    assert_eq!(added, vec![(554, 17, 8)], "affect 554 lands");
    keyed.still("the pick ends");
}

/// `sys.custom.biologist`'s guards: a level exactly at the mission's passes; mission
/// 9 opens (the bound is `>`, not `>=`); a selective mission with the taken at its
/// takes answers the pick line (the bound is `>=`); a finished count on a plain
/// mission overflows; and a completed book is done.
#[test]
fn a_biologist_refuses_the_wrong_state_level_and_done_missions() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let (mut server, _console) = Server::start_with_console_configured(
        binary(),
        database.url(),
        &default_channels(),
        "no_wander = true",
    );
    create_account(&server, "alice");
    add_characters(&database);
    // Level 30 opens mission 0: the level bound is `<`, not `<=`.
    sql(
        &database,
        "UPDATE player SET level = 30 WHERE name = 'Alpha'",
    );
    let mut keyed = bio_enter(&server);
    keyed.send_record(&client_biologist(0, 0, 0, 0, 0));
    let window = read_bio_window(&keyed.read_game());
    assert_eq!(
        window.title, b"Din\xfeii de Orc",
        "level 30 opens mission 0"
    );
    keyed.still("the open ends");
    bio_banked(
        &database,
        &mut server,
        keyed,
        "SELECT level = 30 AND biologist_state = 0 FROM player WHERE name = 'Alpha'",
    );
    // State 9 opens mission 9: the state bound is `>`, not `>=`.
    sql(
        &database,
        "UPDATE player SET level = 154, biologist_state = 9 WHERE name = 'Alpha'",
    );
    let mut keyed = bio_enter(&server);
    keyed.send_record(&client_biologist(0, 0, 0, 0, 0));
    let window = read_bio_window(&keyed.read_game());
    assert_eq!(
        window.title, b"Bijuterie \xcen\xfeelepciune",
        "state 9 opens mission 9"
    );
    assert_eq!(window.level, 94, "mission 9 wants 94");
    assert_eq!(window.req, 30_252, "mission 9 wants the wisdom jewel");
    assert_eq!(window.takes, 20, "mission 9 wants twenty");
    assert_eq!(
        (window.bonus_vnum, window.bonus_value),
        ([1, 53, 54], [1100, 60, 140]),
        "mission 9 offers its three bonuses"
    );
    assert_eq!(window.selective, 0, "nothing taken, nothing to pick");
    keyed.still("the open ends");
    bio_banked(&database, &mut server, keyed, "SELECT biologist_state = 9 AND biologist_items_taken = 0 FROM player WHERE name =          'Alpha'");
    // Ten taken on mission 8 answers the pick line: the selective bound is `>=`.
    sql(
        &database,
        "UPDATE player SET biologist_state = 8, biologist_items_taken = 10 WHERE name = 'Alpha'",
    );
    let mut keyed = bio_enter(&server);
    keyed.send_record(&client_biologist(2, 0, 0, 0, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(
            b"|cff808000[Biologist]|h|r Alege unul dintre bonusurile din lista de recompens\xe3!"
        ),
        "the pick line"
    );
    keyed.still("the refused take ends");
    bio_banked(&database, &mut server, keyed, "SELECT biologist_state = 8 AND biologist_items_taken = 10 FROM player WHERE name =          'Alpha'");
    // Ten taken on mission 0 overflows: the mission is no selective one.
    sql(
        &database,
        "UPDATE player SET biologist_state = 0, biologist_items_taken = 10 WHERE name = 'Alpha'",
    );
    let mut keyed = bio_enter(&server);
    keyed.send_record(&client_biologist(2, 0, 0, 0, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(
            b"|cff808000[Biologist]|h|r OverFlow objects. Contacta\xfei un membru din echipa \
              noastr\xe3!"
        ),
        "the overflow line"
    );
    keyed.still("the refused take ends");
    bio_banked(&database, &mut server, keyed, "SELECT biologist_state = 0 AND biologist_items_taken = 10 FROM player WHERE name =          'Alpha'");
    // A completed book is done, on every arm.
    sql(
        &database,
        "UPDATE player SET biologist_state = 0, biologist_items_taken = 0, biologist_completed = 1 \
         WHERE name = 'Alpha'",
    );
    let mut keyed = bio_enter(&server);
    keyed.send_record(&client_biologist(0, 0, 0, 0, 0));
    assert_eq!(
        keyed.read_game(),
        an_info_line(
            b"|cff808000[Biologist]|h|r Misiunile Biologului Chaegirab au fost finalizate \xeen \
              totalitate!"
        ),
        "the done line"
    );
    keyed.still("the refused open ends");
}

/// The last pick finishes the book: with twenty taken on mission 9, choice 0 pays
/// the reward and the picked affect, the state clamps at 9 (the arm's room is 0),
/// the all-done line chats, the completed sets, and the close goes out. The taken
/// is *not* cleared first — only below the last mission does the arm clear it.
#[test]
fn a_biologist_last_pick_closes_the_finished_book() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let (mut server, _console) = Server::start_with_console_configured(
        binary(),
        database.url(),
        &default_channels(),
        "no_wander = true",
    );
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "UPDATE player SET biologist_state = 9, biologist_items_taken = 20 WHERE name = 'Alpha'",
    );
    let (mut keyed, _alpha, _items) = load_character(&server, b"alice", 0);
    let _entered = enter_game_shown(&mut keyed);
    read_login_lines(&mut keyed, 0, None);
    let _marks = read_login_letters(&mut keyed, true);
    read_login_update(&mut keyed);
    keyed.still("nothing follows");
    keyed.send_record(&client_biologist(3, 0, 0, 0, 0));
    assert_eq!(
        set_fields(&keyed.read_game()),
        (1, 0, 71_105, 1),
        "mission 9's reward lands in the first cell"
    );
    let rose = read_point_move_bytes(&keyed.read_game());
    assert_eq!(
        (rose.kind, rose.amount, rose.value),
        (POINT_BIO_STATE, 0, 9),
        "the state clamps at 9"
    );
    assert_eq!(
        keyed.read_game(),
        an_info_line(
            b"|cff808000[Biologist]|h|r Toate misiune au fost completate cu succes! Felicit\xe3ri!"
        ),
        "the all-done line"
    );
    let done = read_point_move_bytes(&keyed.read_game());
    assert_eq!(
        (done.kind, done.amount, done.value),
        (POINT_BIO_DONE, 1, 1),
        "the completed sets"
    );
    let close = keyed.read_game();
    assert_eq!(close.len(), BIOLOGIST_LEN, "the close is a full window");
    assert_eq!(close[0], GC_BIOLOGIST);
    assert_eq!(close[1], 1, "the close sub-header");
    assert!(
        close[2..].iter().all(|byte| *byte == 0),
        "the close zeroes every field: {close:02x?}"
    );
    // The picked affect's own records ride the outbox, behind the answer's.
    let healthier = read_point_move_bytes(&keyed.read_game());
    assert_eq!(healthier.kind, 6, "max HP moves");
    assert_eq!(healthier.amount, 0, "the affect compute sends the total");
    let (added, _) = affect_moves(&[keyed.read_game()]);
    assert_eq!(added, vec![(562, 6, 1100)], "affect 562 lands max HP 1100");
    keyed.still("the pick ends");
    drop(keyed);
    server.wait_for("Character disconnected; wrote the row");
    wait_for(
        &database,
        "(SELECT biologist_state = 9 AND biologist_items_taken = 20 AND biologist_completed = 1 \
         FROM player WHERE name = 'Alpha')",
    );
}

/// `HEADER_CG_INVENTORY_PROTECTED` (144).
const CG_PROTECTED: u8 = 144;
/// `POINT_SECURED_STATE`, `POINT_SECURED_PASSWORD`.
const POINT_SECURED: u8 = 208;
const POINT_SECURED_PASSWORD: u8 = 209;

/// A `CG_INVENTORY_PROTECTED`: the sub-header, the two 7-byte passwords, the flag.
fn client_protected(sub: u8, now: [u8; 7], changed: [u8; 7], activated: u8) -> Vec<u8> {
    let mut record = vec![CG_PROTECTED, sub];
    record.extend_from_slice(&now);
    record.extend_from_slice(&changed);
    record.push(activated);
    record
}

/// The 7-byte field for `digits`.
fn protected_field(digits: &[u8]) -> [u8; 7] {
    let mut field = [0u8; 7];
    let end = digits.len().min(7);
    field[..end].copy_from_slice(&digits[..end]);
    field
}

/// The popup line the lock chats for `text`.
fn protected_popup(text: &[u8]) -> Vec<u8> {
    let mut line = b"BINARY_PopupMessage ".to_vec();
    line.extend_from_slice(text);
    a_command_line(&line)
}

/// The mistypes and the lock: the strange sub-header is silent, a leading zero,
/// letters and a wrong password each chat, the fresh password locks with the state
/// set, and a second lock is refused.
fn lock_mistypes_and_locks(keyed: &mut Keyed, fresh: [u8; 7], empty: [u8; 7]) {
    keyed.send_record(&client_protected(9, fresh, empty, 1));
    keyed.still("a strange sub-header is silent");
    keyed.send_record(&client_protected(0, protected_field(b"012345"), empty, 1));
    assert_eq!(
        keyed.read_game(),
        protected_popup(b"|cffd93c3c[Err]:|h|r_Parola_nu_poate_incepe_cu_'0'."),
        "a leading zero is refused"
    );
    keyed.send_record(&client_protected(0, protected_field(b"12a45"), empty, 1));
    assert_eq!(
        keyed.read_game(),
        protected_popup(b"|cffd93c3c[Err]:|h|r_Parola_trebuie_sa_contina_doar_cifre."),
        "letters are refused"
    );
    keyed.send_record(&client_protected(0, protected_field(b"111111"), empty, 1));
    assert_eq!(
        keyed.read_game(),
        protected_popup(b"|cffd93c3c[Err]:|h|r_Parola_gresita._Securitatea_nu_poate_fi_activata!"),
        "a wrong password is refused"
    );
    keyed.send_record(&client_protected(0, fresh, empty, 1));
    let locked = read_point_move_bytes(&keyed.read_game());
    assert_eq!(
        (locked.kind, locked.amount, locked.value),
        (POINT_SECURED, 1, 1),
        "the state sets"
    );
    assert_eq!(
        keyed.read_game(),
        protected_popup(b"|cff3cd95e[Info]:|h|r_Securitatea_a_fost_activata!"),
        "the lock chats"
    );
    keyed.still("the lock ends");
    keyed.send_record(&client_protected(0, fresh, empty, 1));
    assert_eq!(
        keyed.read_game(),
        protected_popup(b"|cffd93c3c[Err]:|h|r_Securitatea_este_deja_activa!"),
        "a locked lock is refused"
    );
}

/// The move family while locked: a drop, a destroy, a move, a use and a wear are
