/// `quest.acce_system`'s four arms over the live script: 60003 is Theowahdan too,
/// so the sash letter marks him and the first click runs the sash target script
/// (the mark's delete, the first page); its answer runs the rest (the second page,
/// the captain's mark, the new letter and title). The second click menus the four
/// aura chats with the five sash ones. The about chat says the bla pages around a
/// wait; absorb, refine and evolve ask, the no closes, and the yes closes the
/// dialog and opens its window (0, 1, 2), each closed before the next opens.
#[test]
fn a_visitor_past_the_sash_mark_hears_the_aura_keepers_four_words() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    seed_aura_visitor(&database);
    let server = Server::start(binary(), database.url());
    let (mut alice, _alpha, _items) = load_character(&server, b"alice", 0);
    let entered = enter_game_shown(&mut alice);
    read_login_event(&mut alice);
    let keeper = shown_vid(&entered, 60_003, "map 1 shows its aura keeper");
    alice.send_record(&client_click(keeper));
    assert_eq!(
        alice.read_game()[0],
        GC_QUEST_TARGET_DELETE,
        "the mark goes first"
    );
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the sash page");
    alice.send_record(&client_script_answer(254));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the sash rest");
    assert_eq!(
        alice.read_game()[0],
        GC_QUEST_TARGET_CREATE,
        "the captain's mark"
    );
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the new letter");
    assert_eq!(alice.read_game()[0], GC_QUEST_INFO, "the new title");
    aura_menu(&mut alice, keeper);
    alice.send_record(&client_script_answer(0));
    assert_eq!(
        alice.read_game(),
        server_script(1, AURA_ABOUT_FIRST),
        "the about first"
    );
    alice.send_record(&client_script_answer(254));
    assert_eq!(
        alice.read_game(),
        server_script(1, AURA_ABOUT_LAST),
        "the about last"
    );
    aura_absorb(&mut alice, keeper);
    aura_refuse(&mut alice, keeper, 2, "the refine no closes");
    aura_window(&mut alice, keeper, 2, 1, "the refine opens");
    aura_window(&mut alice, keeper, 3, 2, "the evolve opens");
    drop(server);
}

/// [`a_visitor_past_the_sash_mark_hears_the_aura_keepers_four_words`]'s menu: the
/// click menus the four aura chats with the five sash ones.
fn aura_menu(alice: &mut Keyed, keeper: u32) {
    alice.send_record(&client_click(keeper));
    assert_eq!(alice.read_game(), server_script(1, AURA_MENU), "the menu");
}

/// Its absorb: the ask, and the yes closes the dialog and opens window 0, which the
/// client closes again.
fn aura_absorb(alice: &mut Keyed, keeper: u32) {
    aura_menu(alice, keeper);
    alice.send_record(&client_script_answer(1));
    assert_eq!(
        alice.read_game(),
        server_script(1, AURA_ABSORB_ASK),
        "the absorb asks"
    );
    alice.send_record(&client_script_answer(0));
    assert_eq!(
        alice.read_game(),
        server_script(0, b"[DONE]"),
        "the yes closes"
    );
    assert_eq!(
        alice.read_game(),
        vec![GC_AURA, 5, 0, 0, 0],
        "window 0 opens"
    );
    alice.send_record(&client_aura_cancel());
    assert_eq!(
        alice.read_game(),
        vec![GC_AURA, 5, 0, 1, 3],
        "window 0 closes"
    );
}

/// Its refusal: the ask at `entry`, and the no closes with nothing after.
fn aura_refuse(alice: &mut Keyed, keeper: u32, entry: u8, note: &str) {
    aura_menu(alice, keeper);
    alice.send_record(&client_script_answer(entry));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the ask");
    alice.send_record(&client_script_answer(1));
    assert_eq!(alice.read_game(), server_script(0, b"[DONE]"), "{note}");
    alice.quiet("nothing follows the no");
}

/// Its window: the ask at `entry`, and the yes closes the dialog and opens `window`,
/// which the client closes again.
fn aura_window(alice: &mut Keyed, keeper: u32, entry: u8, window: u8, note: &str) {
    aura_menu(alice, keeper);
    alice.send_record(&client_script_answer(entry));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the ask");
    alice.send_record(&client_script_answer(0));
    assert_eq!(
        alice.read_game(),
        server_script(0, b"[DONE]"),
        "the yes closes"
    );
    assert_eq!(alice.read_game(), vec![GC_AURA, 5, 0, 0, window], "{note}");
    alice.send_record(&client_aura_cancel());
    assert_eq!(
        alice.read_game(),
        vec![GC_AURA, 5, 0, 1, 3],
        "the window closes"
    );
}

/// The Hydra kill's congrats (`3965.kill`, `yohara_system.lua:74-84`).
/// `quest.meleylair`'s three chats over the live script: the click menus the three
/// arms and the close; the lore chat tells the Sung-Mahi story around a wait; the
/// fight chat lists the 3/600 requirements, registers on Yes (the `(6, 300)` pair
/// plus the `[LS;1001;0]` ladder line), and refuses the repeat from CH 1; the
/// shelter chat refuses without guild PK mode (limit 4), then enters in guild PK
/// mode (the remove and the recall-spot warp).
#[test]
fn a_guildmate_hears_meleys_three_words_and_enters_the_shelter() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    add_characters(&database);
    seed_meley_guild(&database);
    let server = Server::start_configured(
        binary(),
        database.url(),
        &meley_channels(),
        "no_wander = true",
    );
    let (mut alice, listed, entered) =
        enter_world_seeing_guilded(&server, b"alice", 0, 1, Some(&[(801, 48, 5)]));
    let npc = shown_vid(&entered, 20_419, "the sub map shows 20419");
    alice.send_record(&client_click(npc));
    assert_eq!(
        alice.read_game(),
        server_script(1, MELEY_MENU),
        "the three chats and the close"
    );
    // The lore chat tells the Sung-Mahi story around a wait.
    alice.send_record(&client_script_answer(0));
    assert_eq!(
        alice.read_game(),
        server_script(1, &[MELEY_TITLE, MELEY_LORE_FIRST].concat()),
        "the fear page"
    );
    alice.send_record(&client_script_answer(254));
    assert_eq!(
        alice.read_game(),
        server_script(1, &[MELEY_TITLE, MELEY_LORE_LAST].concat()),
        "the warning page"
    );
    // The fight chat lists the 3/600 requirements and registers on Yes.
    alice.send_record(&client_click(npc));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the menu again");
    alice.send_record(&client_script_answer(1));
    assert_eq!(
        alice.read_game(),
        server_script(1, &[MELEY_TITLE, MELEY_ASK].concat()),
        "the requirements"
    );
    alice.send_record(&client_script_answer(0));
    assert_eq!(
        alice.read_game(),
        server_script(1, &[MELEY_TITLE, MELEY_REGISTERED].concat()),
        "the register passes"
    );
    assert_eq!(
        alice.read_game(),
        an_info_line(b"[LS;1001;0]"),
        "the ladder line"
    );
    alice.quiet("the register step ends");
    wait_for(
        &database,
        "(SELECT ladder_point FROM guild WHERE id = 7) = 0",
    );
    // The repeat refuses from CH 1; the shelter half runs in its helper.
    alice.send_record(&client_click(npc));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the menu a third time");
    alice.send_record(&client_script_answer(1));
    assert_eq!(
        alice.read_game(),
        server_script(1, &[MELEY_TITLE, MELEY_ALREADY].concat()),
        "the repeat refuses from CH 1"
    );
    meley_shelter_refuses_then_enters(&mut alice, &server, &database, listed.id, npc);
}

/// The shelter chat's second half: it refuses without guild PK mode (`limit ==
/// 4`), then enters with it — the close, the remove, the recall-spot warp.
fn meley_shelter_refuses_then_enters(
    alice: &mut Keyed,
    server: &Server,
    database: &ScratchDatabase,
    vid: u32,
    npc: u32,
) {
    alice.send_record(&client_click(npc));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the menu a fourth time");
    alice.send_record(&client_script_answer(2));
    assert_eq!(
        alice.read_game(),
        server_script(1, &[MELEY_TITLE, MELEY_SHELTER_ASK].concat()),
        "the shelter asks"
    );
    alice.send_record(&client_script_answer(0));
    assert_eq!(
        alice.read_game(),
        server_script(1, &[MELEY_TITLE, MELEY_NEED_GUILD_MODE].concat()),
        "the peace-mode refusal"
    );
    alice.send_record(&client_chat(CHAT_TALKING, b"/pkmode 4"));
    assert_eq!(read_update_mode(alice, vid), 4, "guild lands");
    alice.quiet("the switch ends");
    alice.send_record(&client_click(npc));
    assert_eq!(alice.read_game()[0], GC_SCRIPT, "the menu a fifth time");
    alice.send_record(&client_script_answer(2));
    assert_eq!(
        alice.read_game(),
        server_script(1, &[MELEY_TITLE, MELEY_SHELTER_ASK].concat()),
        "the shelter asks again"
    );
    alice.send_record(&client_script_answer(0));
    assert_eq!(alice.read_game(), server_script(0, b"[DONE]"), "the close");
    let mut removed = vec![GC_CHARACTER_DEL];
    removed.extend_from_slice(&vid.to_le_bytes());
    assert_eq!(alice.read_game(), removed, "EncodeRemovePacket(this)");
    assert_eq!(
        alice.read_game(),
        a_warp_record((320_000, 1_529_000), server.channel(1).port()),
        "the recall spot on the run"
    );
    alice.quiet("the enter step ends");
    wait_for(
        database,
        "(SELECT map_index FROM player WHERE name = 'Alpha') = 2120000",
    );
}

/// The click's menu: the three owner chats and the close.
const MELEY_MENU: &[u8] = b"[QUESTION 1;The Sung Mahi dragons?|2;Fight the Sung Mahi dragons!|3;Go inside shelter!|4;Inchide]";

/// `say_title(mob_name(20419))` (`meleylair.lua`): the name from `en/mob_names.txt`
/// between the two `color256` ratios, then `say`'s blank line beyond `say_title`'s.
const MELEY_TITLE: &[u8] = b"[COLOR r;1|g;0.90196078431373|b;0.72941176470588]Gard\xe3 Dragon Dolnarr[COLOR r;0.76862745098039|g;0.76862745098039|b;0.76862745098039][ENTER][ENTER]";

/// The lore chat's first page, before the `wait()`.
const MELEY_LORE_FIRST: &[u8] = b"I fear that many will not grab the dawns of day...[ENTER][ENTER]Sung-Mahi, the demons god, has come back and also with[ENTER]their 3 dragons. They feed with human souls! Once they[ENTER]have eaten enough, Sung Mahi powers will grow... and[ENTER]that mean the end for all of us. We cannot allow this[ENTER]to happen, but it will require something more than just[ENTER]a brave warrior.[ENTER][ENTER]Only a united guild power can stand up to fight these[ENTER]frightening beasts. Can you help us? Do you know any other[ENTER]adventuriers brave as you? We have to warn all of them![ENTER][NEXT]";

/// The lore chat's last page, after the `wait()`.
const MELEY_LORE_LAST: &[u8] = b"I heard frightening stories about those warriors who want[ENTER]to fight the dragons. They never come back...[ENTER][DONE]";

/// The fight chat's ask: the requirements and the Yes/No.
const MELEY_ASK: &[u8] = b"To fight against Sung Mahi dragons you have to register[ENTER]the guild.[ENTER][ENTER]To register you need following requirments:[ENTER]- Guild must be at least level 3.[ENTER]- Guild must have at least 600 ladder points.[ENTER][ENTER]Do you want to register?[ENTER][QUESTION 1;Yes|2;No]";

/// The fight chat's register pass: `resultMsg[6]` with the 300 the register
/// kept (`meleylair.lua:57`).
const MELEY_REGISTERED: &[u8] = b"You\x27re guild was registered, if you defeat the dragons,[ENTER]300 ladder points will be returned to the guild.[ENTER][DONE]";

/// The fight chat's repeat refusal: `IsRegistered` reads the run on CH 1.
const MELEY_ALREADY: &[u8] = b"You\x27re guild is already registered! You can access[ENTER]the shelter from CH 1.[ENTER][ENTER][DONE]";

/// The shelter chat's ask.
const MELEY_SHELTER_ASK: &[u8] =
    b"Do you want to go inside shelter?[ENTER][ENTER][QUESTION 1;Yes|2;No]";

/// The shelter chat's `limit == 4` refusal: no guild PK mode.
const MELEY_NEED_GUILD_MODE: &[u8] =
    b"To can join the run you must have the combatent[ENTER]status checking in guild.[ENTER][DONE]";

/// Ledger 618's flag probe: the skill teacher (vnum 20300, bound but questless)
/// answers a click by setting `xmas_boom` to 1 from the quest side and saying so.
const FLAG_ARM_PROBE: &[u8] = b"quest flag_arm_probe begin\n\
    state start begin\n\
    when 20300.click begin\n\
    game.set_event_flag('xmas_boom', 1)\n\
    say('set')\n\
    end\n\
    end\n\
    end\n";

/// `lua.game.set_event_flag`, `sys.event.xmas`: the teacher's click sets `xmas_boom`
/// from a quest script, and the set runs the world's arm, not just the table: the
/// dialog lands first, then the `xmas_boom 1` ring, then map 1's firework seller
/// (9004) standing at its base plus 615 m, 618 m with its name behind its add.
/// Before the routing the ring and the seller never came; the GM lines (365) ran
/// the same arm from the other side.
#[test]
fn a_quest_set_flag_rings_its_arm_and_stands_its_seller() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    add_characters(&database);
    sql(&database, "UPDATE account SET empire = 1");
    sql(
        &database,
        "UPDATE player SET x = 471450, y = 954700 WHERE name = 'Alpha'",
    );
    let (server, _data) = Server::start_with_files_channels(
        binary(),
        database.url(),
        &[(
            "locale/europe/quest/zz_probe/flag_arm_probe.lua",
            FLAG_ARM_PROBE,
        )],
        &default_channels(),
        "no_wander = true",
    );
    let (mut alice, _alpha, entered) = enter_equipped_world_with(&server, b"alice", 0);
    let teacher = shown_vid(&entered, 20_300, "map 1 shows one skill teacher");
    alice.send_record(&client_click(teacher));
    assert_eq!(
        alice.read_game(),
        server_script(1, b"set[ENTER][DONE]"),
        "the dialog beats the arm"
    );
    assert_eq!(
        alice.read_game(),
        chat_packet(CHAT_TYPE_COMMAND, 1, b"xmas_boom 1"),
        "the quest-set flag rings"
    );
    assert_eq!(
        read_add_of_race(&mut alice, 9004),
        (409_600 + 61_500, 896_000 + 61_800),
        "map 1's firework seller stands at its base plus 615 m, 618 m"
    );
    assert_eq!(
        alice.read_game()[0],
        GC_CHAR_ADDITIONAL_INFO,
        "the seller's name rides behind its add"
    );
    alice.still("nothing follows");
    drop(server);
}

const YOHARA_HYDRA_CONGRATS: &[u8] = b"[COLOR r;1|g;0.90196078431373|b;0.72941176470588]Statuia Razboinicului: [COLOR r;0.76862745098039|g;0.76862745098039|b;0.76862745098039][ENTER][ENTER]Felicitari.[ENTER]Te astept unde am vorbit ultima data. [ENTER][ENTER][DONE]";

/// The statue's menu at `killReward_new`: the ship's return, the Yohara trip, the
/// reward chat, and the close.
const YOHARA_STATUE_MENU: &[u8] =
    b"[QUESTION 1;Return|2;Un continent nou|3;Devino Campion  |4;Inchide]";

/// The reward chat (`20433.chat."Devino Campion  "`, `yohara_system.lua:98-112`):
/// the 0xe7 byte is the mob name's CP949 `\xb1`, carried byte-exact.
const YOHARA_CHAMPION_REWARD: &[u8] = b"[COLOR r;1|g;0.90196078431373|b;0.72941176470588]Savas\xe7i heykeli[COLOR r;0.76862745098039|g;0.76862745098039|b;0.76862745098039][ENTER][ENTER]Felicitari sincere.. [ENTER]Ai invins Hydra. Acum ti-ai dovedit puterea.[ENTER]Poti avansa la nivelul de campion acum. [ENTER][ENTER][COLOR r;1|g;0.7843137254902|b;0.7843137254902]Ai trecut la nivelul de campion[COLOR r;0.76862745098039|g;0.76862745098039|b;0.76862745098039][ENTER][DONE]";

/// The twenty point records `SetConqueror`'s reset and recompute send
/// (`G/char.cpp:11678-11697`): the next-exp arm, the first compute's seven, the
/// level arm with the speed and the three zeroed bonuses, the second compute's
/// seven, and the two pool maxima.
fn read_conqueror_reset(keyed: &mut Keyed, own: u32) {
    for (kind, value, note) in [
        (176_u8, 433_400_i64, "the conqueror next exp"),
        (18, 240, "the attack grade"),
        (20, 120, "the client defence grade"),
        (16, 120, "the defence grade"),
        (20, 120, "the client defence grade again"),
        (22, 240, "the magic attack grade"),
        (23, 120, "the magic defence grade"),
        (173, 1, "the conqueror level"),
        (17, 100, "the attack speed"),
        (53, 0, "the monster bonus"),
        (146, 0, "the metin bonus"),
        (147, 0, "the boss bonus"),
        (18, 240, "the attack grade recomputed"),
        (20, 120, "the client defence grade recomputed"),
        (16, 120, "the defence grade recomputed"),
        (20, 120, "the client defence grade recomputed again"),
        (22, 240, "the magic attack grade recomputed"),
        (23, 120, "the magic defence grade recomputed"),
        (6, 650, "the max hit points"),
        (8, 200, "the max spirit points"),
    ] {
        assert_eq!(
            keyed.read_game(),
            point_change(own, kind, 0, value),
            "{note}"
        );
    }
}

/// Stage [`a_hydra_kill_moves_yohara_to_its_champion_reward`]: the owner's mob
/// proto with the Hydra (3965) shrunk to level 1 with 1 hit point, map 1's regen
/// with one at the entrant's feet, and map 1's NPCs with the warrior statue
/// (20433) beside it.
fn yohara_champion_stage(database: &ScratchDatabase) -> (Server, PathBuf) {
    create_account_before_boot(database, "alice");
    add_characters(database);
    sql(database, "UPDATE account SET empire = 1");
    sql(
        database,
        "UPDATE player SET x = 469600, y = 948500, level = 120, exp = 625000000 WHERE name =          'Beta'",
    );
    // The CRC32 of `killMonsters_new`, as a signed `integer`.
    sql(
        database,
        "INSERT INTO quest_flag (player_id, name, value) SELECT player.id,          'yohara_system.__status'::bytea, -332622545 FROM player WHERE player.name = 'Beta'",
    );
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../legacy/gamedata");
    let owner = std::fs::read(root.join("proto/mob_proto.txt")).expect("mob proto");
    let mut proto = Vec::new();
    for line in owner.split_inclusive(|&byte| byte == b'\n') {
        if line.starts_with(b"3965\t") {
            let mut cells: Vec<&[u8]> = line
                .strip_suffix(b"\r\n")
                .expect("CRLF")
                .split(|&byte| byte == b'\t')
                .collect();
            assert_eq!(cells.len(), 72, "the 3965 line keeps its columns");
            cells[5] = b"1";
            cells[14] = b"1";
            cells[18] = b"1";
            cells[19] = b"1";
            cells[20] = b"1";
            proto.extend_from_slice(&cells.join(&b'\t'));
            proto.extend_from_slice(b"\r\n");
        } else {
            proto.extend_from_slice(line);
        }
    }
    let mut regen =
        std::fs::read(root.join("locale/europe/map/metin2_map_a1/regen.txt")).expect("a1 regen");
    regen.extend_from_slice(b"m\t600\t525\t1\t1\t0\t0\t60s\t100\t1\t3965\n");
    let mut npcs =
        std::fs::read(root.join("locale/europe/map/metin2_map_a1/npc.txt")).expect("a1 npcs");
    npcs.extend_from_slice(b"m\t600\t525\t0\t0\t0\t1\t1s\t100\t1\t20433\n");
    let (server, data) = Server::start_with_files_channels(
        binary(),
        database.url(),
        &[
            ("proto/mob_proto.txt", &proto),
            ("locale/europe/map/metin2_map_a1/regen.txt", &regen),
            ("locale/europe/map/metin2_map_a1/npc.txt", &npcs),
        ],
        &default_channels(),
        "no_wander = true",
    );
    (server, data)
}

/// `quest.yohara_system`'s Hydra kill and champion reward over the live script:
/// Beta, level 120 with the filled marble (`exp = next_exp(120) / 4`) and the quest
/// at `killMonsters_new`, enters beside the staged Hydra and the warrior statue.
/// A punch kills the Hydra (`3965.kill` counts 1, resets, says the congrats and
/// moves the quest to `killReward_new`); the click then offers the reward chat,
/// and "Devino Campion" runs `pc.set_conqueror`, which makes Beta a champion
/// (the reward page, the begin-bit clear, the reset's point records, the gold and
/// points pair, and the trailing conqueror-exp record), clears the letter
/// (`q.done`) and completes the quest. The marrow: the grant lands on no exp
/// record, because an over-cap character's filled marble silences `gain_exp`
/// (`G/char.cpp:4113-4116`); the stored row keeps conqueror level 1 and the
/// `__COMPLETE__` status.
#[test]
fn a_hydra_kill_moves_yohara_to_its_champion_reward() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let (mut server, _data) = yohara_champion_stage(&database);
    let (mut alice, _beta, _items) = load_character(&server, b"alice", 1);
    let (entered, _cooldown) = enter_game_view_cells(&mut alice);
    let hydras = vids_of_race(&entered.shown, 3965);
    assert_eq!(hydras.len(), 1, "map 1 shows the staged Hydra");
    let statue = shown_vid(&entered, 20_433, "map 1 shows its statue");
    let own = u32::from_le_bytes(entered.add[1..5].try_into().expect("four bytes"));
    alice.send_record(&client_target(hydras[0]));
    assert_eq!(alice.read_game()[0], 0x3f, "the target answers");
    alice.send_record(&client_attack(hydras[0]));
    for (want, note) in [
        (0x87_u8, "the damage"),
        (0x3f, "the hit points"),
        (0x0d, "the stun"),
        (0x3f, "the clear"),
        (0x46, "the orb"),
    ] {
        assert_eq!(alice.read_fight()[0], want, "{note}");
    }
    assert_eq!(
        alice.read_fight(),
        server_script(1, YOHARA_HYDRA_CONGRATS),
        "the kill's congrats"
    );
    for (want, note) in [(0x0e_u8, "the death"), (0x02, "the corpse leaves")] {
        assert_eq!(alice.read_fight()[0], want, "{note}");
    }
    alice.send_record(&client_click(statue));
    assert_eq!(
        alice.read_game(),
        server_script(1, YOHARA_STATUE_MENU),
        "the reward chat joins the menu"
    );
    alice.send_record(&client_script_answer(2));
    assert_eq!(
        alice.read_game(),
        server_script(1, YOHARA_CHAMPION_REWARD),
        "the reward page"
    );
    assert_eq!(
        alice.read_game(),
        quest_begin_clear(49),
        "the letter's `q.done` clears yohara's begin bit"
    );
    read_conqueror_reset(&mut alice, own);
    let mut gold = vec![GC_CHARACTER_GOLD];
    gold.extend_from_slice(&0_u64.to_le_bytes());
    assert_eq!(alice.read_game(), gold, "the gold record");
    let points = alice.read_game();
    assert_eq!(points[0], GC_PLAYER_POINTS, "the points record");
    for (slot, value, note) in [
        (1_usize, 120_i64, "the level stays"),
        (3, 625_000_000, "the experience stays"),
        (173, 1, "the conqueror level"),
        (175, 0, "the conqueror experience"),
        (176, 433_400, "the conqueror next"),
    ] {
        assert_eq!(point_slot(&points, slot), value, "{note}");
    }
    assert_eq!(
        alice.read_game(),
        point_change(own, 175, 0, 0),
        "the trailing conqueror-exp record"
    );
    alice.still("nothing follows");
    drop(alice);
    server.wait_for("Character disconnected; wrote the row");
    check(
        &database,
        "(SELECT conqueror_level FROM player WHERE name = 'Beta') = 1 AND (SELECT value FROM          quest_flag WHERE player_id = (SELECT id FROM player WHERE name = 'Beta') AND name =          'yohara_system.__status'::bytea) = 668443392",
    );
    drop(server);
}

