/// `event.item.ownership_event` (`G/item.cpp:1704-1728`): the diamond ore a +9 pick digs at
/// mining 40 lies owned by the digger, and 15 s on the empty-name record goes around it.
/// The row turns `ported`: the destroy sweep's twin finally has its scenario (ledger 229p's
/// D5 wait ends at the vein, not at a kill).
#[test]
fn a_dug_ore_loses_its_diggers_name_fifteen_seconds_on() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let (server, digger) = vein_stage(&database, MINING_PROBE);
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 50, id, 2, 4,          1, 29110 FROM player WHERE name = 'Alpha'",
    );
    sql(
        &database,
        "INSERT INTO gm_grant (account_id, name, authority) SELECT id, 'Alpha', 'HIGH_WIZARD'          FROM account WHERE login = 'alice'",
    );
    let (mut alice, _alpha, entered) = enter_equipped_world_with(&server, b"alice", 1);
    let vid = u32::from_le_bytes(entered.add[1..5].try_into().expect("four bytes"));
    let vein = shown_vein(&entered);
    alice.send_record(&client_chat(CHAT_TALKING, b"/setskill 124 40"));
    let wire = alice.wire_for(std::time::Duration::from_secs(2));
    assert!(
        wire.iter().any(|record| record[0] == GC_SKILL_LEVEL_NEW),
        "mining stands at 40"
    );
    let mut ore = Vec::new();
    for _ in 0..4 {
        let started = std::time::Instant::now();
        let strokes = u64::from(start_digging(&mut alice, vid, vein));
        let deadline = started + Duration::from_secs(2 * strokes + 2);
        let ended = alice.read_game_until(deadline).expect("the dig ends");
        if ended[0] == GROUND_ADD {
            ore = ended;
            break;
        }
        assert_eq!(ended, an_info_line(b"Mining failed."), "a miss");
        // Half the digs practice the maxed pick: the topped pair rides behind.
        let tail = started + Duration::from_secs(2 * strokes + 5);
        if let Some(line) = alice.read_game_until(tail) {
            assert_eq!(
                line,
                an_info_line(b"The pickaxe has reached its maximum training level."),
                "the topped pair leads"
            );
            assert_eq!(
                alice.read_game(),
                an_info_line(b"You can upgrade to the next level pickaxe through the woodcutter."),
                "and follows"
            );
        }
    }
    assert_eq!(ore[0], GROUND_ADD, "four digs at 81% land an ore");
    let field = |at: usize| i32::from_le_bytes(ore[at..at + 4].try_into().expect("four"));
    assert_eq!(field(17), 50_601, "the vein's raw ore");
    let mut owned = vec![GC_ITEM_OWNERSHIP];
    owned.extend_from_slice(&ore[13..17]);
    let mut name = [0u8; 25];
    name[..5].copy_from_slice(b"Alpha");
    owned.extend_from_slice(&name);
    assert_eq!(alice.read_game(), owned, "the digger owns the ore");
    assert_eq!(alice.read_game(), an_info_line(b"Mining was successful."));
    let owned_at = std::time::Instant::now();
    let mut freed = vec![GC_ITEM_OWNERSHIP];
    freed.extend_from_slice(&ore[13..17]);
    freed.extend_from_slice(&[0u8; 25]);
    let deadline = owned_at + Duration::from_secs(20);
    loop {
        let record = alice
            .read_game_until(deadline)
            .expect("the ownership lapses");
        if record == freed {
            break;
        }
    }
    assert!(
        owned_at.elapsed() >= Duration::from_millis(14_500),
        "fifteen seconds on: {:?}",
        owned_at.elapsed()
    );
    let _ = digger;
}

/// The revive probe entered: the staged server, Alpha keyed, her row, and the burst that
/// showed the group — the swing ends the revive, as `alpha_swinging_by`'s does.
fn revive_enter(database: &ScratchDatabase) -> (Server, Keyed, Listed, Entered) {
    let server = revive_stage(database);
    let (mut alpha, listed, _items) = load_character(&server, b"alice", 0);
    let entered = enter_game_shown(&mut alpha);
    read_login_event(&mut alpha);
    let swing = client_move(
        FUNC_ATTACK,
        7,
        40,
        ALPHA_ENTERS_AT.0,
        ALPHA_ENTERS_AT.1,
        0x5eed,
    );
    alpha.send_record(&swing);
    let update = read_past_pings(&mut alpha);
    assert_eq!(update[0], GC_CHARACTER_UPDATE, "{update:02x?}");
    assert!(alpha.timer_record(&update), "the swing ends the revive");
    assert_eq!(
        read_past_pings(&mut alpha),
        [GC_AFFECT_REMOVE, 215, 0, 0, 0, 0]
    );
    alpha.quiet("the swing is not relayed to the swinger");
    (server, alpha, listed, entered)
}

/// The reviver's 3 s past `died`: the remove, then the insert of the same dog, re-targeted
/// to full hit points.
fn revive_stand_up(alpha: &mut Keyed, victim: u32, died: std::time::Instant) {
    revive_next(
        alpha,
        &removal_of(victim),
        Duration::from_secs(8),
        "the dead dog goes",
    );
    assert!(
        died.elapsed() >= Duration::from_millis(2_500),
        "the reviver waits 75 Pulses: {:?}",
        died.elapsed()
    );
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    let insert = loop {
        let record = alpha
            .read_fight_until(deadline)
            .expect("the reviver stands the dog up");
        if record[0] == GC_CHARACTER_ADD
            && u32::from_le_bytes(record[1..5].try_into().expect("a VID")) == victim
        {
            break record;
        }
    };
    assert_eq!(
        u16::from_le_bytes(insert[22..24].try_into().expect("a race")),
        101,
        "the same dog stands"
    );
    alpha.send_record(&client_target(victim));
    revive_next(
        alpha,
        &target_of(victim, 100, DOG_HP, DOG_HP, 0),
        Duration::from_secs(5),
        "the stood dog is full",
    );
}

/// The second death's destroy: no orb past the spent exp, the remove 25 Pulses on (not
/// the reviver's 75), and no third life in the 3 s after.
fn revive_destroy(alpha: &mut Keyed, victim: u32, alpha_vid: u32) {
    let mut orbless = true;
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    let died_again = loop {
        let record = alpha
            .read_fight_until(deadline)
            .expect("the victim dies again");
        if record == fly_of(FLY_EXP, victim, alpha_vid) {
            orbless = false;
        }
        if record == dead_of(victim) {
            break std::time::Instant::now();
        }
    };
    assert!(orbless, "the spent exp flies no orb");
    let deadline = std::time::Instant::now() + Duration::from_secs(8);
    let mut third_life = false;
    loop {
        let record = alpha.read_fight_until(deadline).expect("the destroy comes");
        if record == removal_of(victim) {
            break;
        }
        if record[0] == GC_CHARACTER_ADD
            && u32::from_le_bytes(record[1..5].try_into().expect("a VID")) == victim
        {
            third_life = true;
        }
    }
    assert!(
        died_again.elapsed() >= Duration::from_millis(750),
        "the dead dog lies 25 Pulses: {:?}",
        died_again.elapsed()
    );
    assert!(
        died_again.elapsed() < Duration::from_millis(2_500),
        "not the reviver's 75: {:?}",
        died_again.elapsed()
    );
    assert!(!third_life, "once revived stays dead");
    let deadline = std::time::Instant::now() + Duration::from_secs(3);
    while let Some(record) = alpha.read_fight_until(deadline) {
        assert!(
            record[0] != GC_CHARACTER_ADD
                || u32::from_le_bytes(record[1..5].try_into().expect("a VID")) != victim,
            "no third life"
        );
    }
}

/// The next fight record matching `want`, skipping the reviver's party assist.
fn revive_next(alpha: &mut Keyed, want: &[u8], within: std::time::Duration, why: &str) -> Vec<u8> {
    let deadline = std::time::Instant::now() + within;
    loop {
        let record = alpha
            .read_fight_until(deadline)
            .unwrap_or_else(|| panic!("{why}"));
        if record == want {
            return record;
        }
    }
}

/// The probe victim punched to a stun: the attack, the damage, the fallen hit points and
/// the stun, strays skipped.
fn revive_punch_to_stun(alpha: &mut Keyed, victim: u32, why: &str) {
    alpha.send_record(&client_attack(victim));
    revive_next(
        alpha,
        &damage_info(victim, DAMAGE_NORMAL, PUNCH_ON_THE_DOG),
        Duration::from_secs(5),
        &format!("{why} lands"),
    );
    revive_next(
        alpha,
        &target_of(victim, 0, 0, DOG_HP, 0),
        Duration::from_secs(5),
        "the hit points fall",
    );
    revive_next(
        alpha,
        &stun_of(victim),
        Duration::from_secs(5),
        "the stun lands",
    );
}

/// `event.char_battle.dead_event`'s party reviver (`G/char_battle.cpp:529-541`, `:1599-1610`):
/// the probe group stands 101 with its reviver 102; the first kill waits 3 s and the dog
/// stands back up at full hit points, and the second kill waits 1 s and destroys it — the
/// exp already spent, no orb and no more gold (`SetExp(0)`, `:2894`, pre-empts `Reward(false)`).
/// The row turns `ported`: the last `partial` timer closes.
#[test]
fn a_revived_dog_stands_back_up_once_and_dies_for_good_the_second_time() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let (server, mut alpha, listed, entered) = revive_enter(&database);
    let _ = server;
    let ones = vids_of_race(&entered.shown, 101);
    let twos = vids_of_race(&entered.shown, 102);
    assert_eq!(ones.len(), 1, "the probe victim stands: {ones:?}");
    assert_eq!(twos.len(), 1, "the probe reviver stands: {twos:?}");
    let (victim, reviver) = (ones[0], twos[0]);
    let _ = reviver;

    // The first kill: the punch, the stun, and 3 s on the death.
    alpha.send_record(&client_target(victim));
    revive_next(
        &mut alpha,
        &target_of(victim, 100, DOG_HP, DOG_HP, 0),
        Duration::from_secs(5),
        "the victim targets at full",
    );
    let alpha_vid = listed.id;
    let _ = listed;
    revive_punch_to_stun(&mut alpha, victim, "the punch");
    revive_next(
        &mut alpha,
        &ownership_of(alpha_vid, victim),
        Duration::from_secs(5),
        "the claim lands",
    );
    revive_next(
        &mut alpha,
        &target_of(0, 0, 0, 0, 0),
        Duration::from_secs(8),
        "the stun ends",
    );
    revive_next(
        &mut alpha,
        &ownership_of(0, victim),
        Duration::from_secs(5),
        "the claim clears",
    );
    revive_next(
        &mut alpha,
        &point_change(alpha_vid, POINT_EXP, 0, 0),
        Duration::from_secs(5),
        "the empty exp record",
    );
    revive_next(
        &mut alpha,
        &fly_of(FLY_EXP, victim, alpha_vid),
        Duration::from_secs(5),
        "the exp orb",
    );
    revive_next(
        &mut alpha,
        &dead_of(victim),
        Duration::from_secs(5),
        "the victim dies",
    );
    let died = std::time::Instant::now();

    revive_stand_up(&mut alpha, victim, died);

    // The second kill: the punch, the stun, and 3 s on the death — with no orb, the exp
    // spent — then 1 s on the destroy, and no third life.
    revive_punch_to_stun(&mut alpha, victim, "the second punch");
    revive_next(
        &mut alpha,
        &target_of(0, 0, 0, 0, 0),
        Duration::from_secs(8),
        "the stun ends again",
    );
    revive_destroy(&mut alpha, victim, alpha_vid);
}

/// Ledger 561: a blow on the Blue Dragon shrinks per live defence stone, and the
/// dragon's own blow grows per live attack stone (`BlueDragon_Damage`,
/// `G/BlueDragon.cpp:139-196`). Map 1 holds only the two stones (8031 defends,
/// 8032 attacks) and the dragon (2493), all on the proven cell beside Alpha's
/// entry; its punch lands the pinned shrunk number, and the dragon's first
/// swing lands the pinned grown one. The file swap clears the town's idle churn and
/// the patched proto leaves no value-feeding draw on either path. The stones never spawn on
/// the owner's data (no map regen, no quest spawn, the boss-event map 230
/// unhosted), so the arms fire here only because the files stood them.
///
/// The dragon's regen lines, as the dog's: `m`, the cell, no scatter, `1000s`.
const DRAGON_LINES: &str = "m\t605\t540\t0\t0\t0\t1\t1000s\t100\t1\t8031\n\
     m\t605\t540\t0\t0\t0\t1\t1000s\t100\t1\t8032\n\
     m\t605\t540\t0\t0\t0\t1\t1000s\t100\t1\t2493\n";

/// The owner's mob proto with the dragon's damage flattened to 200, its defence
/// to 0 and its critical and penetrate enchants to 0: the punch rates past the
/// `battle_damage_floor` draw, and the swing's only draws left feed nothing the
/// head asserts, so both numbers pin (the dice seed is random per boot).
fn dragon_proto(owner: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    for line in owner.split_inclusive(|&byte| byte == b'\n') {
        if line.starts_with(b"2493\t") {
            let mut cells: Vec<&[u8]> = line
                .strip_suffix(b"\r\n")
                .expect("the owner's CRLF")
                .split(|&byte| byte == b'\t')
                .collect();
            assert_eq!(cells.len(), 72, "the 2493 line keeps its columns");
            cells[18] = b"200";
            cells[19] = b"200";
            cells[26] = b"0";
            cells[38] = b"0";
            cells[39] = b"0";
            out.extend_from_slice(&cells.join(&b'\t'));
            out.extend_from_slice(b"\r\n");
        } else {
            out.extend_from_slice(line);
        }
    }
    out
}
#[test]
fn the_dragon_stones_scale_the_dragons_blows_both_ways() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    add_characters(&database);
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../legacy/gamedata");
    let proto = dragon_proto(
        &std::fs::read(root.join("proto/mob_proto.txt")).expect("the owner's mob proto"),
    );
    let (server, _data) = Server::start_with_files(
        binary(),
        database.url(),
        &[
            ("proto/mob_proto.txt", &proto),
            (
                "locale/europe/map/metin2_map_a1/npc.txt",
                DRAGON_LINES.as_bytes(),
            ),
            ("locale/europe/map/metin2_map_a1/regen.txt", b""),
            ("locale/europe/map/metin2_map_a1/stone.txt", b""),
            ("locale/europe/map/metin2_map_a1/boss.txt", b""),
        ],
    );
    let (mut alice, listed, _items) = load_character(&server, b"alice", 0);
    let entered = enter_game_shown(&mut alice);
    read_login_event(&mut alice);
    let defence = vids_of_race(&entered.shown, 8031);
    let attack = vids_of_race(&entered.shown, 8032);
    let dragon = vids_of_race(&entered.shown, 2493);
    assert_eq!(defence.len(), 1, "one defence stone stands");
    assert_eq!(attack.len(), 1, "one attack stone stands");
    assert_eq!(dragon.len(), 1, "one dragon stands");
    let (defence, dragon) = (defence[0], dragon[0]);

    // Given: the files stood all three; nothing else idles on the map.

    // When: Alpha punches the dragon with the defence stone live.
    alice.send_record(&client_target(dragon));
    assert_eq!(
        alice.read_game(),
        target_of(dragon, 100, DRAGON_HP, DRAGON_HP, 1),
        "the dragon targets whole"
    );
    alice.send_record(&client_attack(dragon));
    let sp = u8::try_from(common::point_slot::POINT_SP).expect("a point byte");
    assert_eq!(
        alice.read_fight(),
        point_change(listed.id, sp, 0, 500),
        "the dragon drains 100 spell points"
    );
    // 172 rated, minus a quarter for the one live 8031: 172 - 43 = 129.
    assert_eq!(
        alice.read_fight(),
        damage_info(dragon, DAMAGE_NORMAL, 129),
        "the punch shrinks a quarter"
    );
    assert_eq!(
        alice.read_fight(),
        target_of(dragon, 99, DRAGON_HP - 129, DRAGON_HP, 0),
        "the broadcast carries no element"
    );
    assert_eq!(
        alice.read_fight(),
        ownership_of(listed.id, dragon),
        "the punch claims the dragon"
    );
    // Then: the dragon's first swing, with the attack stone live: 1244 rated,
    // plus a quarter for the one live 8032: 1244 + 311 = 1555.
    let deadline = std::time::Instant::now() + Duration::from_secs(30);
    let (damage, flag, effects) = read_swing_head(&mut alice, dragon, listed.id, deadline);
    assert_eq!(
        (damage, flag, effects),
        (1555, DAMAGE_NORMAL, Vec::new()),
        "the swing grows a quarter"
    );
    let _ = defence;
    drop(alice);
}

/// Ledger 568: Delta the sura learns 63 (`Tais Vrajit`), casts it naked, and the next affect
/// tick strips it: the weapon aura's flag is set with no weapon worn (`UpdateAffect`,
/// `G/char_affect.cpp:168-174`). The cast's add lands first, then — within the tick's ~1 s —
/// the remove, with no SP spent between them (the strip takes the row before the drain, so
/// starvation cannot be the cause; Delta's 300 SP covers the 25-a-tick cost regardless).
#[test]
fn a_naked_aura_is_stripped_on_the_next_tick() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "UPDATE player SET skill_group = 1, skill_point = 1, sp = 200, x = 480000, y = 960000 \
         WHERE name = 'Delta'",
    );
    // Delta's stored spot is map 2, which no Channel hosts; map 1 loads.
    let (mut delta, listed, _items) = load_character(&server, b"alice", 3);
    let vid = listed.id;
    let _entered = enter_game_shown(&mut delta);
    read_login_event(&mut delta);
    delta.send_record(&client_chat(CHAT_TALKING, b"/skillup 63"));
    let mut saw_spend = false;
    let mut burst = Vec::new();
    for _ in 0..8 {
        let record = delta.read_game();
        if record == point_change(vid, 28, 0, 0) {
            assert!(!saw_spend, "one spend");
            saw_spend = true;
            continue;
        }
        if record[0] == GC_SKILL_LEVEL_NEW {
            burst = record;
            break;
        }
        panic!("past a skill-up, a record nobody accounted for: {record:02x?}");
    }
    assert!(saw_spend, "the spend lands");
    assert_eq!(burst[1 + 63 * 6], 0, "master 0");
    assert_eq!(burst[1 + 63 * 6 + 1], 1, "level 1");
    let mut cast = vec![CG_USE_SKILL];
    cast.extend_from_slice(&63_u32.to_le_bytes());
    cast.extend_from_slice(&vid.to_le_bytes());
    delta.send_record(&cast);
    let mut saw_add = false;
    for _ in 0..8 {
        let record = delta.read_game();
        if record[0] == GC_AFFECT_ADD {
            let kind = u32::from_le_bytes(record[1..5].try_into().expect("four bytes"));
            assert_eq!(kind, 63, "the cast's aura: {record:02x?}");
            saw_add = true;
            break;
        }
    }
    assert!(saw_add, "the cast lands its aura");
    // The cast laid two rows (the point and the point2 arms); the tick strips both.
    let mut removes = Vec::new();
    for _ in 0..16 {
        let record = delta.read_game();
        if record[0] == GC_AFFECT_REMOVE {
            let kind = u32::from_le_bytes(record[1..5].try_into().expect("four bytes"));
            if kind == 63 {
                removes.push(record[5]);
            }
            if removes.len() == 2 {
                break;
            }
        }
    }
    removes.sort_unstable();
    assert_eq!(
        removes,
        [95, 100],
        "the next tick strips the naked aura's rows"
    );
}

/// The gauge's start pair on the runner's stream: the zero-change record and the
/// command line with the rate and the pool it carries (ledger 569).
fn read_gauge_start(runner: &mut Keyed, vid: u32) {
    let zero = read_past_pings(runner);
    let pool = point_value(&zero, vid, 9).expect("the start's zero");
    let line = read_past_pings(runner);
    assert_eq!(
        line[3..9],
        [CHAT_TYPE_COMMAND, 0, 0, 0, 0, line[8]],
        "a command line"
    );
    assert!(
        line.ends_with(format!("StartStaminaConsume 25 {pool}").as_bytes()),
        "the gauge starts with the rate and the pool: {line:02x?}"
    );
}

/// The swing that stamps the fight, as the swinger and its viewer read it: the
/// revive-ending update, the remove, and the relayed swing (ledger 569's stage).
fn alpha_swings_before_yankee(alpha: &mut Keyed, yankee: &mut Keyed, vid: u32) {
    let swing = client_move(
        FUNC_ATTACK,
        7,
        40,
        ALPHA_ENTERS_AT.0,
        ALPHA_ENTERS_AT.1,
        0x5eed,
    );
    alpha.send_record(&swing);
    let update = read_past_pings(alpha);
    assert_eq!(update[0], GC_CHARACTER_UPDATE, "{update:02x?}");
    assert!(alpha.timer_record(&update), "the swing ends the revive");
    assert_eq!(read_past_pings(alpha), [GC_AFFECT_REMOVE, 215, 0, 0, 0, 0]);
    alpha.quiet("the swing is not relayed to the swinger");
    let seen = read_past_pings(yankee);
    assert_eq!(seen[0], GC_CHARACTER_UPDATE, "{seen:02x?}");
    assert!(yankee.timer_record(&seen), "the viewer sees the revive end");
    assert_eq!(
        read_past_pings(yankee),
        relayed_move(&swing, vid, 0),
        "the viewer sees the swing"
    );
}

/// The widths of a watching stream: the relay, the fans, the revive records, and pings.
fn watch_width(header: u8) -> usize {
    match header {
        GC_PING => 1,
        GC_MOVE => GC_MOVE_LEN,
        GC_WALK_MODE => 6,
        GC_AFFECT_REMOVE => AFFECT_REMOVE_LEN,
        GC_CHARACTER_UPDATE => CHARACTER_UPDATE_LEN,
        other => panic!("on the watching stream, a record nobody accounted for: {other}"),
    }
}

/// Whether `want` fans on the watching stream within `rounds` one-second drains.
fn wait_for_fan(yankee: &mut Keyed, want: &[u8], rounds: u32) -> bool {
    for _ in 0..rounds {
        let (records, _) = yankee.drain_game(Duration::from_secs(1), watch_width);
        if records.iter().any(|record| record == want) {
            return true;
        }
    }
    false
}

/// The consume arc's six records on the runner's stream: the start's zero and line, the
/// walk fan, the spend's zero, and the stop's zero and line, past the inserts.
fn collect_consume(alpha: &mut Keyed, vid: u32, walk: &[u8]) -> Vec<Vec<u8>> {
    let mut consumed: Vec<Vec<u8>> = Vec::new();
    for _ in 0..64 {
        let record = read_past_pings(alpha);
        if record[0] == GC_POINT_CHANGE && point_value(&record, vid, 9).is_some()
            || record[0] == GC_CHAT
            || record == walk
        {
            consumed.push(record);
            if consumed.len() == 6 {
                break;
            }
        }
    }
    consumed
}

/// Ledger 569 (V3): a run after a fight spends stamina a point a step, the drain silent,
/// until the pool empties and the flag walks with a mode record; a walk past five seconds
/// restores the pool to 890 (800 + 5 * 18 vitality) and the climb off 0 restores the mode
/// line's run, the switch fanning before the point record. Alpha stores stamina 3, swings
/// (the attack stamps the fight), and runs 1600 south; Yankee stands and watches the fans,
/// whose stream stays free of inserts. The refill's three idle seconds elapse mid-walk, so
/// the refill (ledger 229d) sends the restore; the walk arm's own five-second restore, for
/// chained moves whose accepts keep the idle count short, is pinned by unit tests. The
/// first spend starts the client's gauge and the emptying step stops it, each with a
/// zero-change record and a command line (V4).
#[test]
fn a_run_after_a_swing_spends_stamina_then_walks_and_restores() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    create_account(&server, "bob");
    add_characters(&database);
    seat_yankee_and_charlie(&database);
    stamina(&database, "Alpha", 3);
    let (mut alpha, listed, _) = enter_world_seeing(&server, b"alice", 0);
    let vid = listed.id;
    let (mut yankee, yankee_listed, yankee_entered) = enter_world_seeing(&server, b"bob", 0);
    let (_, _, yankee_info, _) = alpha.sees_enter(yankee_listed.id, false, None);
    assert_eq!(
        yankee_info, yankee_entered.info,
        "the summary Yankee got of itself"
    );
    alpha_swings_before_yankee(&mut alpha, &mut yankee, vid);
    let south = client_move(FUNC_MOVE, 0, 0, 470_100, 951_700, 0x5eee);
    alpha.send_record(&south);
    let relay = read_past_pings(&mut yankee);
    assert_eq!(relay[0], GC_MOVE, "the viewer sees the run");
    assert_eq!(&relay[1..4], &south[1..4], "the run's echo");
    let walk = [
        GC_WALK_MODE,
        vid.to_le_bytes()[0],
        vid.to_le_bytes()[1],
        vid.to_le_bytes()[2],
        vid.to_le_bytes()[3],
        1,
    ];
    assert!(
        wait_for_fan(&mut yankee, &walk, 5),
        "the emptied pool walks the flag"
    );
    // Re-target mid-flight, while the run still runs: the flag now walks at the walk
    // clip, so the motion outlasts the refill's three idle seconds.
    alpha.send_record(&client_move(FUNC_MOVE, 0, 0, 470_100, 951_700, 0x5eef));
    let consumed = collect_consume(&mut alpha, vid, &walk);
    assert_eq!(
        consumed.len(),
        6,
        "the start, the drain and the stop: {consumed:02x?}"
    );
    assert_eq!(
        consumed[0],
        point_change(vid, 9, 0, 2),
        "the start sends its zero"
    );
    let empire = consumed[1][8];
    assert_eq!(
        consumed[1],
        chat_packet(CHAT_TYPE_COMMAND, empire, b"StartStaminaConsume 25 2"),
        "the gauge starts with the rate and the pool"
    );
    assert_eq!(consumed[2], walk, "the switch fans before the zero");
    assert_eq!(
        consumed[3],
        point_change(vid, 9, 0, 0),
        "the emptying step sends its zero"
    );
    assert_eq!(
        consumed[4],
        point_change(vid, 9, 0, 0),
        "the stop sends its zero"
    );
    assert_eq!(
        consumed[5],
        chat_packet(CHAT_TYPE_COMMAND, empire, b"StopStaminaConsume 0"),
        "the gauge stops with the pool"
    );
    let run = [
        GC_WALK_MODE,
        vid.to_le_bytes()[0],
        vid.to_le_bytes()[1],
        vid.to_le_bytes()[2],
        vid.to_le_bytes()[3],
        0,
    ];
    assert!(
        wait_for_fan(&mut yankee, &run, 14),
        "the climb off 0 restores the run"
    );
    let mut refilled = false;
    for _ in 0..300 {
        let record = read_past_pings(&mut alpha);
        if record == point_change(vid, 9, 0, 890) {
            refilled = true;
            break;
        }
    }
    assert!(refilled, "the walk restores the pool");
}

/// `G/char_battle.cpp:1411-1442`: the same-empire killer loses 20 000 alignment when its
/// victim dies. Dave of empire 1 goes free and kills Alpha of empire 1 standing at one
/// hit point; three seconds on, the death runs and Dave's update carries -2000 in
/// tenths. The spare draw would carry the `[LS;910]` line instead, pinned by the world
/// tests of `game_state::death`; the dice here pays on the live seed.
#[test]
fn a_same_empire_kill_costs_the_killer_20000_alignment() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    create_account(&server, "dave");
    add_characters(&database);
    sql(
        &database,
        "UPDATE account SET empire = 1 WHERE login = 'dave'",
    );
    sql(
        &database,
        "INSERT INTO player (account_id, slot, name, job, level, x, y) SELECT id, 0, 'Dave', 1, \
         154, 470100, 950100 FROM account WHERE login = 'dave'",
    );
    sql(
        &database,
        "UPDATE player SET stamina = 12345 WHERE name = 'Dave'",
    );
    sql(&database, "UPDATE player SET hp = 1 WHERE name = 'Alpha'");
    let (mut alpha, alpha_listed, _alpha_entered) = enter_world_seeing(&server, b"alice", 0);
    let (mut dave, dave_listed, _dave_entered) = enter_world_seeing(&server, b"dave", 0);
    alpha.sees_enter(dave_listed.id, false, None);
    dave.send_record(&client_chat(CHAT_TALKING, b"/pkmode 2"));
    assert_eq!(read_update_mode(&mut dave, dave_listed.id), 2);
    assert_eq!(read_update_mode(&mut alpha, dave_listed.id), 2);
    dave.quiet("the switch ends");
    alpha.quiet("the switch ends");

    // When: Dave hits Alpha at one hit point. Then: the swing stuns, and the death
    // runs three seconds on.
    dave.send_record(&client_attack(alpha_listed.id));
    let deadline = std::time::Instant::now() + Duration::from_secs(20);
    // The killer's own update (the mark) lands before the victim's stun.
    let mut stunned = false;
    while !stunned {
        let record = read_fight_before(&mut dave, deadline, "the stun");
        if record == stun_of(alpha_listed.id) {
            stunned = true;
        }
    }
    // The death's records: either the penalty's update carries the killer's new
    // alignment in tenths (-20000 / 10), or the spare line comes (one draw in three
    // spares a blameless killer, `G/char_battle.cpp:1414-1422`). Both prove the path
    // ran; the world tests pin each arm on its own seed.
    let mut cost = false;
    let mut spared = false;
    let mut dead = false;
    let spare_line = an_info_line(b"[LS;910]");
    while !(dead && (cost || spared)) {
        let record = read_fight_before(&mut dave, deadline, "the death's records");
        if record[0] == GC_CHARACTER_UPDATE
            && record.len() == CHARACTER_UPDATE_LEN
            && u32::from_le_bytes([record[1], record[2], record[3], record[4]]) == dave_listed.id
            && i16::from_le_bytes([record[32], record[33]]) == -2000
        {
            cost = true;
        }
        if record == spare_line {
            spared = true;
        }
        if record == dead_of(alpha_listed.id) {
            dead = true;
        }
    }
    assert!(cost || spared, "the penalty ran, paid or spared");
}

/// `G/pvp.cpp:470-490`: revenge lets the wronged strike the wrongdoer. Alpha goes
/// revenge while Dave stands negative, and the swing lands unmarked; then Dave is
/// blameless no more the other way — Alpha at 0 refuses the like-aligned Dave at 0.
#[test]
fn a_revenge_hit_on_a_negative_player_lands_and_a_like_aligned_one_is_refused() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    create_account(&server, "dave");
    add_characters(&database);
    sql(
        &database,
        "UPDATE account SET empire = 1 WHERE login = 'dave'",
    );
    sql(
        &database,
        "INSERT INTO player (account_id, slot, name, job, level, x, y) SELECT id, 0, 'Dave', 1, \
         154, 470100, 950100 FROM account WHERE login = 'dave'",
    );
    sql(
        &database,
        "UPDATE player SET stamina = 12345 WHERE name = 'Dave'",
    );
    sql(
        &database,
        "UPDATE player SET alignment = -100 WHERE name = 'Dave'",
    );
    let (mut alpha, alpha_listed, _alpha_entered) = enter_world_seeing(&server, b"alice", 0);
    let (mut dave, dave_listed, _dave_entered) = enter_world_seeing(&server, b"dave", 0);
    alpha.sees_enter(dave_listed.id, false, None);

    // Alpha goes revenge: her own update carries the mode, and Dave sees it too.
    alpha.send_record(&client_chat(CHAT_TALKING, b"/pkmode 1"));
    assert_eq!(read_update_mode(&mut alpha, alpha_listed.id), 1);
    assert_eq!(read_update_mode(&mut dave, alpha_listed.id), 1);
    alpha.quiet("the switch ends");
    dave.quiet("the switch ends");

    // When: Alpha hits the negative Dave. Then: the damage and the claim to Alpha, the
    // damage, the hit points and the claim to Dave — and no update on either side
    // raises the killer bit.
    alpha.send_record(&client_attack(dave_listed.id));
    for (side, client) in [("Alpha", &mut alpha), ("Dave", &mut dave)] {
        let mut damage = false;
        while !damage {
            let record = client.read_game();
            if record[0] == GC_CHARACTER_UPDATE {
                assert_eq!(record[19] & (1 << 3), 0, "{side}: no killer bit raises");
                continue;
            }
            assert_eq!(
                record,
                damage_info(dave_listed.id, DAMAGE_NORMAL, PVP_DAMAGE),
                "{side}: the damage"
            );
            damage = true;
        }
    }
    assert_eq!(
        alpha.read_hit(),
        ownership_of(alpha_listed.id, dave_listed.id),
        "Alpha: the claim"
    );
    assert_eq!(
        dave.read_hit(),
        point_change(
            dave_listed.id,
            u8::try_from(common::point_slot::POINT_HP).expect("a point byte"),
            0,
            PVP_HP_AFTER
        ),
        "Dave: the hit points"
    );
    assert_eq!(
        dave.read_hit(),
        ownership_of(alpha_listed.id, dave_listed.id),
        "Dave: the claim"
    );
}

/// `sys.char.pk`, `event.item.unique_expire_event`: a worn unique's event fires and
/// removes it (`G/item.cpp:1900-1983`). Alpha is given the cloak (70048) at cell 0 with
/// the saved socket 4 banked at 2 seconds; wearing it onto the first unique cell (187)
/// clears the bank and arms the event 2 s on, and the fire removes the worn cloak —
/// the wear cell clears, the shown alignment returns to 432, and the item row is gone.
#[test]
fn a_worn_cloaks_saved_seconds_fire_and_remove_it() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "UPDATE player SET alignment = 4321 WHERE name = 'Alpha'",
    );
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum, socket4) \
         SELECT 30, id, 1, 0, 1, 70048, 2 FROM player WHERE name = 'Alpha'",
    );
    let entered_at = std::time::Instant::now();
    let (keyed, character, quickslots, load_sets) =
        load_with_quickslots_in(&server, b"alice", 0, ENGLISH);
    assert_eq!(character.name, b"Alpha");
    assert_eq!(quickslots, Vec::<Vec<u8>>::new(), "no quickslot is stored");
    assert_eq!(load_sets.len(), 1, "the load sets the cloak");
    let mut alpha = keyed;
    let entered = enter_game_view(&mut alpha);
    let vid = u32::from_le_bytes(entered.add[1..5].try_into().expect("four bytes"));
    std::thread::sleep(Duration::from_millis(1600).saturating_sub(entered_at.elapsed()));
    drain_revive_end(&mut alpha, entered_at);

    // When: the cloak is moved onto the first unique cell.
    alpha.send_record(&client_item_move(0, 187, 0));
    // The wear's burst, the socket clear's `GC_ITEM_UPDATE` (25) among it: the wear
    // cell sets with the hide behind it. Read raw, because the move reader knows no
    // update record.
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    let mut set = false;
    let mut looks = Vec::new();
    let mut cleared_bank = false;
    while std::time::Instant::now() < deadline && (!set || looks.len() < 2 || !cleared_bank) {
        let Some(record) = alpha.read_game_until(deadline) else {
            break;
        };
        if record.first() == Some(&ITEM_SET) {
            let (window, cell, vnum, _count) = set_fields(&record);
            if window == common::item_slots::EWindows::Inventory as u8
                && cell == 187
                && vnum == 70_048
            {
                set = true;
            }
        }
        if record.first() == Some(&GC_CHARACTER_UPDATE) {
            let update = protocol::gc_actors::GcCharacterUpdate::decode(&record)
                .expect("a character update");
            if update.dw_vid == vid {
                looks.push(update.s_alignment);
            }
        }
        if record.first() == Some(&ITEM_UPDATE) {
            cleared_bank = true;
        }
    }
    assert!(set, "the wear cell sets");
    assert_eq!(looks, [432, 0], "the wear step's look, then the hide");
    assert!(cleared_bank, "the start clears the socket-4 bank");
    // Then: 2 s on, the banked seconds fire and the worn cloak is removed — the
    // wear cell clears and the shown alignment returns to 432.
    let deadline = std::time::Instant::now() + Duration::from_secs(30);
    let mut cleared = false;
    let mut reshown = false;
    while std::time::Instant::now() < deadline && !(cleared && reshown) {
        let Some(record) = alpha.read_game_until(deadline) else {
            break;
        };
        if record.first() == Some(&ITEM_SET) {
            let (window, cell, vnum, _count) = set_fields(&record);
            if window == common::item_slots::EWindows::Inventory as u8 && cell == 187 && vnum == 0 {
                cleared = true;
            }
        }
        if record.first() == Some(&GC_CHARACTER_UPDATE) {
            let update = protocol::gc_actors::GcCharacterUpdate::decode(&record)
                .expect("a character update");
            if update.dw_vid == vid && update.s_alignment == 432 {
                reshown = true;
            }
        }
    }
    assert!(cleared, "the fire clears the wear cell");
    assert!(reshown, "the expiry shows the real alignment again");
    check(&database, "(SELECT count(*) = 0 FROM item WHERE id = 30)");
}

/// `sys.char.pk`: the hide-alignment cloak (70048) is worn and taken off through
/// `CG_ITEM_MOVE`, and the shown alignment follows it while the stored one stays.
///
/// Alpha is stored with alignment 4321 and given the cloak at cell 0. Wearing it onto
/// the first unique cell (187) sends the equip records and then the look with `sAlignment` 0
/// (`ShowAlignment(false)`, `G/char_item.cpp:8556-8557`); the client's own additional
/// info at entry showed 432. Taking it off again sends the look with 432
/// (`ShowAlignment(true)`, `:8287-8288`), and the stored row still says 4321.
#[test]
fn a_worn_cloak_hides_the_shown_alignment_and_its_takeoff_restores_it() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "UPDATE player SET alignment = 4321 WHERE name = 'Alpha'",
    );
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 30, id, \
         1, 0, 1, 70048 FROM player WHERE name = 'Alpha'",
    );
    let protos = owners_protos();
    assert_eq!(
        protos
            .get(70_048)
            .expect("the owner's data has it")
            .item_type,
        gamedata::item_kind::ITEM_UNIQUE,
        "the cloak is a unique of the owner's data"
    );
    let entered_at = std::time::Instant::now();
    let (keyed, character, quickslots, load_sets) =
        load_with_quickslots_in(&server, b"alice", 0, ENGLISH);
    assert_eq!(character.name, b"Alpha");
    assert_eq!(quickslots, Vec::<Vec<u8>>::new(), "no quickslot is stored");
    assert_eq!(load_sets.len(), 1, "the load sets the cloak");
    let mut alpha = keyed;
    let entered = enter_game_view(&mut alpha);
    let add = entered.add;
    let vid = u32::from_le_bytes(add[1..5].try_into().expect("four bytes"));
    // Past the equip's 1.5 s window (the entry itself took most of it) and the
    // revive's five seconds, so the affect end's pair lands here and not in a
    // move's window.
    std::thread::sleep(Duration::from_millis(1600).saturating_sub(entered_at.elapsed()));
    drain_revive_end(&mut alpha, entered_at);

    // When: the cloak is moved onto the first unique cell.
    alpha.send_record(&client_item_move(0, 187, 0));
    // Then: the cell clears, the wear cell sets, the battle points recompute, and the
    // wear step's look carries 432 with the hide's look carrying 0 behind it. No
    // update record lands: the banked socket 4 is 0, and the start clears nothing.
    let (seen, updates) = read_a_move_with_updates(&mut alpha, vid);
    let seen = seen
        .into_iter()
        .filter(|seen| !matches!(seen, Seen::Look(..)))
        .collect::<Vec<_>>();
    assert_eq!(
        seen,
        [
            Seen::Set(0, 0),
            Seen::Set(187, 70_048),
            Seen::Point(18, 344),
            Seen::Point(20, 168),
            Seen::Point(16, 168),
            Seen::Point(20, 172),
            Seen::Point(22, 348),
            Seen::Point(23, 180),
        ]
    );
    let shown = updates
        .iter()
        .map(|update| update.s_alignment)
        .collect::<Vec<_>>();
    assert_eq!(shown, [432, 0], "the wear step's look, then the hide");

    // When: it is taken off again.
    alpha.send_record(&client_item_move(187, 0, 0));
    // Then: the wear cell clears, the points recompute, the cell sets, the unique
    // stop banks the seconds left into socket 4 with an update record, the step's
    // own look carries the still-hidden 0, and the show's look behind it carries 432.
    let (seen, updates) = read_a_move_with_updates(&mut alpha, vid);
    let seen = seen
        .into_iter()
        .filter(|seen| !matches!(seen, Seen::Look(..)))
        .collect::<Vec<_>>();
    assert_eq!(
        seen,
        [
            Seen::Set(187, 0),
            Seen::Point(18, 344),
            Seen::Point(20, 168),
            Seen::Point(16, 168),
            Seen::Point(20, 172),
            Seen::Point(22, 348),
            Seen::Point(23, 180),
            Seen::Set(0, 70_048),
            Seen::Count(0, 1),
        ]
    );
    let shown = updates
        .iter()
        .map(|update| update.s_alignment)
        .collect::<Vec<_>>();
    assert_eq!(shown, [0, 432], "the take-off step's look, then the show");
    check(
        &database,
        "(SELECT alignment = 4321 FROM player WHERE name = 'Alpha')",
    );
    // The stop banked the ~60 seconds left into socket 4 and saved the row.
    check(&database, "(SELECT socket4 > 0 FROM item WHERE id = 30)");
}

/// [`read_a_move`], with the decoded `GC_CHARACTER_UPDATE` records of `vid` beside it,
/// in order.
fn read_a_move_with_updates(
    keyed: &mut Keyed,
    vid: u32,
) -> (Vec<Seen>, Vec<protocol::gc_actors::GcCharacterUpdate>) {
    use protocol::gc_actors::GcCharacterUpdate;
    let language = keyed.language;
    let (records, quiet) = keyed.drain_game(Duration::from_millis(700), |header| match header {
        GC_CHARACTER_UPDATE => CHARACTER_UPDATE_LEN,
        GC_SPECIAL_EFFECT => SPECIAL_EFFECT_LEN,
        other => game_len(other),
    });
    assert_eq!(quiet, Quiet::Open);
    let mut updates = Vec::new();
    let seen = records
        .iter()
        .filter(|record| !is_revive_end(record))
        .map(|record| match record.first().copied().unwrap_or_default() {
            ITEM_SET => {
                let (window, cell, vnum, _count) = set_fields(record);
                assert_eq!(window, common::item_slots::EWindows::Inventory as u8);
                Seen::Set(cell, vnum)
            }
            ITEM_UPDATE => {
                let (window, cell, count) = update_fields(record);
                assert_eq!(window, common::item_slots::EWindows::Inventory as u8);
                Seen::Count(cell, count)
            }
            GC_POINT_CHANGE => {
                assert_eq!(&record[4..8], &vid.to_le_bytes(), "the mover's VID");
                let value = i64::from_le_bytes(record[17..25].try_into().expect("eight bytes"));
                Seen::Point(record[8], value)
            }
            GC_SPECIAL_EFFECT => {
                assert_eq!(&record[2..6], &vid.to_le_bytes(), "the mover's VID");
                Seen::Effect(record[1])
            }
            GC_CHARACTER_UPDATE => {
                let update = GcCharacterUpdate::decode(record).expect("a character update decodes");
                assert_eq!(update.dw_vid, vid, "the mover's VID");
                assert_eq!(update.b_language, language, "the mover's language");
                updates.push(update);
                Seen::Look(update.aw_part, update.b_moving_speed, update.b_attack_speed)
            }
            other => panic!("a record nobody accounted for in a move: header {other}"),
        })
        .collect();
    (seen, updates)
}

/// `cg.game.item_use`: a main-switch `USE_AFFECT` item (39010) lands value(0) on
/// `aApplyInfo` of value(1), and a second use while it is held is refused. Alpha
/// uses the item at cell 0: one of two goes (the update record), the
/// `GC_AFFECT_ADD` of kind 510 lands on point 17 with value 10 and 1800 s, and
/// the row reads count 1. The second use hears `[LS;99]` and the row stays at 1.
#[test]
fn a_timed_use_lands_510_and_a_second_is_refused_while_held() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 30, id, 1, 0, 2, \
         39010 FROM player WHERE name = 'Alpha'",
    );
    let protos = owners_protos();
    let proto = protos.get(39_010).expect("the owner's data has it");
    assert_eq!(proto.item_type, gamedata::item_kind::ITEM_USE);
    assert_eq!(proto.sub_type, 8, "the owner's item is USE_AFFECT");
    assert_eq!(proto.values[0], 510, "the item is the mall affect");
    let (mut alpha, _listed) = enter_world(&server, b"alice", 0);
    // When: Alpha uses. Then: the update, and the 510 add on 17 with 10 for 1800.
    alpha.send_record(&client_item_use(0));
    let mut spent = false;
    let mut timed = false;
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    while std::time::Instant::now() < deadline && !(spent && timed) {
        let Some(record) = alpha.read_game_until(deadline) else {
            break;
        };
        if record.first() == Some(&ITEM_UPDATE) {
            let (window, cell, count) = update_fields(&record);
            if window == common::item_slots::EWindows::Inventory as u8 && cell == 0 {
                assert_eq!(count, 1, "the use spends one of two");
                spent = true;
            }
        }
        if record.first() == Some(&GC_AFFECT_ADD)
            && record.len() == AFFECT_ADD_LEN
            && record[1..5] == 510u32.to_le_bytes()
        {
            assert_eq!(record[5], 17, "value(1) 7 is attack speed");
            let value = i32::from_le_bytes(record[6..10].try_into().expect("four bytes"));
            let dur = i32::from_le_bytes(record[14..18].try_into().expect("four bytes"));
            assert_eq!(value, 10, "value(2) is the bonus");
            assert_eq!(dur, 1800, "value(3) is the duration");
            timed = true;
        }
    }
    assert!(spent, "the use lands");
    assert!(timed, "the 510 affect lands");
    check(&database, "(SELECT count = 1 FROM item WHERE id = 30)");
    // When: the second use, while (510, 17) is held. Then: `[LS;99]`, the row kept.
    alpha.send_record(&client_item_use(0));
    assert_eq!(
        alpha.read_game(),
        an_info_line(b"[LS;99]"),
        "the second use hears the renewal line"
    );
    check(&database, "(SELECT count = 1 FROM item WHERE id = 30)");
}

/// `cg.game.item_use`: the 72355 premium item lands the 507 row, holds the
/// account expiry, and a second maxed use is refused. Alpha uses the item at
/// cell 0: one of two goes (the update record), the `GC_AFFECT_ADD` of kind 507
/// lands on point 0 with 604800 s, the increased line tells, and the account
/// row reads an expiry a week out. The first use's max line queued behind the
/// add, then the second use hears the recently-reached line and the row stays at 1.
#[test]
fn a_shop_premium_use_lands_507_stores_the_expiry_and_refuses_the_second() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 30, id, 1, 0, 2, \
         72355 FROM player WHERE name = 'Alpha'",
    );
    let protos = owners_protos();
    let proto = protos.get(72_355).expect("the owner's data has it");
    assert_eq!(proto.item_type, gamedata::item_kind::ITEM_USE);
    assert_eq!(proto.sub_type, 8, "the owner's item is USE_AFFECT");
    assert_eq!(proto.values[0], 507, "the item is the shop premium");
    let (mut alpha, _listed) = enter_world(&server, b"alice", 0);
    // When: Alpha uses. Then: the update, the 507 add on 0 for 604800, the line.
    alpha.send_record(&client_item_use(0));
    let mut spent = false;
    let mut premium = false;
    let mut increased = false;
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    while std::time::Instant::now() < deadline && !(spent && premium && increased) {
        let Some(record) = alpha.read_game_until(deadline) else {
            break;
        };
        if record.first() == Some(&ITEM_UPDATE) {
            let (window, cell, count) = update_fields(&record);
            if window == common::item_slots::EWindows::Inventory as u8 && cell == 0 {
                assert_eq!(count, 1, "the use spends one of two");
                spent = true;
            }
        }
        if record.first() == Some(&GC_AFFECT_ADD)
            && record.len() == AFFECT_ADD_LEN
            && record[1..5] == 507u32.to_le_bytes()
        {
            assert_eq!(record[5], 0, "the row lands on POINT_NONE");
            let dur = i32::from_le_bytes(record[14..18].try_into().expect("four bytes"));
            assert_eq!(dur, 604_800, "value(3) is the duration");
            premium = true;
        }
        if record == an_info_line(b"You have increased Premium Personal Shop duration.") {
            increased = true;
        }
    }
    assert!(spent, "the use lands");
    assert!(premium, "the 507 affect lands");
    assert!(increased, "the increased line tells");
    check(&database, "(SELECT count = 1 FROM item WHERE id = 30)");
    check(
        &database,
        "(SELECT private_shop_premium_expire BETWEEN \
         EXTRACT(EPOCH FROM now())::bigint + 604799 AND \
         EXTRACT(EPOCH FROM now())::bigint + 604805 FROM account WHERE login = 'alice')",
    );
    // When: the second use, maxed. Then: the reached-max line first (it queued
    // behind the 507 add), then the recently-reached line; the row stays at 1.
    alpha.send_record(&client_item_use(0));
    assert_eq!(
        alpha.read_game(),
        an_info_line(b"You have reached maximum premium time for your personal shop. "),
        "the first use's max line queued behind the add"
    );
    assert_eq!(
        alpha.read_game(),
        an_info_line(
            b"You have just recently reached maximum premium time for your personal shop. "
        ),
        "the second use hears the recent line"
    );
    check(&database, "(SELECT count = 1 FROM item WHERE id = 30)");
}

/// `cg.game.item_use`: a town portal (22000) marks its user's spot on its own sockets
/// and recalls to the empire's town. Alpha uses the lone portal at cell 0: the two
/// socket updates stamp (470100, 950000), the row keeps them, the life pays 30%, and
/// `GC_WARP` names map 1's town spawn (469300, 964200) on Channel 1.
#[test]
fn a_town_portal_marks_the_spot_and_recalls_to_town() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 30, id, 1, 0, 1, \
         22000 FROM player WHERE name = 'Alpha'",
    );
    let protos = owners_protos();
    let proto = protos.get(22_000).expect("the owner's data has it");
    assert_eq!(proto.item_type, gamedata::item_kind::ITEM_USE);
    assert_eq!(proto.sub_type, 1, "the owner's item is USE_TALISMAN");
    assert_eq!(proto.values[0], 1, "the item is the town portal");
    let (mut alpha, _listed) = enter_world(&server, b"alice", 0);
    // When: Alpha uses. Then: the two updates, and the warp to town.
    alpha.send_record(&client_item_use(0));
    let mut updates = 0;
    let mut warped = false;
    let port = server.channel(1).port();
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    while std::time::Instant::now() < deadline && !(updates >= 2 && warped) {
        let Some(record) = alpha.read_game_until(deadline) else {
            break;
        };
        if record.first() == Some(&ITEM_UPDATE) {
            let (window, cell, _count) = update_fields(&record);
            if window == common::item_slots::EWindows::Inventory as u8 && cell == 0 {
                updates += 1;
            }
        }
        if record == a_warp_record((469_300, 964_200), port) {
            warped = true;
        }
    }
    assert_eq!(updates, 2, "the mark stamps both sockets");
    assert!(warped, "the recall warps to town");
    check(
        &database,
        "(SELECT socket0 = 470100 AND socket1 = 950000 FROM item WHERE id = 30)",
    );
}

/// `cg.game.item_use`: the 80003 gold bar (`LINGOURI_SURSA`,
/// `G/char_item.cpp:3328-3370`) pays 500 000 yang. Alpha's two bars sit at cell 0; the
/// use pays the gold with the `ChangeGold` record, one bar of two goes, and the store
/// keeps the gold and the bar.
#[test]
fn a_gold_bar_pays_its_yang_and_uses_one_up() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 30, id, 1, 0, 2, \
         80003 FROM player WHERE name = 'Alpha'",
    );
    let protos = owners_protos();
    let proto = protos.get(80_003).expect("the owner's data has it");
    assert_eq!(proto.item_type, gamedata::item_kind::ITEM_USE);
    assert_eq!(proto.sub_type, 10, "the owner's bar is USE_SPECIAL");
    sql(
        &database,
        "UPDATE player SET gold = 5000 WHERE name = 'Alpha'",
    );
    let (mut alpha, listed) = enter_world(&server, b"alice", 0);
    let (before, vid) = (5_000, listed.id);
    // When: Alpha uses. Then: the gold record, and the bar's update.
    alpha.send_record(&client_item_use(0));
    assert_eq!(
        alpha.read_game(),
        gold_change(vid, 500_000, before + 500_000),
        "the gold pays with the ChangeGold record"
    );
    let mut updated = false;
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    while std::time::Instant::now() < deadline && !updated {
        let Some(record) = alpha.read_game_until(deadline) else {
            break;
        };
        if record.first() == Some(&ITEM_UPDATE) {
            let (window, cell, count) = update_fields(&record);
            if window == common::item_slots::EWindows::Inventory as u8 && cell == 0 {
                assert_eq!(count, 1, "the use spends one of two");
                updated = true;
            }
        }
    }
    assert!(updated, "the bar's update lands");
    check(&database, "(SELECT count = 1 FROM item WHERE id = 30)");
    check(
        &database,
        &format!(
            "(SELECT gold = {} FROM player WHERE name = 'Alpha')",
            before + 500_000
        ),
    );
}

/// `cg.game.item_use`: the 70038 cape of courage (`case USE_SPECIAL`,
