/// `cg.game.item_use`: the 50216 Nog pocket (`case USE_SPECIAL`,
/// `G/char_item.cpp:3787-3811`) lands three 302 rows — move speed with the potion
/// flag, the mall attack bonus and the mall experience bonus, value(1..=3) each
/// for value(0) s. Alpha uses one of two: the three adds ride, the count falls to
/// 1, and a second use is refused with `[LS;99]`, the row kept at 1.
#[test]
fn a_nog_pocket_lands_302_and_a_second_is_refused_while_held() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    create_account(&server, "alice");
    add_characters(&database);
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 30, id, 1, 0, 2, \
         50216 FROM player WHERE name = 'Alpha'",
    );
    let protos = owners_protos();
    let proto = protos.get(50_216).expect("the owner's data has it");
    assert_eq!(proto.item_type, gamedata::item_kind::ITEM_USE);
    assert_eq!(proto.sub_type, 10, "the owner's pocket is USE_SPECIAL");
    assert_eq!(proto.values, [1800, 10, 5, 10, 0, 0], "the pocket's rows");
    // The pocket's `REAL_TIME` limit owns socket 0 as its expiry, so the row
    // carries a live one; the load keeps the sockets as stored.
    sql(
        &database,
        "UPDATE item SET socket0 = 2147483647 WHERE id = 30",
    );
    let (mut alpha, _listed) = enter_world(&server, b"alice", 0);
    // When: Alpha uses. Then: the update, and three 302 adds.
    alpha.send_record(&client_item_use(0));
    let mut spent = false;
    let mut adds: Vec<(u8, i32)> = Vec::new();
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    while std::time::Instant::now() < deadline && !(spent && adds.len() >= 3) {
        let Some(record) = alpha.read_game_until(deadline) else {
            break;
        };
        if record.first() == Some(&ITEM_UPDATE) {
            let (window, cell, count) = update_fields(&record);
            if window == common::item_slots::EWindows::Inventory as u8 && cell == 0 {
                assert_eq!(count, 1, "the use spends one of two");
                spent = true;
            }
        }
        if record.first() == Some(&GC_AFFECT_ADD)
            && record.len() == AFFECT_ADD_LEN
            && record[1..5] == 302u32.to_le_bytes()
        {
            let value = i32::from_le_bytes(record[6..10].try_into().expect("four bytes"));
            let dur = i32::from_le_bytes(record[14..18].try_into().expect("four bytes"));
            assert_eq!(dur, 1800, "value(0) is the duration");
            adds.push((record[5], value));
        }
    }
    assert!(spent, "the use lands");
    let mov = u8::try_from(common::point_slot::POINT_MOV_SPEED).expect("a point byte");
    let att = u8::try_from(common::point_slot::POINT_MALL_ATTBONUS).expect("a point byte");
    let exp = u8::try_from(common::point_slot::POINT_MALL_EXPBONUS).expect("a point byte");
    assert_eq!(
        adds,
        [(mov, 10), (att, 5), (exp, 10)],
        "the three rows land"
    );
    check(&database, "(SELECT count = 1 FROM item WHERE id = 30)");
    // When: the second use, while 302 is held. Then: `[LS;99]`, the row kept.
    alpha.send_record(&client_item_use(0));
    assert_eq!(
        alpha.read_game(),
        an_info_line(b"[LS;99]"),
        "the held row refuses"
    );
    check(&database, "(SELECT count = 1 FROM item WHERE id = 30)");
}

/// `cg.game.item_use`: `UseItemEx`'s head (`G/char_item.cpp:2769-2775`) refuses a
/// duellist's limited potion while `no_potions_on_pvp` stands. Alice (a
/// `HIGH_WIZARD`) stands the flag herself, then fights Yankee; she uses the
/// limited 50817 and hears `[LS;1205]` with the row kept. A GM stands the flag
/// because `questlib_extra.lua`'s load set is not ported (only the boot's two
/// seeds stand). Yankee enters first while Alpha is offline, so his own team
/// list names her with the offline byte; her enter then fans him `TEAM_LOGIN`.
#[test]
fn a_duellist_with_the_flag_up_hears_1205_for_a_limited_potion() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    for login in ["alice", "bob"] {
        create_account(&server, login);
    }
    add_characters(&database);
    sql(
        &database,
        "UPDATE account SET empire = 2 WHERE login = 'bob'",
    );
    sql(
        &database,
        "INSERT INTO player (account_id, slot, name, job, x, y) SELECT id, 0, 'Yankee', 1, \
         470000, 950000 FROM account WHERE login = 'bob'",
    );
    sql(
        &database,
        "INSERT INTO item (id, owner_id, window_type, pos, count, vnum) SELECT 30, id, 1, 0, 2, \
         50817 FROM player WHERE name = 'Alpha'",
    );
    // Alice carries the grant from the select, where `/eventflag` reads it.
    sql(
        &database,
        "INSERT INTO gm_grant (account_id, name, authority) SELECT id, 'Alpha', 'HIGH_WIZARD' \
         FROM account WHERE login = 'alice'",
    );
    let protos = owners_protos();
    let proto = protos.get(50_817).expect("the owner's data has it");
    assert_eq!(proto.item_type, gamedata::item_kind::ITEM_USE);
    // Yankee enters while Alpha is offline: his own team list names Alpha with
    // the offline byte, inside his login event, ahead of the board's line. The
    // enter helper only reads the online shape, so the enter is manual here.
    let (mut yankee, _, yankee_list) = select_screen_on(&server, 1, b"bob", ENGLISH);
    let (_yankee_character, _yankee_quickslots, _yankee_items) =
        load_selected(&mut yankee, &yankee_list, 0);
    let _yankee_entered = enter_game_shown(&mut yankee);
    assert_eq!(
        yankee.read_game(),
        messenger_team_list_many(&[(b"Alpha".as_slice(), false)]),
        "Yankee hears the offline team"
    );
    read_login_event(&mut yankee);
    yankee.still("nothing follows");
    let (mut alice, _empire, list) = select_screen_on(&server, 1, b"alice", ENGLISH);
    let (_character, _quickslots, _items) = load_selected(&mut alice, &list, 0);
    let entered = enter_game_shown(&mut alice);
    // Alice hears no team list of her own: the team is every GM name other
    // than her own, and her grant names her.
    read_login_event(&mut alice);
    // Yankee's team set holds Alpha, so her enter fans `TEAM_LOGIN` to him,
    // ahead of her view records (`LoadTeamList`, `G/messenger_manager.cpp:48-52`).
    assert_eq!(
        yankee.read_game(),
        messenger_login(1, b"Alpha"),
        "Yankee hears Alpha's team login"
    );
    let yankee_sees_alice = yankee.read_game();
    assert_eq!(
        yankee_sees_alice[0], GC_CHARACTER_ADD,
        "Alice's view reaches Yankee"
    );
    let yankee_sees_info = yankee.read_game();
    assert_eq!(
        yankee_sees_info[0], GC_CHAR_ADDITIONAL_INFO,
        "Alice's summary reaches Yankee"
    );
    let update = yankee.read_game();
    assert_eq!(
        update[0], GC_CHARACTER_UPDATE,
        "Alice's login hides reach Yankee's view"
    );
    yankee.still("nothing follows");
    let alice_vid = u32::from_le_bytes(entered.add[1..5].try_into().expect("a VID"));
    let yankee_vid = entered
        .shown
        .records
        .iter()
        .find(|record| record[0] == GC_CHAR_ADDITIONAL_INFO && record[5..11] == b"Yankee"[..])
        .map(|record| u32::from_le_bytes(record[1..5].try_into().expect("a VID")))
        .expect("Yankee stands in view");
    // When: Alice stands the flag, the duel begins, and Alice uses. Then:
    // `[LS;1205]`, the row kept.
    alice.send_record(&client_chat(
        CHAT_TALKING,
        b"/eventflag no_potions_on_pvp 1",
    ));
    assert_eq!(
        alice.read_game(),
        an_info_line(b"RequestSetEventFlag no_potions_on_pvp 1"),
        "the flag stands"
    );
    challenge_and_accept(&mut alice, &mut yankee, alice_vid, yankee_vid);
    alice.send_record(&client_item_use(0));
    let mut refused = false;
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    while std::time::Instant::now() < deadline && !refused {
        let Some(record) = alice.read_game_until(deadline) else {
            break;
        };
        if record == an_info_line(b"[LS;1205]") {
            refused = true;
        }
    }
    assert!(refused, "the duel gate refuses");
    check(&database, "(SELECT count = 2 FROM item WHERE id = 30)");
    drop(alice);
    drop(yankee);
}

/// The cast for the top-player fall: Alpha the `LOW_WIZARD` and Yankee, both on
/// Channel 1's map 1, on a server at max level 120, as the owner's config sets
/// it (the test default stops at 99, below the top). Yankee enters first while
/// Alpha is offline, so his own team list names her with the offline byte; her
/// enter then fans him `TEAM_LOGIN` ahead of her view.
fn top_fall_cast() -> Option<(ScratchDatabase, Server, Keyed, Keyed)> {
    let database = ScratchDatabase::create()?;
    create_account_before_boot(&database, "alice");
    create_account_before_boot(&database, "bob");
    add_characters(&database);
    sql(&database, "UPDATE account SET empire = 1");
    sql(
        &database,
        "INSERT INTO player (account_id, slot, name, job, x, y) SELECT id, 0, 'Yankee', 1, \
         470100, 950100 FROM account WHERE login = 'bob'",
    );
    sql(
        &database,
        "INSERT INTO gm_grant (account_id, name, authority) SELECT id, 'Alpha', 'LOW_WIZARD' \
         FROM account WHERE login = 'alice'",
    );
    let server = Server::start_configured(
        binary(),
        database.url(),
        &default_channels(),
        "max_level = 120",
    );
    // The enter helper only reads the online team shape, so Yankee's enter is
    // manual: his list names Alpha with the offline byte, inside his login
    // event, ahead of the board's line.
    let (mut yankee, _, yankee_list) = select_screen_on(&server, 1, b"bob", ENGLISH);
    let (_yankee_character, _yankee_quickslots, _yankee_items) =
        load_selected(&mut yankee, &yankee_list, 0);
    let _yankee_entered = enter_game_shown(&mut yankee);
    assert_eq!(
        yankee.read_game(),
        messenger_team_list_many(&[(b"Alpha".as_slice(), false)]),
        "Yankee hears the offline team"
    );
    read_login_event(&mut yankee);
    yankee.still("nothing follows");
    let (mut alice, _character, _quickslots, _items) =
        load_with_quickslots_on(&server, 1, b"alice", 0, ENGLISH);
    let _entered = enter_game_shown(&mut alice);
    assert_eq!(
        yankee.read_game(),
        messenger_login(1, b"Alpha"),
        "Yankee hears Alpha's team login"
    );
    let yankee_sees_alice = yankee.read_game();
    assert_eq!(
        yankee_sees_alice[0], GC_CHARACTER_ADD,
        "Alice's view reaches Yankee"
    );
    let yankee_sees_info = yankee.read_game();
    assert_eq!(
        yankee_sees_info[0], GC_CHAR_ADDITIONAL_INFO,
        "Alice's summary reaches Yankee"
    );
    let update = yankee.read_game();
    assert_eq!(
        update[0], GC_CHARACTER_UPDATE,
        "Alice's login hides reach Yankee's view"
    );
    // Alice's own grant names her, so she hears no team list of her own: the
    // list names every GM but the entrant.
    read_login_event(&mut alice);
    alice.still("nothing follows");
    yankee.still("nothing follows");
    Some((database, server, alice, yankee))
}

/// `/level` to and off 120 (`SetTopPlayerEffect`, `G/char.cpp:11255-11284`, and the
/// `ComputeAffect` strip, `G/char_affect.cpp:811-826`): the first arrival stands its
/// `player_top` row and takes the 321 row with flag 44; a move to 119 takes the
/// row off with its remove packet and fells the store row.
#[test]
fn a_level_to_120_grants_the_top_row_and_a_move_off_fells_it() {
    let Some((database, _server, mut alice, yankee)) = top_fall_cast() else {
        return;
    };
    // When: `/level 120`. Then: the reset rides, the 321 row lands with its
    // update, and the store row stands.
    alice.send_record(&client_chat(CHAT_TALKING, b"/level 120"));
    // The reset rides with the quest `levelup` lines; read until the grant.
    let mut adds: Vec<Vec<u8>> = Vec::new();
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    while std::time::Instant::now() < deadline && adds.is_empty() {
        let Some(record) = alice.read_game_until(deadline) else {
            break;
        };
        if record.first() == Some(&GC_AFFECT_ADD) {
            adds.push(record);
        }
    }
    assert_eq!(adds.len(), 1, "the grant lands one row");
    assert_eq!(
        u32::from_le_bytes(adds[0][1..5].try_into().expect("a kind")),
        321,
        "the first arrival takes the first row"
    );
    assert_eq!(
        u32::from_le_bytes(adds[0][10..14].try_into().expect("a flag")),
        44,
        "the row carries flag 44"
    );
    check(&database, "(SELECT COUNT(*) FROM player_top) = 1");
    // When: `/level 119`. Then: the 321 row's remove rides, and the store row
    // falls.
    alice.send_record(&client_chat(CHAT_TALKING, b"/level 119"));
    let mut removes: Vec<Vec<u8>> = Vec::new();
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    while std::time::Instant::now() < deadline && removes.is_empty() {
        let Some(record) = alice.read_game_raw_until(deadline) else {
            break;
        };
        if record.first() == Some(&GC_AFFECT_REMOVE) {
            removes.push(record);
        }
    }
    assert_eq!(removes.len(), 1, "the strip takes one row");
    assert_eq!(
        u32::from_le_bytes(removes[0][1..5].try_into().expect("a kind")),
        321,
        "the fallen row is the granted one"
    );
    check(&database, "(SELECT COUNT(*) FROM player_top) = 0");
    drop(alice);
    drop(yankee);
}
/// `sys.char.chat`'s `SpamBlockCheck` (`G/input_main.cpp:192-234`, `:836-839`, `:540-552`).
/// The server boots with one seeded spam word (`*gold*`, 100) and the compiled-in bar
/// (100) and duration (900 s). Yankee is level 1, so the check runs: its first spammy
/// talking line is consumed and answers `[LS;1030;15;0]`; a second line while blocked
/// answers the countdown again and the map hears nothing; the whisper arm is gated the
/// same way. Alpha is level 154, past the bar's level, so the same line from it reaches
/// the map and proves the gate is the level, not the word.
#[test]
fn a_spammy_line_blocks_its_ip_and_a_high_level_speaks_through() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let owner = std::fs::read(
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../legacy/sql/gamedata/common.sql"),
    )
    .expect("the owner's common.sql");
    let mut common = owner;
    common.extend_from_slice(
        b"INSERT INTO `spam_db` (`word`, `score`, `type`) VALUES ('*gold*',100,'SPAM');\n",
    );
    let (server, _tables) = Server::start_with_tables_configured(
        binary(),
        database.url(),
        &[("common.sql", &common)],
        "",
    );
    create_account(&server, "alice");
    create_account(&server, "bob");
    add_characters(&database);
    sql(&database, "UPDATE account SET empire = 1");
    sql(
        &database,
        "INSERT INTO player (account_id, slot, name, job, x, y) SELECT id, 0, 'Yankee', 1, \
         470000, 950000 FROM account WHERE login = 'bob'",
    );
    let (mut alice, _) = enter_world_on_with_team(&server, 1, b"alice", 0, ENGLISH, None);
    let (mut yankee, yankee_listed) =
        enter_world_on_with_team(&server, 1, b"bob", 0, ENGLISH, None);
    alice.sees_enter(yankee_listed.id, true, None);

    // A clean line first, so the test proves the map hears Yankee before the block.
    yankee.send_record(&client_chat(CHAT_TALKING, b"hello all"));
    let heard = yankee.read_game();
    assert_eq!(&heard[10..], b"Yankee : hello all");
    assert_eq!(alice.read_game(), heard, "the map hears a clean line");

    // The spammy line crosses the bar at once: consumed, and the ladder answers 900 s.
    yankee.send_record(&client_chat(CHAT_TALKING, b"cheap GOLD here"));
    assert_eq!(
        yankee.read_game(),
        an_info_line(b"[LS;1030;15;0]"),
        "fifteen minutes stay"
    );
    alice.quiet("the map hears no spammy line");

    // While blocked, even a clean line is consumed and answers the countdown again.
    yankee.send_record(&client_chat(CHAT_TALKING, b"hello again"));
    let again = yankee.read_game();
    assert_eq!(again[0], GC_CHAT, "the countdown is an info line");
    assert_eq!(&again[10..15], b"[LS;1", "the countdown is the ladder");
    alice.quiet("the map hears no line from a blocked IP");

    // The whisper arm runs the same check: blocked too, with the ladder, not `[LS;652]`.
    yankee.send_record(&client_whisper(b"Alpha", b"cheap gold too"));
    let refused = yankee.read_game();
    assert_eq!(
        refused[0], GC_CHAT,
        "a spam-blocked whisper hears the ladder"
    );
    assert_eq!(&refused[10..15], b"[LS;1", "not the silence key");
    alice.quiet("the whisper never reached its target");

    // Alpha is level 154, past `spam_block_max_level`: the same line goes through.
    alice.send_record(&client_chat(CHAT_TALKING, b"cheap GOLD here"));
    let through = alice.read_game();
    assert_eq!(&through[10..], b"Alpha : cheap GOLD here");
    assert_eq!(yankee.read_game(), through, "the map hears past the level");
}

/// Ledger 628: a morphed player moves at its morph's run clip. Alpha, a shaman
/// whose general run is 450 a second, morphs into the stray dog (101) and walks
/// the (100, 100) diagonal: the relayed duration is 322 ms, the dog's 438.38
/// over the same diagonal, not the shaman's 314.
#[test]
fn a_morphed_player_moves_at_its_morphs_run_clip() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let server = Server::start(binary(), database.url());
    for login in ["alice", "bob"] {
        create_account(&server, login);
    }
    add_characters(&database);
    sql(
        &database,
        "INSERT INTO player (account_id, slot, name, job, x, y) SELECT id, 0, 'Yankee', 1, \
         470000, 950000 FROM account WHERE login = 'bob'",
    );
    sql(
        &database,
        "INSERT INTO gm_grant (account_id, name, authority) SELECT id, 'Alpha', 'HIGH_WIZARD' \
         FROM account WHERE login = 'alice'",
    );
    stamina(&database, "Alpha", 12_345);
    stamina(&database, "Yankee", 12_345);
    let (mut alice, alpha) = enter_world_on_with_team(&server, 1, b"alice", 0, ENGLISH, None);
    let (mut yankee, yankee_listed) =
        enter_world_on_with_team(&server, 1, b"bob", 0, GERMAN, Some(b"Alpha"));
    alice.sees_enter(yankee_listed.id, false, None);

    // A step lands exactly, whatever the enter nudged; then the shaman's own
    // diagonal: 314 ms at 450 a second.
    let step = client_move(3, 7, 40, 470_100, 950_100, 0x5eed);
    alice.send_record(&step);
    assert_eq!(yankee.read_game(), relayed_move(&step, alpha.id, 0));
    let walk = client_move(1, 0, 0, 470_200, 950_200, 0x5eee);
    alice.send_record(&walk);
    assert_eq!(yankee.read_game(), relayed_move(&walk, alpha.id, 314));
    alice.quiet("the mover is still excluded");

    // The morph: the witness's add carries race 101.
    alice.send_record(&client_chat(CHAT_TALKING, b"/polymorph 101"));
    let add = read_add_of(&mut yankee, alpha.id);
    assert_eq!(
        u16::from_le_bytes(add[22..24].try_into().expect("two bytes")),
        101,
        "the shown race is the vnum"
    );
    let info = yankee.read_game();
    assert_eq!(info[0], GC_CHAR_ADDITIONAL_INFO, "{info:02x?}");
    assert_eq!(&info[1..5], &alpha.id.to_le_bytes(), "the pair's VID");

    // The same diagonal as the dog: 322 ms at 438.38 a second.
    let walk = client_move(1, 0, 0, 470_300, 950_300, 0x5eef);
    alice.send_record(&walk);
    assert_eq!(yankee.read_game(), relayed_move(&walk, alpha.id, 322));
}

/// Ledger 628: a mounted player moves at its mount's run clip. The quest mounts
/// Alpha on the boar (20201), MOV 140 with the band and the bonus; the (100,
/// 100) diagonal relays 134 ms, the boar's 743.49 scaled by MOV 140, not the
/// shaman's 314.
#[test]
fn a_mounted_player_moves_at_its_mounts_run_clip() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    let (server, _) = vein_stage(&database, MOUNT_PROBE);
    create_account(&server, "bob");
    sql(
        &database,
        "INSERT INTO player (account_id, slot, name, job, x, y) SELECT id, 0, 'Yankee', 1, \
         470000, 950000 FROM account WHERE login = 'bob'",
    );
    stamina(&database, "Yankee", 12_345);
    let (mut alice, _alpha, entered) = enter_equipped_world_with(&server, b"alice", 0);
    let vein = shown_vein(&entered);
    let vid = u32::from_le_bytes(entered.add[1..5].try_into().expect("four bytes"));
    let (mut yankee, yankee_listed) = enter_world_on_with_team(&server, 1, b"bob", 0, GERMAN, None);
    alice.sees_enter(yankee_listed.id, false, None);

    // A step lands exactly; the quest mounts the boar.
    let step = client_move(3, 7, 40, 470_100, 950_100, 0x5eed);
    alice.send_record(&step);
    assert_eq!(yankee.read_game(), relayed_move(&step, vid, 0));
    quest_mounts(&mut alice, vein, vid);
    // The mount's re-show reaches the witness too: the pair again, then one
    // update per affect row.
    let (_, remount, _) = yankee.sees_arrive(vid, false, None);
    for _ in 0..3 {
        let restate = yankee.read_game();
        assert_eq!(restate[0], GC_CHARACTER_UPDATE, "{restate:02x?}");
        assert_eq!(&restate[1..5], &vid.to_le_bytes(), "the update's VID");
    }
    assert_eq!(
        u16::from_le_bytes(remount[22..24].try_into().expect("two bytes")),
        3,
        "still the shaman"
    );

    // The diagonal mounted: 134 ms, the boar's clip under MOV 140.
    let walk = client_move(1, 0, 0, 470_200, 950_200, 0x5eee);
    alice.send_record(&walk);
    assert_eq!(yankee.read_game(), relayed_move(&walk, vid, 134));
}

/// Ledger 629: the morphed attacker's battle arms (`CalcMeleeDamage`'s polymorph arm,
/// `G/battle.cpp:527-541`, and `CalcAttackRating`'s `GetPolymorphPoint(POINT_DX)`,
/// `G/char.cpp:3673-3701`).
///
/// Alpha climbs skill 129 to 25 (power 41), takes `HIGH_WIZARD`, and morphs into the dog
/// 101 without keeping its stats. Its grades recompute to the morphed arm (attack 350:
/// twice level 154 plus twice polymorph-strength 21, the shaman adding its own IQ 20 to
/// the dog's 3 scaled by 41), and its rating reads attacker DX 21 (the dog's 6 scaled
/// by 41 plus its own 19). Its punch on the 406 it targets adds the dog's range,
/// 20..=24 scaled to 8..=9, so the damage lands 228 or 229, past the plain punch's
/// 213; the witness's stream proves the morph, and the target record proves the
/// boar's hit points moved by the same damage.
/// The morph reencode's drain for the morphed swing: the target click's answer, or
/// the caller's stale view row first — then its own morph add, its summary,
/// Yankee's walk and enter, and the map's NPC adds with their summaries and the
/// morph's grade records, until the target record lands.
fn drain_morph_reencode(alice: &mut Keyed, caller: u32, yankee: u32) -> Vec<u8> {
    let mut clicked = alice.read_game();
    if clicked[0] != GC_CHARACTER_DEL {
        return clicked;
    }
    assert_eq!(
        &clicked[1..5],
        &caller.to_le_bytes(),
        "the stale row is the caller's"
    );
    let own = alice.read_game();
    assert_eq!(own[0], GC_CHARACTER_ADD, "{own:02x?}");
    assert_eq!(
        u16::from_le_bytes(own[22..24].try_into().expect("two bytes")),
        101,
        "the own add is the morph"
    );
    let summary = alice.read_game();
    assert_eq!(summary[0], GC_CHAR_ADDITIONAL_INFO, "{summary:02x?}");
    assert_eq!(&summary[1..5], &caller.to_le_bytes(), "the summary's VID");
    let walk = alice.read_game();
    assert_eq!(walk[0], GC_WALK_MODE, "{walk:02x?}");
    assert_eq!(&walk[1..5], &yankee.to_le_bytes(), "the walker's VID");
    let (_named, _add, _info) = alice.sees_arrive(yankee, false, None);
    loop {
        let npc = alice.read_game();
        if npc[0] == GC_TARGET {
            clicked = npc;
            break;
        }
        if npc[0] == GC_POINT_CHANGE {
            continue;
        }
        assert_eq!(npc[0], GC_CHARACTER_ADD, "{npc:02x?}");
        let npc_info = alice.read_game();
        assert_eq!(npc_info[0], GC_CHAR_ADDITIONAL_INFO, "{npc_info:02x?}");
    }
    clicked
}

#[test]
fn a_morphed_attacker_adds_its_morphs_range_to_the_swing() {
    let Some(database) = ScratchDatabase::create() else {
        return;
    };
    create_account_before_boot(&database, "alice");
    create_account_before_boot(&database, "bob");
    add_characters(&database);
    sql(
        &database,
        "INSERT INTO player (account_id, slot, name, job, x, y) SELECT id, 0, 'Yankee', 1, \
         470200, 950200 FROM account WHERE login = 'bob'",
    );
    sql(
        &database,
        "INSERT INTO gm_grant (account_id, name, authority) SELECT id, 'Alpha', 'HIGH_WIZARD' \
         FROM account WHERE login = 'alice'",
    );
    sql(&database, "UPDATE account SET empire = 1");
    sql(
        &database,
        "INSERT INTO player_skill (player_id, vnum, level, next_read) SELECT id, 129, 25, 0 \
         FROM player WHERE name = 'Alpha'",
    );
    let server = Server::start_with_npcs_configured(
        binary(),
        database.url(),
        "metin2_map_a1",
        BOAR_AT_ALPHA,
        "no_wander = true",
    );
    let (mut alice, listed, _items) = load_character(&server, b"alice", 0);
    let entered = enter_game_shown(&mut alice);
    read_login_event(&mut alice);
    let boar = vid_shown_at(
        entered.shown.monsters.iter().map(Vec::as_slice),
        ALPHA_ENTERS_AT,
    );
    let (mut yankee, yankee_listed) =
        enter_world_on_with_team(&server, 1, b"bob", 0, GERMAN, Some(b"Alpha"));
    alice.sees_enter(yankee_listed.id, true, None);

    // The morph: the witness's add carries race 101.
    alice.send_record(&client_chat(CHAT_TALKING, b"/polymorph 101"));
    let add = read_add_of(&mut yankee, listed.id);
    assert_eq!(
        u16::from_le_bytes(add[22..24].try_into().expect("two bytes")),
        101,
        "the shown race is the vnum"
    );

    // When: the morphed Alpha punches the boar. Then: the damage carries the dog's
    // scaled range on the morphed grade 350 (`2*154 + 2*(3*41/100 + 20)`, the shaman's
    // own IQ): the 8..=9 roll lands 228 or 229, past the plain punch's 213. The
    // morph's reencode may still hold a stale view row of the caller, which leaves
    // before the click lands.
    alice.send_record(&client_target(boar));
    let clicked = drain_morph_reencode(&mut alice, listed.id, yankee_listed.id);
    assert_eq!(clicked[0], GC_TARGET, "{clicked:02x?}");
    alice.send_record(&client_attack(boar));
    let punch = alice.read_fight();
    assert_eq!(punch[0], GC_DAMAGE_INFO, "{punch:02x?}");
    assert_eq!(&punch[1..5], &boar.to_le_bytes(), "the boar's VID");
    let dealt = i32::from_le_bytes(punch[6..10].try_into().expect("four bytes"));
    assert!(
        (228..=229).contains(&dealt),
        "the morphed punch lands 228 or 229: {dealt}"
    );
    let shown = alice.read_fight();
    assert_eq!(shown[0], GC_TARGET, "{shown:02x?}");
    let boar_hp = i32::from_le_bytes(shown[6..10].try_into().expect("four bytes"));
    assert_eq!(
        boar_hp,
        1736 - dealt,
        "the punch's damage stays in the hit points"
    );
    drop(alice);
    drop(yankee);
    drop(server);
}
